INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'article-18459', '𝐉𝐎𝐁 𝐃𝐀𝐓𝐈𝐍𝐆 𝐀̀ 𝐋𝐀 𝐁𝐀𝐑𝐑𝐄', '𝐉𝐎𝐁 𝐃𝐀𝐓𝐈𝐍𝐆 𝐀̀ 𝐋𝐀 𝐁𝐀𝐑𝐑𝐄 !🆕💼 L’Hormadi s’associe à notre partenaire label Tekniaero ainsi qu’à France Travail pour l’organisation d’une après-midi job dating à la patinoire de la Barre le mardi 24 février prochain !🤝 Une découverte des métiers, des rencontres avec des employeurs, d', '<p>𝐉𝐎𝐁 𝐃𝐀𝐓𝐈𝐍𝐆 𝐀̀ 𝐋𝐀 𝐁𝐀𝐑𝐑𝐄 !🆕💼</p>
<p><img loading="lazy" decoding="async"  src="https://pro.hormadi.fr/wp-content/uploads/2026/02/Job-Dating-2402.jpg" alt="" width="268" height="358" srcset="https://pro.hormadi.fr/wp-content/uploads/2026/02/Job-Dating-2402.jpg 1080w, https://pro.hormadi.fr/wp-content/uploads/2026/02/Job-Dating-2402-225x300.jpg 225w, https://pro.hormadi.fr/wp-content/uploads/2026/02/Job-Dating-2402-768x1024.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2026/02/Job-Dating-2402-96x128.jpg 96w, https://pro.hormadi.fr/wp-content/uploads/2026/02/Job-Dating-2402-24x32.jpg 24w, https://pro.hormadi.fr/wp-content/uploads/2026/02/Job-Dating-2402-74x98.jpg 74w" sizes="auto, (max-width: 268px) 100vw, 268px" /></p>
<p>L’Hormadi s’associe à notre partenaire label Tekniaero ainsi qu’à France Travail pour l’organisation d’une après-midi job dating à la patinoire de la Barre le mardi 24 février prochain !🤝</p>
<p>Une découverte des métiers, des rencontres avec des employeurs, de 16h à 20h, l’occasion pour tous de se réunir autour de plusieurs secteurs d’activités !👀</p>
<p>➡️ Parce qu’un club de sport ne se limite pas au terrain et doit aussi s’engager socialement pour répondre aux besoins de ses partenaires et de son territoire, cet événement s’inscrit pleinement dans notre volonté d’agir concrètement pour l’emploi et l’insertion.💙</p>
<p>Plusieurs entreprises déjà présentes : Tekniaero, Etchart, Onet, Metro, Leroy Merlin, Celsa, Txik Txak, Ramsay Santé Clinique Belharra, À Lundi, TDS, LP Pro Sécurité, Vitalliance, Shiva, Domaine du Pignada… et bien d’autres encore !</p>
<p>🫡Inscrivez-vous : <a href="http://mesevenementsemploi.francetravail.fr/">mesevenementsemploi.francetravail.fr</a> / 05 59 46 30 01</p>
', 'Vie du Club', '/images/news/article-18459.png', true, '1771329262000', '1774831257801', '1774833441693');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'peter-morgan-debarque-a-la-barre', 'Peter MORGAN débarque à la Barre', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] L&rsquo;attaquant américain, 𝐏𝐞𝐭𝐞𝐫 𝐌𝐎𝐑𝐆𝐀𝐍 (), pose ses valises au Pays Basque ! Natif de Floride, 𝐏𝐞𝐭𝐞𝐫 arrive d&rsquo;East Coast du club des Gladiateurs d&rsquo;Atlanta, après avoir passé quatre dernière', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<div dir="ltr">
<div >
<div dir="auto">
<div >
<div dir="auto"></div>
</div>
<div >
<div dir="auto">L&rsquo;attaquant américain, 𝐏𝐞𝐭𝐞𝐫 𝐌𝐎𝐑𝐆𝐀𝐍 (<span ><img loading="lazy" decoding="async"  src="https://static.xx.fbcdn.net/images/emoji.php/v9/tf2/2/16/1f1fa_1f1f8.png" alt="🇺🇸" width="16" height="16" /></span>), pose ses valises au Pays Basque !<span ><img loading="lazy" decoding="async"  src="https://static.xx.fbcdn.net/images/emoji.php/v9/tef/2/16/1f525.png" alt="🔥" width="16" height="16" /></span></div>
</div>
<div >
<div dir="auto">Natif de Floride, 𝐏𝐞𝐭𝐞𝐫 arrive d&rsquo;East Coast du club des Gladiateurs d&rsquo;Atlanta, après avoir passé quatre dernières saisons en NCAA III, championnat universitaire américain, capitaine et meilleur pointeur (37 points) de sa formation de SUNY-Geneseo l’an dernier !<span ><img loading="lazy" decoding="async"  src="https://static.xx.fbcdn.net/images/emoji.php/v9/t18/2/16/1f44a.png" alt="👊" width="16" height="16" /></span></div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Il traverse pour la première fois l&rsquo;Atlantique et découvrira la Ligue Magnus sous nos couleurs avec le numéro 5, nous lui souhaitons la bienvenue à l&rsquo;Hormadi ! Le staff angloy met tout en œuvre actuellement pour que 𝐏𝐞𝐭𝐞𝐫 puisse être qualifié dès que possible.</div>
</div>
</div>
</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F484047%2Fpeter-morgan|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »18449&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q0ODQwNDclMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQ2MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/peter-morgan-debarque-a-la-barre.jpg', true, '1769068200000', '1774831258462', '1774833441699');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'lancement-de-notre-boutique-en-ligne', 'Lancement de notre boutique en ligne', '𝐋𝐀𝐍𝐂𝐄𝐌𝐄𝐍𝐓 𝐃𝐄 𝐍𝐎𝐓𝐑𝐄 𝐁𝐎𝐔𝐓𝐈𝐐𝐔𝐄 𝐄𝐍 𝐋𝐈𝐆𝐍𝐄 !🆕🚨 C&rsquo;est la grande nouveauté, venez profiter des offres de nos partenaires ! Notre boutique en ligne voit le jour avec l&rsquo;intégralité des produits textiles Hormadi by Pull In, des tenues Macron et des produits Promogla', '<p>𝐋𝐀𝐍𝐂𝐄𝐌𝐄𝐍𝐓 𝐃𝐄 𝐍𝐎𝐓𝐑𝐄 𝐁𝐎𝐔𝐓𝐈𝐐𝐔𝐄 𝐄𝐍 𝐋𝐈𝐆𝐍𝐄 !🆕🚨</p>
<p>C&rsquo;est la grande nouveauté<img loading="lazy" decoding="async"  src="https://pro.hormadi.fr/wp-content/uploads/2025/11/Boutique-en-ligne-visuel-min-225x300.png" alt="" width="358" height="477" srcset="https://pro.hormadi.fr/wp-content/uploads/2025/11/Boutique-en-ligne-visuel-min-225x300.png 225w, https://pro.hormadi.fr/wp-content/uploads/2025/11/Boutique-en-ligne-visuel-min-768x1024.png 768w, https://pro.hormadi.fr/wp-content/uploads/2025/11/Boutique-en-ligne-visuel-min-96x128.png 96w, https://pro.hormadi.fr/wp-content/uploads/2025/11/Boutique-en-ligne-visuel-min-24x32.png 24w, https://pro.hormadi.fr/wp-content/uploads/2025/11/Boutique-en-ligne-visuel-min-74x98.png 74w, https://pro.hormadi.fr/wp-content/uploads/2025/11/Boutique-en-ligne-visuel-min.png 1080w" sizes="auto, (max-width: 358px) 100vw, 358px" />, venez profiter des offres de nos partenaires ! Notre boutique en ligne voit le jour avec l&rsquo;intégralité des produits textiles Hormadi by Pull In, des tenues Macron et des produits Promoglace Bauer !😍</p>
<p>🔥Rendez-vous directement sur ce lien ci-joint pour découvrir notre catalogue : <a href="https://boutiques.hormadi.fr/">https://boutiques.hormadi.fr</a></p>
<p>🤌Par ailleurs, dès à présent, profitez de nos deux codes promos : « HORMADI15 » offrant 15% de réduction sur l&rsquo;ensemble du site Pull In et le code « HORMADIANGLET20 » offrant 20% de remise sur tous les produits Macron (jusqu&rsquo;à la fin du mois de novembre pour Macron) !🤩</p>
<p>Aucun doute que vous trouverez votre bonheur parmi notre sélection ! C&rsquo;est tout beau, tout frais, tout nouveau, alors foncez vous mettre aux couleurs de l&rsquo;Hormadi !💚❤️</p>
<p>👀Retrouvez les trois catalogues ici : <a href="https://boutiques.hormadi.fr/">https://boutiques.hormadi.fr</a></p>
<p>#GoHormadi | #JoTaKeIrabaziArte</p>
', 'Vie du Club', '/images/news/lancement-de-notre-boutique-en-ligne.png', true, '1763136022000', '1774831261814', '1774833441700');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'conference-de-presse-du-3110', 'Conférence de presse du 31/10', '[vc_row][vc_column][vc_single_image image= »18229&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_column_text css= » »] Ce vendredi 31 octobre 2025, l’Anglet Hormadi Pays Basque a organisé une conférence de presse avec pour sujet « une nouvelle pat', '<div ><p>[vc_row][vc_column][vc_single_image image= »18229&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_column_text css= » »]</p>
<p dir="ltr">Ce vendredi 31 octobre 2025, l’Anglet Hormadi Pays Basque a organisé une conférence de presse avec pour sujet « une nouvelle patinoire au Pays Basque », rassemblant sur place de nombreux médias.</p>
<p>En résumé, une réelle volonté des dirigeants angloys de créer <b>une nouvelle patinoire</b> pouvant accueillir <b>5.000 personnes</b>. Car effectivement, notre belle et chère patinoire de la Barre, construite en 1969, va rapidement devenir obsolète. Les 1.100 places assises ne seront plus suffisantes pour exister en Synerglace Ligue Magnus, l’élite du hockey sur glace français.</p>
<p>« À un moment donné, on va être au maximum de ce qu&rsquo;elle nous apporte », affirme au micro Olivier Bouney, le président de l&rsquo;Hormadi Anglet Pays Basque.</p>
<p>Quel projet ? A minima une infrastructure sportive double pistes (de 60&#215;30) et 5.000 places assises avec les réceptifs afférents, ou un modèle polyvalent de salle moderne (toujours double pistes) comme on en voit en Amérique du Nord. <b>Une salle polyvalente</b> qui pourrait accueillir du hockey sur glace un jour, puis se transformer pour le lendemain accueillir un autre sport en salle ou un spectacle culturel comme un concert, ou tout autre évènement.</p>
<p>Quel enjeu ? <b>Le développement du club</b> certes, dans un contexte où le hockey sur glace est de plus en plus populaire en France. Les clubs de Nice, Rouen ou encore Dunkerque ont des projets en cours pour des infrastructures ambitieuses, alors pourquoi pas l’Hormadi ? Mais c’est aussi <b>un enjeu de territoire pour le grand sud-ouest</b> qui souffre d’un déficit évident, que ce soit de patinoire ou de salle de spectacle moderne.</p>
<p>« En 1968, la France a eu les J.O. En 1969, on a eu la patinoire de la Barre. Ça a été fait une fois donc pourquoi pas l&rsquo;avoir en 2031&Prime;, conclut Olivier Bouney, le président de l&rsquo;Hormadi.</p>
<p>Retrouvez ci-dessous les différents articles de presse résumant cette conférence de presse…[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text css= » »]Article Sud-Ouest : <a href="https://www.sudouest.fr/sport/hockey-sur-glace/hormadi-anglet/pays-basque-a-moyen-terme-l-hormadi-ne-pourra-pas-survivre-s-il-n-y-a-pas-un-projet-de-patinoire-26546835.php" target="_blank" rel="noopener">https://www.sudouest.fr/sport/hockey-sur-glace/hormadi-anglet/pays-basque-a-moyen-terme-l-hormadi-ne-pourra-pas-survivre-s-il-n-y-a-pas-un-projet-de-patinoire-26546835.php</a></p>
<p>Article France Bleu Pays-Basque : <a href="https://www.francebleu.fr/sports/tous-les-sports/hockey-sur-glace-une-nouvelle-patinoire-a-terme-on-ne-pourra-pas-survivre-sans-affirme-l-anglet-hormadi-9971598" target="_blank" rel="noopener">https://www.francebleu.fr/sports/tous-les-sports/hockey-sur-glace-une-nouvelle-patinoire-a-terme-on-ne-pourra-pas-survivre-sans-affirme-l-anglet-hormadi-9971598</a></p>
<p>[/vc_column_text][/vc_column][/vc_row]</p>
</div>', 'Vie du Club', '/images/news/conference-de-presse-du-3110.jpeg', true, '1761948028000', '1774831262998', '1774833441701');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-matthew-sredl', 'Arrivée de Matthew SREDL', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] Le solide défenseur américain, 𝐌𝐚𝐭𝐭𝐡𝐞𝐰 𝐒𝐑𝐄𝐃𝐋 (🇺🇸), pose ses valises à l&rsquo;Hormadi !🔥 Du haut de ses 1.85m et 91 kg, ce défenseur droitier possède déjà une expérience conséquente à seulement 23 ans, ave', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<div dir="ltr">
<div >
<div dir="auto">
<p>Le solide défenseur américain, 𝐌𝐚𝐭𝐭𝐡𝐞𝐰 𝐒𝐑𝐄𝐃𝐋 (🇺🇸), pose ses valises à l&rsquo;Hormadi !🔥</p>
<p>Du haut de ses 1.85m et 91 kg, ce défenseur droitier possède déjà une expérience conséquente à seulement 23 ans, avec des passages en East Coast et en AHL.🫡</p>
<p>🇪🇺Mais surtout en Europe où il a évolué du côté de l&rsquo;Extraliga Tchèque à Vitkovice (🇨🇿), de l&rsquo;Extraliga Slovaque au HC 19 Humenné (🇸🇰), et également à Lillehammer au plus au niveau norvégien (🇳🇴). L&rsquo;an dernier, 𝐌𝐚𝐭𝐭𝐡𝐞𝐰 avait terminé sa saison du côté de la DEL2, le second échelon allemand (🇩🇪), chez les Blue Devils de Weiden !👊</p>
<p>Il arrive désormais à la Barre pour cette saison, renforçant la ligne bleue basque ! Le staff angloy met tout en œuvre actuellement pour que le natif du Michigan puisse être qualifié dès vendredi soir contre Chamonix !⏳</p>
<p>Nous sommes ravis de l&rsquo;accueillir à la Barre et nous lui souhaitons la bienvenue à l&rsquo;Hormadi !🤝</p>
<p>𝐎𝐧𝐠𝐢 𝐄𝐭𝐨𝐫𝐫𝐢 𝐒𝐡𝐫𝐞𝐝𝐳 !💚❤️</p>
</div>
</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F417494%2Fmatthew-sredl|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »18176&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q0MTc0OTQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQ2MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-matthew-sredl.jpg', true, '1759831221000', '1774831264145', '1774833441702');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'matchs-de-preparation-2025-2026', 'Matchs de préparation 2025 – 2026', '[vc_row][vc_column][vc_column_text css= » »] 𝐋𝐞 𝐜𝐚𝐥𝐞𝐧𝐝𝐫𝐢𝐞𝐫 𝐝𝐞 𝐥𝐚 𝐩𝐫𝐞́𝐩𝐚 Alors que le camp d’entraînement débutera le lundi 11 août, découvrez les quatre matchs de préparation de nos Angloys avant la reprise du championnat le 12 septembre ! Au programme, 𝐭𝐫𝐨𝐢𝐬 𝐫𝐞𝐧𝐜𝐨𝐧𝐭', '<div ><p>[vc_row][vc_column][vc_column_text css= » »]</p>
<div >
<div dir="auto">
<div >
<div dir="auto">𝐋𝐞 𝐜𝐚𝐥𝐞𝐧𝐝𝐫𝐢𝐞𝐫 𝐝𝐞 𝐥𝐚 𝐩𝐫𝐞́𝐩𝐚</div>
</div>
<div >
<div dir="auto">Alors que le camp d’entraînement débutera le lundi 11 août, découvrez les quatre matchs de préparation de nos Angloys avant la reprise du championnat le 12 septembre !</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Au programme, 𝐭𝐫𝐨𝐢𝐬 𝐫𝐞𝐧𝐜𝐨𝐧𝐭𝐫𝐞𝐬 𝐚𝐦𝐢𝐜𝐚𝐥𝐞𝐬 à la Barre, tout d&rsquo;abord face aux <span ><a  tabindex="0" role="link" href="https://www.facebook.com/boxersbordeaux?__cft__[0]=AZXa9yT7dsHN1XKILind98AwCcOjmkNtEwQX-A1BIzkTqA6qJXAXoJDgQyrUV3CpBKMvO2G4U5Zu4diBKNlgVAAmL-JY505-7RTOeiTBw1L2fIo71pSPYMcgZcSU1kw7fw7TfoMYmz_5N0y29H8aWiKQQoNSIdX0N0hbLrX3Ey1Yp1IPTpAIfh7fhx592UaQMTErY29P30p13pgUzIDh4Hy3&amp;__tn__=-]K-R"><span ><span >Boxers de Bordeaux</span></span></a></span> le vendredi 22 août à 20h00, puis un back to back contre <span ><a  tabindex="0" role="link" href="https://www.facebook.com/DiablesRougesBriancon?__cft__[0]=AZXa9yT7dsHN1XKILind98AwCcOjmkNtEwQX-A1BIzkTqA6qJXAXoJDgQyrUV3CpBKMvO2G4U5Zu4diBKNlgVAAmL-JY505-7RTOeiTBw1L2fIo71pSPYMcgZcSU1kw7fw7TfoMYmz_5N0y29H8aWiKQQoNSIdX0N0hbLrX3Ey1Yp1IPTpAIfh7fhx592UaQMTErY29P30p13pgUzIDh4Hy3&amp;__tn__=-]K-R"><span ><span >Les Diables Rouges Hockey Briançon</span></span></a></span> le week-end suivant à 18h30 !</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Entre-temps, les hommes de Stéphane Barin iront à Mériadeck pour une manche retour face aux Bordelais le dimanche 24 août.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">La billetterie en ligne sera prochainement ouverte ! Tous les matchs de préparation sont inclus dans l’abonnement, alors si ce n’est pas déjà fait, abonnez-vous, toutes les informations sont ici : <span ><a  tabindex="0" role="link" href="https://pro.hormadi.fr/abonnement/?fbclid=IwZXh0bgNhZW0CMTAAYnJpZBEwajJodHB2bTdPQUhUcHVEdwEeIu5T7aFJdYQqC3YmyZehXB8IV9NPcmkUjykchQWn-gtBdbmMMD1tf8VRXuI_aem_r_R7rcDPv94GBaGECjPrEA" target="_blank" rel="nofollow noopener noreferrer">https://pro.hormadi.fr/abonnement/</a></span></div>
</div>
</div>
</div>
<p>[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_btn title= »Visualisez les matchs » align= »center » i_icon_fontawesome= »fas fa-eye » css= » » add_icon= »true » link= »url:https%3A%2F%2Fpro.hormadi.fr%2Fcalendar%2Fpreparation-24-26%2F|title:Match%20de%20pr%C3%A9pa%202025|target:_blank »][/vc_column][/vc_row]</p>
</div>', 'Vie du Club', '/images/news/matchs-de-preparation-2025-2026.jpg', true, '1751875242000', '1774831266331', '1774833441703');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'calendrier-2025-2026', 'Calendrier 2025 – 2026', '[vc_row][vc_column][vc_column_text css= » »] 𝐂𝐡𝐞𝐫𝐬 𝐬𝐮𝐩𝐩𝐨𝐫𝐭𝐞𝐫𝐬, 𝐚̀ 𝐯𝐨𝐬 𝐚𝐠𝐞𝐧𝐝𝐚𝐬 ! Il est enfin là, tout fraîchement sorti ! Voici notre calendrier de cette nouvelle saison 2025/2026 de Synerglace Ligue Magnus ! Nos Angloys commenceront cet exercice par un déplacement chez les', '<div ><p>[vc_row][vc_column][vc_column_text css= » »]</p>
<div >
<div dir="auto">𝐂𝐡𝐞𝐫𝐬 𝐬𝐮𝐩𝐩𝐨𝐫𝐭𝐞𝐫𝐬, 𝐚̀ 𝐯𝐨𝐬 𝐚𝐠𝐞𝐧𝐝𝐚𝐬 !</div>
</div>
<div >
<div dir="auto"></div>
<div dir="auto">Il est enfin là, tout fraîchement sorti ! Voici notre calendrier de cette nouvelle saison 2025/2026 de <span ><a  tabindex="0" role="link" href="https://www.facebook.com/liguemagnus?__cft__[0]=AZU6BN1VtM_Fzzus2BVA9K6eI2qNodMMJbBwGie8HpgiroZWH47aTCFfwkQMS272ulm4o9qE1z8THwMamqKEjTpnaODx0eFH_w20N8a3I1TLUG_UL55cqncy2ZMCtdVtFhgKpm6SLXUQyUw1QJH_V8jUCIL7y_J1sswV9tKDvm4M3Lw_30A0-pXrFQr_xY2C4ugzje_fsY0Rmtot1dht5rI4&amp;__tn__=-]K-R"><span ><span >Synerglace Ligue Magnus</span></span></a></span> !<span ><br />
</span></div>
</div>
<div >
<div dir="auto">Nos Angloys commenceront cet exercice par un déplacement chez les <span ><a  tabindex="0" role="link" href="https://www.facebook.com/SpartiatesdeMarseille?__cft__[0]=AZU6BN1VtM_Fzzus2BVA9K6eI2qNodMMJbBwGie8HpgiroZWH47aTCFfwkQMS272ulm4o9qE1z8THwMamqKEjTpnaODx0eFH_w20N8a3I1TLUG_UL55cqncy2ZMCtdVtFhgKpm6SLXUQyUw1QJH_V8jUCIL7y_J1sswV9tKDvm4M3Lw_30A0-pXrFQr_xY2C4ugzje_fsY0Rmtot1dht5rI4&amp;__tn__=-]K-R"><span ><span >Spartiates de Marseille</span></span></a></span> le vendredi 12 septembre. Le premier match au chaudron de la Barre lui, aura lieu le mardi 16 septembre contre <span ><a  tabindex="0" role="link" href="https://www.facebook.com/Infosjokers?__cft__[0]=AZU6BN1VtM_Fzzus2BVA9K6eI2qNodMMJbBwGie8HpgiroZWH47aTCFfwkQMS272ulm4o9qE1z8THwMamqKEjTpnaODx0eFH_w20N8a3I1TLUG_UL55cqncy2ZMCtdVtFhgKpm6SLXUQyUw1QJH_V8jUCIL7y_J1sswV9tKDvm4M3Lw_30A0-pXrFQr_xY2C4ugzje_fsY0Rmtot1dht5rI4&amp;__tn__=-]K-R"><span ><span >Les Jokers de Cergy-Pontoise</span></span></a></span> !<span ><br />
</span></div>
</div>
<div >
<div dir="auto">Nous clôturerons la saison régulière début mars par deux réceptions, quant aux deux derbys du Sud Ouest à domicile face à nos voisins bordelais, ils sont programmés le mardi 30 septembre et le vendredi 27 février !<span ><br />
</span></div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">
<p>Bref, encore une saison forte en émotions qui arrive dans quelques mois, prenez bien note de toutes les dates, et n&rsquo;oubliez pas de vous abonner dès maintenant pour bénéficier des nombreux avantages durant la saison : <span ><a  tabindex="0" role="link" href="https://pro.hormadi.fr/abonnement/?fbclid=IwZXh0bgNhZW0CMTAAYnJpZBEwajJodHB2bTdPQUhUcHVEdwEe_6xp7XzOOVdRIEbOy-SlI2XFHE-8vBJnSwlMnlRVLurA7HNY5lya5sywWpY_aem_KK195_LJxksGUcu4WVbhBA" target="_blank" rel="nofollow noopener noreferrer">https://pro.hormadi.fr/abonnement/</a></span></p>
<p>&nbsp;</p>
</div>
</div>
<div >
<div dir="auto">Rendez-vous le 12 septembre prochain !</div>
</div>
<p>[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width= »1/2&Prime;][vc_btn title= »Voir le calendrier d&rsquo;Anglet » align= »center » i_icon_fontawesome= »fas fa-eye » css= » » add_icon= »true » link= »url:https%3A%2F%2Fpro.hormadi.fr%2Fcalendar%2Fcalendrier-2025-2026%2F|title:Calendrier%202025%20%E2%80%93%202026|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_btn title= »Télécharger le calendrier » align= »center » i_icon_fontawesome= »fas fa-download » css= » » add_icon= »true » link= »url:https%3A%2F%2Fpro.hormadi.fr%2Fwp-content%2Fuploads%2F2025%2F07%2FCalendrier-SLM-2025-VF.pdf|target:_blank »][/vc_column][/vc_row]</p>
</div>', 'Vie du Club', '/images/news/calendrier-2025-2026.jpeg', true, '1751448438000', '1774831266662', '1774833441704');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-jake-gagnon', 'Arrivée de Jake GAGNON', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] 𝐆𝐚𝐠𝐧𝐨𝐧 𝐜𝐨𝐦𝐩𝐥𝐞̀𝐭𝐞 𝐥&rsquo;𝐨𝐟𝐟𝐞𝐧𝐬𝐢𝐯𝐞 !✍️🚨 Quasiment né en plein cœur de Montréal, à Pointe-Claire plus exactement, l&rsquo;ailier droit canadien de 25 ans, 𝐉𝐚𝐤𝐞 𝐆𝐀𝐆𝐍𝐎𝐍 (🇨🇦), pose ses va', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<div dir="ltr">
<p>𝐆𝐚𝐠𝐧𝐨𝐧 𝐜𝐨𝐦𝐩𝐥𝐞̀𝐭𝐞 𝐥&rsquo;𝐨𝐟𝐟𝐞𝐧𝐬𝐢𝐯𝐞 !✍️🚨</p>
<p>Quasiment né en plein cœur de Montréal, à Pointe-Claire plus exactement, l&rsquo;ailier droit canadien de 25 ans, 𝐉𝐚𝐤𝐞 𝐆𝐀𝐆𝐍𝐎𝐍 (🇨🇦), pose ses valises à la Barre à la rentrée prochaine !🔥</p>
<p>Ce francophone évoluait lui aussi depuis 5 saisons en NCAA, au sein des Engineers RPI, université américaine située non loin de New York aux États-Unis, où il en était d&rsquo;ailleurs le capitaine depuis deux saisons !👊</p>
<p>Un profil atypique pour l&rsquo;offensive basque de Stéphane Barin et Mathieu Cyr, très gros travailleur et bon patineur avec une énergie sans relâche, 𝐉𝐚𝐤𝐞 saura sans aucun doute se démarquer sur le glaçon de par son style !💪</p>
<p>Avec son arrivée, il vient renforcer encore un peu plus notre attaque et la compléter, nous sommes ravis de pouvoir l&rsquo;accueillir ici au Pays Basque pour sa première aventure en Europe, nous lui souhaitons la bienvenue et un très bel été avant de le retrouver début août !🤝😉</p>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F499131%2Fjake-gagnon|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17992&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q0OTkxMzElMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjI5NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-jake-gagnon.jpg', true, '1750863601000', '1774831267118', '1774833441705');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), '150-abonnes-en-10-jours', '150 abonnés en 10 jours', '[vc_row][vc_column][vc_single_image image= »17987&Prime; img_size= »full » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_column_text css= » »] L&rsquo;Hormadi ne perdra jamais sa ferveur ! Déjà 150 abonnés inscrits en seulement dix jours pour la future saison qui démarre ', '<div ><p>[vc_row][vc_column][vc_single_image image= »17987&Prime; img_size= »full » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_column_text css= » »]</p>
<div >
<div dir="auto">
<p>L&rsquo;Hormadi ne perdra jamais sa ferveur ! Déjà 150 abonnés inscrits en seulement dix jours pour la future saison qui démarre dans quelques mois à la Barre !🤩</p>
<p>🫡L&rsquo;engouement est bel et bien présent sur ce début de campagne d&rsquo;abonnement, et ce n&rsquo;est pas fini ! Le formulaire d&rsquo;inscription ainsi que les informations concernant l&rsquo;abonnement, c&rsquo;est directement sur notre site internet dans l’onglet billetterie puis abonnement.</p>
<p>Si ce n&rsquo;est pas déjà fait, venez nous voir au bureau de l&rsquo;AHPB pour faire vous aussi partie de cette nouvelle aventure, vous avez jusqu&rsquo;au 15 août pour réserver votre abonnement. Le lundi, mardi, jeudi et vendredi de 9h30 à 12h et de 14h30 à 18h à la patinoire de la Barre !🚨</p>
<p>On vous attend encore 𝐍𝐎𝐌𝐁𝐑𝐄𝐔𝐗 !💚❤️</p>
</div>
</div>
<p>[/vc_column_text][/vc_column][/vc_row]</p>
</div>', 'Vie du Club', '/images/news/150-abonnes-en-10-jours.jpg', true, '1750345255000', '1774831267590', '1774833441706');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-samuel-duerr', 'Arrivée de Samuel DUERR', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] 𝐃𝐮𝐞𝐫𝐫 𝐫𝐞𝐧𝐟𝐨𝐫𝐜𝐞 𝐥𝐚 𝐝𝐞́𝐟𝐞𝐧𝐬𝐞 !✍️🚨 Une première signature à la ligne bleue, il arrive tout droit de l&rsquo;Université de Bentley en NCAA, le robuste défenseur américain de 23 ans, 𝐒𝐚𝐦𝐮𝐞𝐥 𝐃𝐔𝐄', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<div dir="ltr">
<p dir="ltr">𝐃𝐮𝐞𝐫𝐫 𝐫𝐞𝐧𝐟𝐨𝐫𝐜𝐞 𝐥𝐚 𝐝𝐞́𝐟𝐞𝐧𝐬𝐞 !✍️🚨</p>
<p>Une première signature à la ligne bleue, il arrive tout droit de l&rsquo;Université de Bentley en NCAA, le robuste défenseur américain de 23 ans, 𝐒𝐚𝐦𝐮𝐞𝐥 𝐃𝐔𝐄𝐑𝐑 (🇺🇸), connaîtra sa première expérience européenne sous les couleurs de l&rsquo;Hormadi la saison prochaine !😍</p>
<p>Né à Chicago, 𝐒𝐚𝐦𝐮𝐞𝐥 évoluait lors de ses quatre dernières saisons en NCAA, la meilleure ligue universitaire des États-Unis. D&rsquo;abord à Maine puis à Bentley, où il aura remporté un titre la saison dernière, celui de NCAA (AHA), la conférence Atlantique de NCAA. Il a d&rsquo;ailleurs affronté un certain&#8230; Mathieu Caron !👀</p>
<p>Ce défenseur gaucher imposant du haut de ses 1.88m et 86kg, qui a notamment participé à un camp d&rsquo;été en 2023 avec les Red Wings de Détroit, apportera sans aucun doute de la robustesse à la défensive basque.💪</p>
<p>Nous sommes ravis de pouvoir l&rsquo;accueillir ici à la Barre, en attendant de le retrouver début août, nous lui souhaitons un excellent été !😁</p>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F418239%2Fsamuel-duerr|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17968&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q0MTgyMzklMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjMyNSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-samuel-duerr.jpg', true, '1749318781000', '1774831268041', '1774833441707');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-dominik-volejnicek', 'Arrivée de Dominik VOLEJNICEK', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] 𝐔𝐧 𝐇𝐞𝐥𝐯𝐞̀𝐭𝐞 𝐭𝐫𝐚𝐯𝐞𝐫𝐬𝐞 𝐥𝐚 𝐟𝐫𝐨𝐧𝐭𝐢𝐞̀𝐫𝐞 !✍️🚨 Nous sommes heureux de vous annoncer aujourd&rsquo;hui l&rsquo;arrivée de l&rsquo;attaquant suisse de 27 ans, 𝐃𝐨𝐦𝐢𝐧𝐢𝐤 𝐕𝐎𝐋𝐄𝐉𝐍𝐈́𝐂̌𝐄𝐊 (🇨', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<div dir="ltr">𝐔𝐧 𝐇𝐞𝐥𝐯𝐞̀𝐭𝐞 𝐭𝐫𝐚𝐯𝐞𝐫𝐬𝐞 𝐥𝐚 𝐟𝐫𝐨𝐧𝐭𝐢𝐞̀𝐫𝐞 !✍️🚨</div>
<div  dir="ltr"></div>
<div  dir="ltr">Nous sommes heureux de vous annoncer aujourd&rsquo;hui l&rsquo;arrivée de l&rsquo;attaquant suisse de 27 ans, 𝐃𝐨𝐦𝐢𝐧𝐢𝐤 𝐕𝐎𝐋𝐄𝐉𝐍𝐈́𝐂̌𝐄𝐊 (🇨🇭🇨🇿), en provenance du HC Sierre, club de Swiss League, le solide second échelon suisse !🔥</div>
<div  dir="ltr"></div>
<div  dir="ltr">Né entre Lucerne et le lac de Zoug, formé au réputé club du EV Zug, 𝐃𝐨𝐦𝐢 possède aussi la nationalité tchèque via son père, mais il sera officiellement le premier joueur suisse à évoluer sous les couleurs de l&rsquo;Hormadi la saison prochaine !😍</div>
<div  dir="ltr"></div>
<div  dir="ltr">Un ailier au sens du but, en démontre ses cinq dernières saisons en SL, toujours régulier dans ses performances dans un championnat relevé ! Il aura aussi goûté au très haut niveau suisse, sous les couleurs de Lausanne et de Zoug entre 2018 et 2021, également ancien international U20, U18, U17 et U16 avec la Nati, et passé aussi plus jeune, par la Suède et Malmö.💪</div>
<div  dir="ltr"></div>
<div  dir="ltr">Aujourd&rsquo;hui, à tout juste 27 ans (depuis quelques jours), 𝐃𝐨𝐦𝐢 s&rsquo;apprête à découvrir le championnat voisin, la Synerglace Ligue Magnus sous nos couleurs, nous sommes très satisfaits de le voir débarquer à la Barre pour cette nouvelle aventure hors de son pays natal !🤩</div>
<div dir="ltr"></div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F220971%2Fdominik-volejnicek|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17948&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyMjA5NzElMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjg1MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBBJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-dominik-volejnicek.png', true, '1748877697000', '1774831271222', '1774833441708');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-samuel-dunn', 'Départ de Samuel DUNN', '[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »] Après 99 matchs fièrement disputés sous les couleurs de l&rsquo;Hormadi, nous vous annonçons aujourd&rsquo;hui le départ de notre robuste défenseur canadien, 𝐒𝐚𝐦𝐮𝐞𝐥 𝐃𝐔𝐍𝐍 (🇨🇦), qui ne fera plus partie de l&rsquo;effectif angl', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »]</p>
<div >
<div dir="auto">
<p>Après 99 matchs fièrement disputés sous les couleurs de l&rsquo;Hormadi, nous vous annonçons aujourd&rsquo;hui le départ de notre robuste défenseur canadien, 𝐒𝐚𝐦𝐮𝐞𝐥 𝐃𝐔𝐍𝐍 (🇨🇦), qui ne fera plus partie de l&rsquo;effectif angloy à la rentrée prochaine.👋</p>
<p>Arrivé lui aussi à l&rsquo;été 2023 sur la côte basque, 𝐃𝐮𝐧𝐧𝐞𝐫 n&rsquo;aura jamais triché avec notre maillot, assistant capitaine également la saison dernière, il aura contribué au développement de ce jeune groupe en apportant tout son sérieux et son professionnalisme !🤝</p>
<p>Nous tenions à sincèrement le remercier pour ces deux saisons passées à la Barre, et nous lui souhaitons désormais bonne chance pour la suite de sa carrière !🫡</p>
</div>
</div>
<p>[/vc_column_text][/vc_column][vc_column width= »1/4&Prime;][vc_single_image image= »17943&Prime; img_size= »medium » alignment= »center » css= » »][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-samuel-dunn.jpg', true, '1748846892000', '1774831271446', '1774833441709');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-craig-puffer', 'Départ de Craig PUFFER', '[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »] Il aura marqué de son empreinte son passage à l&rsquo;Hormadi, mais aujourd&rsquo;hui il est temps pour lui de s&rsquo;envoler vers un nouveau challenge, notre attaquant américain et n°7️⃣1️⃣, 𝐂𝐫𝐚𝐢𝐠 𝐏𝐔𝐅𝐅𝐄𝐑 (🇺🇸), ne fera plu', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »]</p>
<div >
<div dir="auto">
<p>Il aura marqué de son empreinte son passage à l&rsquo;Hormadi, mais aujourd&rsquo;hui il est temps pour lui de s&rsquo;envoler vers un nouveau challenge, notre attaquant américain et n°7️⃣1️⃣, 𝐂𝐫𝐚𝐢𝐠 𝐏𝐔𝐅𝐅𝐄𝐑 (🇺🇸), ne fera plus partie de l&rsquo;effectif la saison prochaine.</p>
<p>Arrivé il y a deux saisons au Pays Basque, 𝐏𝐮𝐟𝐟𝐲 aura de suite démontrer tout son panel offensif, faisant de lui le Top Scorer de l&rsquo;Hormadi lors de sa première saison, en étant également le second meilleur buteur du championnat. Un deuxième chapitre tout aussi satisfaisant, au total, 𝐏𝐮𝐟𝐟𝐲 aura inscrit pas moins de 88 points en 93 parties disputées sous notre maillot !🤯</p>
<p>L&rsquo;ensemble du club tient à le remercier comme il se doit pour ces deux belles années passées à la Barre, un joueur talentueux et une personne attachante qui nous quitte, désormais, nous lui souhaitons tout le meilleur pour la suite de sa carrière !🫶</p>
</div>
</div>
<p>[/vc_column_text][/vc_column][vc_column width= »1/4&Prime;][vc_single_image image= »17940&Prime; img_size= »medium » alignment= »center » css= » »][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-craig-puffer.jpg', true, '1748846801000', '1774831271765', '1774833441709');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'retraite-sportive-de-vincent-deslauriers', 'Retraite sportive de Vincent DESLAURIERS', '[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »] Tout jeune papa depuis quelques semaines maintenant, après la naissance de son petit garçon 𝙉𝙤𝙝𝙖𝙣 𝘼𝙡𝙚𝙭, notre attaquant québécois de 28 ans, 𝐕𝐢𝐧𝐜𝐞𝐧𝐭 𝐃𝐄𝐒𝐋𝐀𝐔𝐑𝐈𝐄𝐑𝐒 (🇨🇦), a décidé de mettre un terme à sa carrièr', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »]</p>
<div >
<div dir="auto">
<p>Tout jeune papa depuis quelques semaines maintenant, après la naissance de son petit garçon 𝙉𝙤𝙝𝙖𝙣 𝘼𝙡𝙚𝙭, notre attaquant québécois de 28 ans, 𝐕𝐢𝐧𝐜𝐞𝐧𝐭 𝐃𝐄𝐒𝐋𝐀𝐔𝐑𝐈𝐄𝐑𝐒 (🇨🇦), a décidé de mettre un terme à sa carrière professionnelle pour se consacrer pleinement à sa nouvelle petite vie de famille !🥹</p>
<p>Arrivé en provenance de Moncton à l&rsquo;été 2023, 𝐃𝐞𝐬𝐥𝐚𝐮 aura passé deux belles saisons à la Barre, auteur de 67 points en 102 rencontres disputées, notre n°2️⃣1️⃣ aura été l&rsquo;un des hommes forts de l&rsquo;offensive angloye durant son passage. Une personne tout aussi attachante en dehors de la glace de par son professionnalisme, sa gentillesse et surtout son sourire que personne n&rsquo;oubliera, tout cela restera gravé ici à l&rsquo;Hormadi !🤝</p>
<p>Nous tenons à souhaiter à 𝐃𝐞𝐬𝐥𝐚𝐮 mais également à sa compagne Pascale, tout le meilleur pour la suite ! Un grand merci à toi 𝐕𝐢𝐧𝐜𝐞𝐧𝐭 pour ces deux années à nos côtés, tu seras évidemment toujours le bienvenu ici au Pays Basque !🫶</p>
</div>
</div>
<p>[/vc_column_text][/vc_column][vc_column width= »1/4&Prime;][vc_single_image image= »17932&Prime; img_size= »medium » alignment= »center » css= » »][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/retraite-sportive-de-vincent-deslauriers.jpg', true, '1748271617000', '1774831272830', '1774833441710');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-alexander-khovanov', 'Arrivée de Alexander KHOVANOV', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]Vous êtes prêts à apprendre le russe ?😁 Le 86e choix (3e tour) au total de la draft NHL de 2018, repêché par le Wild du Minnesota, 𝐀𝐥𝐞𝐱𝐚𝐧𝐝𝐞𝐫 𝐊𝐇𝐎𝐕𝐀𝐍𝐎𝐕 (🇷🇺), pose ses valises à l’Hormadi dès la rentrée p', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]Vous êtes prêts à apprendre le russe ?😁</p>
<p>Le 86e choix (3e tour) au total de la draft NHL de 2018, repêché par le Wild du Minnesota, 𝐀𝐥𝐞𝐱𝐚𝐧𝐝𝐞𝐫 𝐊𝐇𝐎𝐕𝐀𝐍𝐎𝐕 (🇷🇺), pose ses valises à l’Hormadi dès la rentrée prochaine !🔥</p>
<p>International russe U20, U18 et U17 notamment, passé dès son plus jeune âge par les prestigieuses ligues de la KHL et l’AHL, ce gros espoir russe avait totalement dominé la LHJMQ, la meilleure ligue junior du Canada, entre ces 17 et 20 ans pour s’offrir le luxe en 2018 d’être repêché par la franchise du Wild.😍</p>
<p>Poursuivant son évolution du côté de Kazan, il aura ensuite goûté au haut niveau nord-américain avec l’Iowa Wild (AHL) et l’Iowa Heartlanders (ECHL), avant de revenir à Kazan puis à Tambov dans la VHL, le second échelon russe !👊</p>
<p>Il nous provient tout droit de Biélorussie, où il aura été champion national avec le Metallurg Zhlobin la saison dernière, un premier titre pour celui qui avait été vice-champion du monde U20 en 2020. Un profil atypique, qui arrive à la Barre pour démontrer tout son talent offensif que nous avons hâte de découvrir !👀</p>
<p>𝐊𝐨𝐯𝐲, on te souhaite la bienvenue à l’Hormadi, à très vite !🤝[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F339559%2Falexander-khovanov|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17925&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzMzk1NTklMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjUzNSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-alexander-khovanov.jpg', true, '1748245575000', '1774831274206', '1774833441711');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-jamie-eyre', 'Prolongation de Jamie EYRE', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] Une nouvelle confirmation en défense, celle de 𝐉𝐚𝐦𝐞𝐬 𝐄𝐘𝐑𝐄 (🇫🇷🇬🇧), qui arborera le chandail basque pour une seconde saison dès la rentrée prochaine !🔥 Arrivé l’été dernier des États-Unis, 𝐉𝐢𝐦 a été auteur', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<p dir="ltr">Une nouvelle confirmation en défense, celle de 𝐉𝐚𝐦𝐞𝐬 𝐄𝐘𝐑𝐄 (🇫🇷🇬🇧), qui arborera le chandail basque pour une seconde saison dès la rentrée prochaine !🔥</p>
<p>Arrivé l’été dernier des États-Unis, 𝐉𝐢𝐦 a été auteur d’une première saison convaincante en Synerglace Ligue Magnus avec notamment ses trois premiers buts, démontrant aussi tout son potentiel sur la glace, lui qui avait été élu meilleur défenseur des championnats du monde U20 D1A en 2024 !👊</p>
<p>C’est avec beaucoup de satisfaction que nous le conservons au sein de l’effectif angloy, nous lui souhaitons de passer un très bel été, et nous lui donnons rendez-vous dès le mois d’août à la Barre !💚❤️</p>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F620534%2Fjamie-eyre|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17920&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q2MjA1MzQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQ2MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-jamie-eyre.jpg', true, '1747918269000', '1774831275221', '1774833441711');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'retour-de-anton-vasilyev', 'Retour de Anton VASILYEV', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]Un retour, et pas des moindres, vous avez été nombreux à le réclamer, il est là ! Le brillant attaquant russe de 26 ans, 𝐀𝐧𝐭𝐨𝐧 𝐕𝐀𝐒𝐈𝐋𝐘𝐄𝐕 (🇷🇺), fait son retour à l’Hormadi la saison prochaine !😍 On ne vous l', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]Un retour, et pas des moindres, vous avez été nombreux à le réclamer, il est là ! Le brillant attaquant russe de 26 ans, 𝐀𝐧𝐭𝐨𝐧 𝐕𝐀𝐒𝐈𝐋𝐘𝐄𝐕 (🇷🇺), fait son retour à l’Hormadi la saison prochaine !😍</p>
<p>On ne vous le présente plus tant il aura marqué de par son talent les esprits de tous ici à la Barre durant son passage entre 2022 et 2024, auteur de 74 points en 76 matchs disputés sous les couleurs angloyes, il s’était envolé ensuite vers la Hongrie avant de retrouver la France et la D1 la saison dernière du côté de Mont Blanc.👊</p>
<p>C’était presque une évidence de le voir revenir un jour ici à Anglet, tant ce dernier y est attaché, c’est chose faites aujourd’hui ! Nous sommes très heureux de pouvoir compter sur 𝐕𝐚𝐬𝐲𝐚 pour ce nouveau chapitre, nous lui souhaitons un bel été et la (re) bienvenue au Pays Basque !🤝🤩[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F334202%2Fanton-vasilyev|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17917&Prime; img_size= » » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzMzQyMDIlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQ5MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/retour-de-anton-vasilyev.jpg', true, '1747917991000', '1774831276265', '1774833441712');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-rudolfs-polcs', 'Arrivée de Rudolfs POLCS', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]Parce qu’un Letton peut en cacher un autre…👀 Nous sommes très heureux de vous annoncer aujourd’hui l’arrivée du robuste attaquant international letton de 24 ans, 𝐑𝐮𝐝𝐨𝐥𝐟𝐬 𝐏𝐎𝐋𝐂𝐒 (🇱🇻), en provenance lui aussi ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]Parce qu’un Letton peut en cacher un autre&#8230;👀</p>
<p>Nous sommes très heureux de vous annoncer aujourd’hui l’arrivée du robuste attaquant international letton de 24 ans, 𝐑𝐮𝐝𝐨𝐥𝐟𝐬 𝐏𝐎𝐋𝐂𝐒 (🇱🇻), en provenance lui aussi des Boxers de Bordeaux !🔥</p>
<p>À l’instar de son confrère letton Nikita Jevpalovs, celui que l’on surnomme 𝐑𝐮𝐝𝐲, évoluera sous nos couleurs la saison prochaine. Ce centre de formation pouvant aussi évoluer à l’aile, apportera toutes ses aptitudes physiques du haut de ses 1.91m et ses 93kg, renforçant la colonne vertébrale de l’effectif angloy.💪</p>
<p>Après deux saisons intéressantes du côté de la Gironde, l’originaire de Riga passé par la KHL et la Slovénie étant plus jeune, comptabilisant aussi plusieurs sélections avec son équipe nationale, débarque au Pays Basque pour confirmer tout son potentiel !🤝</p>
<p>𝐑𝐮𝐝𝐲, nous te souhaitons la bienvenue ici à la Barre et on te donne rendez-vous dès le mois d’août pour entamer ce nouveau chapitre.😉[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F477494%2Frudolfs-polcs|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17912&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q0Nzc0OTQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjYxMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-rudolfs-polcs.jpg', true, '1747667336000', '1774831277312', '1774833441713');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-baptiste-manciot', 'Prolongation de Baptiste MANCIOT', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] Notre tout jeune défenseur droitier de 22 ans, 𝐁𝐚𝐩𝐭𝐢𝐬𝐭𝐞 𝐌𝐀𝐍𝐂𝐈𝐎𝐓 (🇫🇷), continuera sous les couleurs angloyes la saison prochaine !😍 Au club depuis l’âge de 16 ans, 𝐁𝐚𝐩𝐭 poursuivra son évolution à la ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<p dir="ltr">Notre tout jeune défenseur droitier de 22 ans, 𝐁𝐚𝐩𝐭𝐢𝐬𝐭𝐞 𝐌𝐀𝐍𝐂𝐈𝐎𝐓 (🇫🇷), continuera sous les couleurs angloyes la saison prochaine !😍</p>
<p>Au club depuis l’âge de 16 ans, 𝐁𝐚𝐩𝐭 poursuivra son évolution à la Barre sous les ordres de Stéphane Barin, lui qui sort de deux saisons pleines au sein de l’arrière-garde verte et rouge. Défenseur à l’aise dans les deux sens de la glace, ce sera une année charnière pour lui dans son développement !💪</p>
<p>Nous sommes très heureux de pouvoir le retrouver d’ici quelques mois sur le glaçon, toujours sous notre chandail, d’ici là 𝐁𝐚𝐩𝐭, on te souhaite une bonne intersaison et on te dit à très vite !💚❤️</p>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F362574%2Fbaptiste-manciot|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17908&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzNjI1NzQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQzMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-baptiste-manciot.jpg', true, '1747574842000', '1774831281744', '1774833441713');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-theo-fremond', 'Prolongation de Théo FREMOND', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] Auteur d’une saison complète, notre jeune défenseur formé ici à l’Hormadi, 𝐓𝐡𝐞́𝐨 𝐅𝐑𝐄́𝐌𝐎𝐍𝐃 (🇫🇷), continuera de défendre fièrement les couleurs de son club formateur une saison de plus !😍 Avec 49 matchs au co', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<p dir="ltr">Auteur d’une saison complète, notre jeune défenseur formé ici à l’Hormadi, 𝐓𝐡𝐞́𝐨 𝐅𝐑𝐄́𝐌𝐎𝐍𝐃 (🇫🇷), continuera de défendre fièrement les couleurs de son club formateur une saison de plus !😍</p>
<p>Avec 49 matchs au compteur lors du précédent exercice, 𝐅𝐫𝐞𝐦𝐳 a su s’imposer au sein de la défensive basque sous les ordres de Stéphane Barin, travailleur très assidu, il incarne aussi l’identité angloye !👊</p>
<p>C’est avec beaucoup de joie que nous le retrouverons à la Barre dès la rentrée prochaine pour un nouvel épisode en vert et rouge !💚❤️</p>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F362604%2Ftheo-fremond|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17905&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzNjI2MDQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQ0NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-theo-fremond.jpg', true, '1747573363000', '1774831283622', '1774833441714');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-ivan-esipov', 'Prolongation de Ivan ESIPOV', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] Notre jeune défenseur de 22 ans, né à Moscou et international français, 𝐈𝐯𝐚𝐧 𝐄𝐒𝐈𝐏𝐎𝐕 (🇫🇷🇷🇺), prolonge pour une deuxième saison consécutive à la Barre !🔥 Un potentiel qu’il doit confirmer dès la rentrée proc', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<p dir="ltr">Notre jeune défenseur de 22 ans, né à Moscou et international français, 𝐈𝐯𝐚𝐧 𝐄𝐒𝐈𝐏𝐎𝐕 (🇫🇷🇷🇺), prolonge pour une deuxième saison consécutive à la Barre !🔥</p>
<p>Un potentiel qu’il doit confirmer dès la rentrée prochaine, défenseur à vocation offensive qui aime soutenir ses trois attaquants devant lui, 𝐕𝐚𝐯𝐚𝐧𝐞 sera un élément clé du système de jeu du staff angloy.🫡</p>
<p>Nous sommes heureux de le voir poursuivre l’aventure sous nos couleurs et nous avons hâte de pouvoir le retrouver dans quelques mois !💚❤️[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F559917%2Fivan-esipov|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17902&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q1NTk5MTclMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjUyMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-ivan-esipov.jpg', true, '1747573069000', '1774831284521', '1774833441715');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-nathael-fleuret', 'Arrivée de Nathael FLEURET', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]𝐍𝐚𝐭𝐡𝐚𝐞𝐥 𝐅𝐥𝐞𝐮𝐫𝐞𝐭 𝐚̀ 𝐥’𝐇𝐨𝐫𝐦𝐚𝐝𝐢 !✍️🚨 Un jeune espoir français, international U20, sera parmi la paire de gardiens la saison prochaine, en la présence de 𝐍𝐚𝐭𝐡𝐚𝐞𝐥 𝐅𝐋𝐄𝐔𝐑𝐄𝐓 (🇫🇷), qui arriv', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]𝐍𝐚𝐭𝐡𝐚𝐞𝐥 𝐅𝐥𝐞𝐮𝐫𝐞𝐭 𝐚̀ 𝐥’𝐇𝐨𝐫𝐦𝐚𝐝𝐢 !✍️🚨</p>
<p>Un jeune espoir français, international U20, sera parmi la paire de gardiens la saison prochaine, en la présence de 𝐍𝐚𝐭𝐡𝐚𝐞𝐥 𝐅𝐋𝐄𝐔𝐑𝐄𝐓 (🇫🇷), qui arrive tout droit des Ducs d’Angers !🤝</p>
<p>Âgé de 20 ans, 𝐍𝐚𝐭𝐡 évoluait sous les couleurs angevines depuis cinq saisons, avec tout d’abord des passages en U17, puis en U20 avant de plonger dans le grand bain et de découvrir la Synerglace Ligue Magnus lors de la saison 2023/2024.👏</p>
<p>Après avoir engrangé de l’expérience au sein de l’effectif des Ducs, il succèdera à Isaac Charpentier et continuera de se développer sous le chandail vert et rouge dès la rentrée prochaine !💚❤️</p>
<p>𝐍𝐚𝐭𝐡, bienvenue à l’Hormadi, on te retrouve très vite sur le glaçon de la Barre !😁[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F799017%2Fnathael-fleuret|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17896&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q3OTkwMTclMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM1NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-nathael-fleuret.jpg', true, '1747486318000', '1774831284884', '1774833441716');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-mathieu-caron', 'Arrivée de Mathieu CARON', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]Il traversera l’Atlantique pour la première fois de sa carrière afin de rallier le Pays Basque dès le mois d’août prochain, nous sommes très heureux aujourd’hui de vous présenter notre tout nouveau portier canadien, en la', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]Il traversera l’Atlantique pour la première fois de sa carrière afin de rallier le Pays Basque dès le mois d’août prochain, nous sommes très heureux aujourd’hui de vous présenter notre tout nouveau portier canadien, en la présence de 𝐌𝐚𝐭𝐡𝐢𝐞𝐮 𝐂𝐀𝐑𝐎𝐍 (🇨🇦) !🤝</p>
<p>En provenance de l’Université de Boston, en NCAA, la meilleure ligue universitaire américaine, d’où provenait également Dylan St. Cyr, l’originaire de la Colombie-Britannique affichait une solide moyenne de 91,5% sur ses quatre années passées en NCAA.💪</p>
<p>Celui que l’on surnomme 𝐂𝐡𝐞𝐰𝐲 évoluait avec un certain Macklin Celebrini à Boston lors de l’épisode 2023/2024, premier choix de la draft NHL l’an dernier des San José Sharks, qui fait le bonheur en ce moment du Team Canada aux championnats du monde aux côtés de Sidney Crosby and co. 𝐌𝐚𝐭𝐡𝐢𝐞𝐮 a également été un grand artisan du parcours de sa formation cette saison, se rendant jusqu’en finale du réputé Frozen Four face à Western Michigan.🔥</p>
<p>👏De belles performances qui lui ont valu un appel en ECHL chez les Everblades de Floride en toute fin de saison dernière mais également, il aura participé à une semaine de camp d’été en juillet 2024 avec les Bruins de Boston, avant de faire le choix de poser son gant, sa mitaine et ses jambières au Pays Basque !🤝</p>
<p>Nous sommes ravis de pouvoir accueillir 𝐂𝐡𝐞𝐰𝐲 ici à la Barre pour cette toute nouvelle aventure, nous lui souhaitons un excellent été et nous avons extrêmement hâte de le voir s’exprimer dès le mois d’août !😍[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F351457%2Fmathieu-caron|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17892&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzNTE0NTclMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM1NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-mathieu-caron.jpg', true, '1747485890000', '1774831286343', '1774833441716');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-timothe-quattrone', 'Prolongation de Timothé QUATTRONE', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] Nous sommes extrêmement heureux aujourd’hui d’annoncer la prolongation de contrat de notre talentueux attaquant français, 𝐓𝐢𝐦𝐨𝐭𝐡𝐞́ 𝐐𝐔𝐀𝐓𝐓𝐑𝐎𝐍𝐄 (🇫🇷) !😍 Auteur d’une très belle première saison à l’Hormadi,', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<p dir="ltr">Nous sommes extrêmement heureux aujourd’hui d’annoncer la prolongation de contrat de notre talentueux attaquant français, 𝐓𝐢𝐦𝐨𝐭𝐡𝐞́ 𝐐𝐔𝐀𝐓𝐓𝐑𝐎𝐍𝐄 (🇫🇷) !😍</p>
<p>Auteur d’une très belle première saison à l’Hormadi, avec 23 points dont 14 buts toutes compétitions confondues, l’ancien grenoblois aura été une réelle révélation, faisant partie des hommes forts de notre offensive !🔥</p>
<p>Un potentiel qu’il souhaite confirmer un peu plus dès la rentrée prochaine toujours sous le chandail angloy pour celui qui est surnommé « powerhorse » alias le cheval de bataille.🐎</p>
<p>𝐓𝐢𝐦, on te souhaite de passer un très bel été avant de te retrouver rapidement à la Barre dès le mois d’août !💚❤️</p>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F457994%2Ftimothe-quattrone|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17886&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q0NTc5OTQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjYyNSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-timothe-quattrone.jpg', true, '1746881737000', '1774831287976', '1774833441717');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-julien-munoz', 'Prolongation de Julien MUNOZ', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] 𝐌𝐮𝐧𝐳 𝐩𝐫𝐨𝐥𝐨𝐧𝐠𝐞 𝐥’𝐚𝐯𝐞𝐧𝐭𝐮𝐫𝐞 !🖋🤝 Lui aussi reste à la Barre, notre attaquant et n°12, qui était arrivé en provenance des Brûleurs de Loups l’été dernier, 𝐉𝐮𝐥𝐢𝐞𝐧 𝐌𝐔𝐍𝐎𝐙 (🇫🇷), sera de retour ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<p dir="ltr">𝐌𝐮𝐧𝐳 𝐩𝐫𝐨𝐥𝐨𝐧𝐠𝐞 𝐥’𝐚𝐯𝐞𝐧𝐭𝐮𝐫𝐞 !🖋🤝</p>
<p>Lui aussi reste à la Barre, notre attaquant et n°12, qui était arrivé en provenance des Brûleurs de Loups l’été dernier, 𝐉𝐮𝐥𝐢𝐞𝐧 𝐌𝐔𝐍𝐎𝐙 (🇫🇷), sera de retour dans les rangs angloys à la rentrée prochaine !😍</p>
<p>𝐌𝐮𝐧𝐳 a su amener tout son caractère au groupe, en réalisant dans le même temps sa deuxième meilleure saison en Synerglace Ligue Magnus sur le plan comptable, faisant de lui un élément important de l’effectif basque.👊</p>
<p>Avec une grosse seconde partie de saison notamment, le Grenoblois de naissance continuera de faire partie de ce noyau de JFL et d’encadrer nos jeunes pousses du haut de son expérience !🫡</p>
<p>Nous sommes ravis de le voir poursuivre en vert et rouge, ici même à l’Hormadi, en attendant, nous lui souhaitons une belle intersaison avant de le revoir fouler le glaçon de la Barre au mois d’août !💚❤️</p>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F229148%2Fjulien-munoz|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17883&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyMjkxNDglMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjczMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-julien-munoz.jpg', true, '1746881380000', '1774831288360', '1774833441717');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-nikita-jevpalovs', 'Arrivée de Nikita JEVPALOVS', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]𝐍𝐢𝐤𝐢𝐭𝐚 𝐉𝐞𝐯𝐩𝐚𝐥𝐨𝐯𝐬 𝐞𝐬𝐭 𝐮𝐧 𝐀𝐧𝐠𝐥𝐨𝐲 !✍️🚨 Le Letton âgé de 30 ans avec ses 20 sélections internationales au compteur, 𝐍𝐢𝐤𝐢𝐭𝐚 𝐉𝐄𝐕𝐏𝐀𝐋𝐎𝐕𝐒 (🇱🇻), qu’on ne présente plus maintenant, restera', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]𝐍𝐢𝐤𝐢𝐭𝐚 𝐉𝐞𝐯𝐩𝐚𝐥𝐨𝐯𝐬 𝐞𝐬𝐭 𝐮𝐧 𝐀𝐧𝐠𝐥𝐨𝐲 !✍️🚨</p>
<p>Le Letton âgé de 30 ans avec ses 20 sélections internationales au compteur, 𝐍𝐢𝐤𝐢𝐭𝐚 𝐉𝐄𝐕𝐏𝐀𝐋𝐎𝐕𝐒 (🇱🇻), qu’on ne présente plus maintenant, restera dans le Sud Ouest la saison prochaine mais du côté de l’Hormadi désormais !😍</p>
<p>Cet ailier droit au sens du but redoutable et à la qualité technique hors pair, a décidé de poser ses valises à la Barre dès cet été, c’est assurément un renfort de luxe qui s’ajoute à l’offensive basque !🔥</p>
<p>𝙏𝙤𝙥 𝙎𝙘𝙤𝙧𝙚𝙧 avec 43 points en autant de parties lors de sa première apparition en France sous les couleurs de Bordeaux, 𝐍𝐢𝐤𝐢 n’a jamais cessé d’affoler les compteurs en <a  tabindex="0" role="link" href="https://www.instagram.com/synerglaceliguemagnus/?hl=fr">@synerglaceliguemagnus</a>, comptabilisant 112 points pour un total de 130 matchs avec les Boxers depuis trois exercices.👊</p>
<p>Passé auparavant par la AHL, la KHL ou encore l’ICEHL, c’est avec beaucoup de satisfaction que nous l’accueillons ici au Pays Basque, nous lui souhaitons évidemment la bienvenue et nous avons hâte de le voir à l’œuvre sur le glaçon de la Barre !😮‍💨[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F52417%2Fnikita-jevpalovs|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17879&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q1MjQxNyUyMiUyMHdpZHRoJTNEJTIyMTAwJTI1JTIyJTIwaGVpZ2h0JTNEJTIyNTk1JTIyJTIwc2Nyb2xsaW5nJTNEJTIybm8lMjIlMjBmcmFtZWJvcmRlciUzRCUyMjAlMjIlM0UlM0MlMkZpZnJhbWUlM0UlMEE=[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-nikita-jevpalovs.jpg', true, '1746723901000', '1774831288877', '1774833441718');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-dylan-st-cyr', 'Départ de Dylan ST. CYR', '[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »] 𝐌𝐢𝐥𝐞𝐬𝐤𝐞𝐫 𝐃𝐲𝐥𝐬 !💚❤️ C&rsquo;est avec une énorme pointe au cœur que nous vous annonçons aujourd&rsquo;hui la retraite sportive de 𝐃𝐲𝐥𝐚𝐧 𝐒𝐓. 𝐂𝐘𝐑 (🇺🇸🇨🇦), notre muraille angloye, celui qui a réalisé tous les exploi', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »]</p>
<div >
<div dir="auto">
<p dir="ltr">𝐌𝐢𝐥𝐞𝐬𝐤𝐞𝐫 𝐃𝐲𝐥𝐬 !💚❤️</p>
<p>C&rsquo;est avec une énorme pointe au cœur que nous vous annonçons aujourd&rsquo;hui la retraite sportive de 𝐃𝐲𝐥𝐚𝐧 𝐒𝐓. 𝐂𝐘𝐑 (🇺🇸🇨🇦), notre muraille angloye, celui qui a réalisé tous les exploits possibles dans ses cages depuis deux saisons, a décidé de donner un nouveau tournant à sa vie !🥲</p>
<p>Depuis son arrivée au Pays Basque à l&rsquo;été 2023, il aura marqué les esprits de tous, aussi bien à la Barre qu&rsquo;aux quatre coins de l&rsquo;hexagone, rayonnant de par son style acrobatique et virevoltant dans ses filets mais également de par sa technique et son jeu de crosse unique !🤩</p>
<p>Aujourd&rsquo;hui, à 25 ans et après 89 matchs fièrement disputés sous le chandail basque, 𝐃𝐲𝐥𝐬 raccroche les patins mais sera non loin du club puisqu&rsquo;il restera vivre dans la région.😉</p>
<p>C&rsquo;est une décision évidemment respectable pour celui qui a toujours été engagé dans notre club et notamment auprès des jeunes gardiens de l&rsquo;AHA, qu&rsquo;il a accompagné tout au long de cette saison !👏</p>
<p>𝐃𝐲𝐥𝐬, c&rsquo;est tout Anglet qui te remercie pour ces deux saisons que tu nous as offertes, tu auras su marquer de ton empreinte ton passage ici à l&rsquo;Hormadi, désormais une nouvelle page s&rsquo;ouvre à toi et nous te souhaitons évidemment le meilleur pour tes projets futurs !🫶</p>
<p>Et puis, vu que tu es ici chez toi maintenant, passes nous voir quand tu veux&#8230;🥰</p>
</div>
</div>
<p>[/vc_column_text][/vc_column][vc_column width= »1/4&Prime;][vc_single_image image= »17874&Prime; img_size= »medium » alignment= »center » css= » »][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-dylan-st-cyr.jpg', true, '1746629364000', '1774831289481', '1774833441718');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-isaac-charpentier', 'Départ de Isaac CHARPENTIER', '[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »] ❌🚨𝐃𝐞́𝐩𝐚𝐫𝐭 𝐝&rsquo;𝐈𝐬𝐚𝐚𝐜 𝐂𝐡𝐚𝐫𝐩𝐞𝐧𝐭𝐢𝐞𝐫 ! Arrivé à la Barre l&rsquo;été dernier, notre portier français, 𝐈𝐬𝐚𝐚𝐜 𝐂𝐇𝐀𝐑𝐏𝐄𝐍𝐓𝐈𝐄𝐑 (🇫🇷), ne fera plus partie de l&rsquo;effectif angloy la saison prochaine et', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »]</p>
<div >
<div dir="auto">
<p dir="ltr">❌🚨𝐃𝐞́𝐩𝐚𝐫𝐭 𝐝&rsquo;𝐈𝐬𝐚𝐚𝐜 𝐂𝐡𝐚𝐫𝐩𝐞𝐧𝐭𝐢𝐞𝐫 !</p>
<p>Arrivé à la Barre l&rsquo;été dernier, notre portier français, 𝐈𝐬𝐚𝐚𝐜 𝐂𝐇𝐀𝐑𝐏𝐄𝐍𝐓𝐈𝐄𝐑 (🇫🇷), ne fera plus partie de l&rsquo;effectif angloy la saison prochaine et évoluera sous d&rsquo;autres couleurs !✈️</p>
<p>𝐙𝐚𝐳𝐚𝐜, nous te remercions pour cette saison passée au club et nous te souhaitons bonne chance pour la suite de ta carrière.👋</p>
</div>
</div>
<p>[/vc_column_text][/vc_column][vc_column width= »1/4&Prime;][vc_single_image image= »17871&Prime; img_size= »medium » alignment= »center » css= » »][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-isaac-charpentier.jpg', true, '1746629258000', '1774831290165', '1774833441719');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-nick-master', 'Départ de Nick MASTER', '[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »] ❌🚨𝐃𝐞́𝐩𝐚𝐫𝐭 𝐝𝐞 𝐍𝐢𝐜𝐤 𝐌𝐚𝐬𝐭𝐞𝐫… Arrivé en renfort au mois de novembre dernier en provenance du Danemark, le centre américain de 30 ans, 𝐍𝐢𝐜𝐤 𝐌𝐀𝐒𝐓𝐄𝐑 (🇺🇸), ne fera plus partie de l&rsquo;effectif angloy la saison ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_column_text css= » »]</p>
<div >
<div dir="auto">
<p dir="ltr">❌🚨𝐃𝐞́𝐩𝐚𝐫𝐭 𝐝𝐞 𝐍𝐢𝐜𝐤 𝐌𝐚𝐬𝐭𝐞𝐫&#8230;</p>
<p>Arrivé en renfort au mois de novembre dernier en provenance du Danemark, le centre américain de 30 ans, 𝐍𝐢𝐜𝐤 𝐌𝐀𝐒𝐓𝐄𝐑 (🇺🇸), ne fera plus partie de l&rsquo;effectif angloy la saison prochaine et donnera un nouveau tournant à sa carrière.🫡</p>
<p>Auteur d&rsquo;un passage remarqué à la Barre, avec 27 points en 34 matchs toutes compétitions confondues, il aura su apporter toute son aisance offensive, notamment sur le sprint final. Nous tenions à le remercier pour son professionnalisme et nous lui souhaitons bonne chance dans ses projets futurs !🤝</p>
</div>
</div>
<p>[/vc_column_text][/vc_column][vc_column width= »1/4&Prime;][vc_single_image image= »17831&Prime; img_size= »medium » alignment= »center » css= » »][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-nick-master.png', true, '1746629142000', '1774831293260', '1774833441719');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-samuel-rousseau', 'Prolongation de Samuel ROUSSEAU', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] 𝐑𝐨𝐮𝐬𝐬𝐞𝐚𝐮 𝐞𝐭 𝐀𝐧𝐠𝐥𝐞𝐭 𝐧𝐞 𝐟𝐨𝐧𝐭 𝐪𝐮&rsquo;𝐮𝐧 !🖋🤝 Il est arrivé au Pays Basque il y a deux ans maintenant et ne le quitte plus désormais, notre vaillant attaquant français, 𝐒𝐚𝐦𝐮𝐞𝐥𝐑𝐎𝐔𝐒𝐒𝐄𝐀', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<p dir="ltr">𝐑𝐨𝐮𝐬𝐬𝐞𝐚𝐮 𝐞𝐭 𝐀𝐧𝐠𝐥𝐞𝐭 𝐧𝐞 𝐟𝐨𝐧𝐭 𝐪𝐮&rsquo;𝐮𝐧 !🖋🤝</p>
<p>Il est arrivé au Pays Basque il y a deux ans maintenant et ne le quitte plus désormais, notre vaillant attaquant français, 𝐒𝐚𝐦𝐮𝐞𝐥𝐑𝐎𝐔𝐒𝐒𝐄𝐀𝐔 (🇫🇷), portera bel et bien les couleurs angloyes une saison supplémentaire !🔥</p>
<p>Très en vue depuis le début d&rsquo;année 2025 et notamment sur le sprint final, 𝐒𝐚𝐦 a été récompensé à juste titre de tous ses efforts fournis pour l&rsquo;équipe, arborant même le casque d&rsquo;or durant la poule de maintien.👏</p>
<p>Un élément indispensable du collectif de Stéphane Barin, qui a le goût du sacrifice avec un grand S, souvent touché mais jamais tombé, il continuera d&rsquo;apporter toute son énergie à l&rsquo;Hormadi dès la rentrée prochaine !😍</p>
<p>𝐒𝐚𝐦, très bel été à toi et on te retrouve très rapidement aux abords de la Barre pour une nouvelle aventure !💚❤️[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F363574%2Fsamuel-rousseau|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17862&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzNjM1NzQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjY1NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-samuel-rousseau.jpg', true, '1746628881000', '1774831295097', '1774833441720');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-fabien-kazarine', 'Prolongation de Fabien KAZARINE', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] 𝐊𝐚𝐳’𝐀𝐬𝐬𝐢𝐬𝐭𝐚𝐧𝐭 𝐩𝐫𝐨𝐥𝐨𝐧𝐠𝐞 !🖋🤝 On démarre fort cette nouvelle semaine avec la prolongation de contrat de notre 𝑻𝒐𝒑 𝑺𝒄𝒐𝒓𝒆𝒓, 𝐅𝐚𝐛𝐢𝐞𝐧 𝐊𝐀𝐙𝐀𝐑𝐈𝐍𝐄 (🇫🇷), qui entamera à la rentrée procha', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<p dir="ltr">𝐊𝐚𝐳’𝐀𝐬𝐬𝐢𝐬𝐭𝐚𝐧𝐭 𝐩𝐫𝐨𝐥𝐨𝐧𝐠𝐞 !🖋🤝</p>
<p>On démarre fort cette nouvelle semaine avec la prolongation de contrat de notre 𝑻𝒐𝒑 𝑺𝒄𝒐𝒓𝒆𝒓, 𝐅𝐚𝐛𝐢𝐞𝐧 𝐊𝐀𝐙𝐀𝐑𝐈𝐍𝐄 (🇫🇷), qui entamera à la rentrée prochaine sa quatrième saison déjà sous les couleurs de l&rsquo;Hormadi !😍</p>
<p>Assistant capitaine cette saison également, 𝐊𝐚𝐳𝐚 est un réel leader au sein du groupe et parfaitement installé maintenant au Pays Basque. Auteur de 37 points lors du précédent exercice, il continuera d&rsquo;être un atout majeur de l&rsquo;effectif angloy sur la glace pour notre plus grand plaisir !🔥</p>
<p>Bel été à toi 𝐊𝐚𝐳𝐚 et à très vite à la Barre !💚❤️[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F151491%2Ffabien-kazarine|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17859&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxNTE0OTElMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjgzNSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-fabien-kazarine.jpg', true, '1746628713000', '1774831295918', '1774833441720');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-arnaud-faure', 'Prolongation de Arnaud FAURE', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »] 𝐂𝐚𝐩𝐭𝐚𝐢𝐧 𝐍𝐨𝐧𝐨 𝐫𝐞𝐦𝐩𝐢𝐥𝐞 !🫡🖋 Quoi de mieux pour finir la semaine ? La prolongation de notre défenseur et capitaine, 𝐀𝐫𝐧𝐚𝐮𝐝 𝐅𝐀𝐔𝐑𝐄 (🇫🇷), pour une saison supplémentaire !😍 𝐍𝐨𝐧𝐨 continuera d', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]</p>
<p dir="ltr">𝐂𝐚𝐩𝐭𝐚𝐢𝐧 𝐍𝐨𝐧𝐨 𝐫𝐞𝐦𝐩𝐢𝐥𝐞 !🫡🖋</p>
<p>Quoi de mieux pour finir la semaine ? La prolongation de notre défenseur et capitaine, 𝐀𝐫𝐧𝐚𝐮𝐝 𝐅𝐀𝐔𝐑𝐄 (🇫🇷), pour une saison supplémentaire !😍</p>
<p>𝐍𝐨𝐧𝐨 continuera de défendre fièrement les couleurs basques pour une troisième année consécutive dès la rentrée prochaine. Élément fort du groupe angloy dans le vestiaire, sa présence physique et ses atouts défensifs sur la glace sont tout aussi indispensables au collectif !💪</p>
<p>Nous sommes vraiment heureux de le retrouver dans quelques mois, 𝐍𝐨𝐧𝐨 désormais on te souhaite un très bel été et on te dit à très vite au chaudron !🤝[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F163801%2Farnaud-faure|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17856&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxNjM4MDElMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjY4NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-arnaud-faure.jpg', true, '1746628527000', '1774831296442', '1774833441721');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-alexey-polodyan', 'Prolongation de Alexey POLODYAN', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]De retour à la maison, chez lui ici à l’Hormadi l’été dernier, notre virevoltant attaquant russe de 26 ans, 𝐀𝐥𝐞𝐱𝐞𝐲 𝐏𝐎𝐋𝐎𝐃𝐘𝐀𝐍 (🇷🇺), continuera de porter les couleurs angloyes la saison prochaine !😍 Toujours', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]De retour à la maison, chez lui ici à l’Hormadi l’été dernier, notre virevoltant attaquant russe de 26 ans, 𝐀𝐥𝐞𝐱𝐞𝐲 𝐏𝐎𝐋𝐎𝐃𝐘𝐀𝐍 (🇷🇺), continuera de porter les couleurs angloyes la saison prochaine !😍</p>
<p>Toujours aussi travailleur dans les deux sens de la glace et auteur d’une saison complète, avec 10 buts et 15 assistances en 44 matchs disputés, 𝐏𝐨𝐥𝐨 restera une pièce maîtresse de l’offensive basque.🔥</p>
<p>Nous sommes très heureux de le voir poursuivre l’aventure, désormais 𝐏𝐨𝐥𝐨, on te souhaite un bel été et on te retrouve très vite sur la glace de la Barre !🤝[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » css= » » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F313724%2Falexei-polodyan|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17832&Prime; img_size= »large » alignment= »center » css= » »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html css= » »]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzMTM3MjQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQ3NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-alexey-polodyan.png', true, '1745501206000', '1774831298302', '1774833441721');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-stephane-barin', 'Prolongation de Stéphane BARIN', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]Il poursuivra en tant qu’entraîneur en chef de l’Hormadi pour une seconde saison consécutive, notre technicien de 54 ans, 𝐒𝐭𝐞́𝐩𝐡𝐚𝐧𝐞 𝐁𝐚𝐫𝐢𝐧, reste à la tête de l’équipe !🫡 L’originaire de Grenoble qui avait fa', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text css= » »]Il poursuivra en tant qu’entraîneur en chef de l’Hormadi pour une seconde saison consécutive, notre technicien de 54 ans, 𝐒𝐭𝐞́𝐩𝐡𝐚𝐧𝐞 𝐁𝐚𝐫𝐢𝐧, reste à la tête de l’équipe !🫡</p>
<p>L’originaire de Grenoble qui avait fait son retour sur les bancs de Ligue Magnus en septembre dernier avec Anglet, prépare d’ores et déjà l’épisode 2025-2026, il souhaitait d’ailleurs adresser quelques mots :</p>
