INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-ivan-esipov', 'Arrivée de Ivan ESIPOV', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] ✍️ | 𝐍𝐎𝐔𝐕𝐄𝐋𝐋𝐄 𝐀𝐑𝐑𝐈𝐕𝐄́𝐄 |🚨 Un jeune international français débarque à la Barre…🐓🇫🇷 Il n&rsquo;a que 21 ans seulement, mais il fait déjà partie des gros prospects français à la ligne bleue, avec 7 sélections en É', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<div >
<div dir="auto">
<div >
<div dir="auto">
<p><span >✍️</span> | 𝐍𝐎𝐔𝐕𝐄𝐋𝐋𝐄 𝐀𝐑𝐑𝐈𝐕𝐄́𝐄 |<span >🚨</span></p>
<p>Un jeune international français débarque à la Barre&#8230;<span >🐓</span><span >🇫🇷</span></p>
<p>Il n&rsquo;a que 21 ans seulement, mais il fait déjà partie des gros prospects français à la ligne bleue, avec 7 sélections en Équipe de France sur ces deux dernières années, le défenseur offensif, 𝐈𝐯𝐚𝐧 𝐄𝐒𝐈𝐏𝐎𝐕 (<span >🇫🇷</span><span >🇷🇺</span>), rejoint l&rsquo;Hormadi la saison prochaine !<span >🤩</span></p>
<p>C&rsquo;est une belle pioche, auteur de 24 points en 48 matchs la saison dernière en championnat sous les couleurs des Aigles de Nice, 𝗜𝘃𝗮𝗻 était parmi les trois meilleurs défenseurs tricolores de la ligue. Un talent à polir donc, qui vient s&rsquo;inscrire dans ce nouveau projet angloy.<span >🤝</span></p>
<p>Par ailleurs, né à Moscou, 𝗜𝘃𝗮𝗻 possède aussi la double nationalité Franco-Russe, via son père, Andrei, ancien joueur de Bordeaux et de Mulhouse à l’époque.</p>
<p>Nous sommes extrêmement heureux de le voir arriver à la Barre, nous lui souhaitons la bienvenue au club et un bel été avant de se retrouver pour le début du camp en août.<span >👊</span></p>
<p>𝑶𝑵𝑮𝑰 𝑬𝑻𝑶𝑹𝑹𝑰 𝑰𝑽𝑨𝑵 !<span >💚</span><span >❤️</span></p>
</div>
</div>
</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F559917%2Fivan-esipov|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17480&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q1NTk5MTclMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQ2MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-ivan-esipov.jpeg', true, '1717603240000', '1774831357732', '1774833441735');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-timothe-quattrone', 'Arrivée de Timothé QUATTRONE', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] ✍️ | 𝐍𝐎𝐔𝐕𝐄𝐋𝐋𝐄 𝐀𝐑𝐑𝐈𝐕𝐄́𝐄 |🚨 Un Brûleur de Loups peut en cacher un autre…👀🐺 Après l&rsquo;arrivée à la Barre de Julien Munoz, c&rsquo;est un autre attaquant français en provenance de Grenoble qui pose ses valises a', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<div >
<div dir="auto">
<div >
<div dir="auto">
<p><span >✍️</span> | 𝐍𝐎𝐔𝐕𝐄𝐋𝐋𝐄 𝐀𝐑𝐑𝐈𝐕𝐄́𝐄 |<span >🚨</span></p>
<p>Un Brûleur de Loups peut en cacher un autre&#8230;<span >👀</span><span >🐺</span></p>
<p>Après l&rsquo;arrivée à la Barre de Julien Munoz, c&rsquo;est un autre attaquant français en provenance de Grenoble qui pose ses valises au Pays Basque, en la personne du jeune ailier gauche de 23 ans, 𝐓𝐢𝐦𝐨𝐭𝐡𝐞́ 𝐐𝐔𝐀𝐓𝐓𝐑𝐎𝐍𝐄 (<span >🇫🇷</span>).</p>
<p>Doté d&rsquo;un très bon potentiel offensif, 𝗧𝗶𝗺 vient de passer deux saisons sous les couleurs grenobloises, où il a disputé pas moins de 112 matchs entre la Synerglace Ligue Magnus, la CHL, la Continental Cup et la Coupe de France. À l&rsquo;instar de son collègue Julien, lui aussi a remporté les deux dernières éditions de la Coupe de France.<span >🔥</span></p>
<p>De nombreuses sélections en Équipe de France junior également pour 𝗧𝗶𝗺 qui possède une belle habileté technique, un très bon patinage et une marge de progression significative.<span >👊</span></p>
<p>Nous sommes extrêmement ravis de l&rsquo;accueillir chez nous, dans le sillage de Julien, il quitte l&rsquo;Isère pour l&rsquo;océan. Nous lui souhaitons la bienvenue à l&rsquo;Hormadi, et on lui donne rendez-vous au mois d&rsquo;août.<span >😉</span></p>
<p>𝑶𝑵𝑮𝑰 𝑬𝑻𝑶𝑹𝑹𝑰 𝑻𝑰𝑴𝑶𝑻𝑯𝑬́ !<span >💚</span><span >❤️</span></p>
</div>
</div>
</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F457994%2Ftimothe-quattrone|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17403&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q0NTc5OTQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjU4MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
