INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-julien-munoz', 'Arrivée de Julien MUNOZ', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] ✍️ | 𝐍𝐎𝐔𝐕𝐄𝐋𝐋𝐄 𝐀𝐑𝐑𝐈𝐕𝐄́𝐄 |🚨 Il est la première recrue française de cette intersaison à la Barre, l&rsquo;ailier droit français de 26 ans, 𝐉𝐮𝐥𝐢𝐞𝐧 𝐌𝐔𝐍𝐎𝐙 (🇫🇷), débarque à l&rsquo;Hormadi en provenance des ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<div >
<div dir="auto">
<div >
<div dir="auto">
<p><span >✍️</span> | 𝐍𝐎𝐔𝐕𝐄𝐋𝐋𝐄 𝐀𝐑𝐑𝐈𝐕𝐄́𝐄 |<span >🚨</span></p>
<p>Il est la première recrue française de cette intersaison à la Barre, l&rsquo;ailier droit français de 26 ans, 𝐉𝐮𝐥𝐢𝐞𝐧 𝐌𝐔𝐍𝐎𝐙 (<span >🇫🇷</span>), débarque à l&rsquo;Hormadi en provenance des Brûleurs de Loups.<span >😍</span></p>
<p>Champion de France 2022, vainqueur de la Coupe de France en 2023 et 2024 avec Grenoble et plus de 220 matchs disputés sous les couleurs des BDL, 𝗝𝘂𝗹𝗶𝗲𝗻, faisait partie des cadres de l&rsquo;effectif isérois ces dernières années.<span >👊</span><span >🐺</span></p>
<p>L&rsquo;originaire de Villard-de-Lans a effectué toutes ses classes juniors à Grenoble, tout en étant prêté à Chambery, avant de partir durant une saison à Mulhouse en 2020, qui s&rsquo;était avérée concluante, lui permettant de revenir chez les Brûleurs de Loups l&rsquo;année suivante et de s&rsquo;installer durablement au sein du groupe.<span >💪</span></p>
<p>C&rsquo;est un réel atout aussi bien sur la glace qu&rsquo;en dehors, fort de ses expériences également en CHL, nous sommes donc extrêmement ravis de pouvoir accueillir 𝗝𝘂𝗹𝗶𝗲𝗻 au Pays Basque la saison prochaine.<span >🤝</span></p>
<p>Nous lui souhaitons la bienvenue au club et nous avons très hâte de le voir à l&rsquo;œuvre dans quelques mois !<span >🔥</span></p>
<p>𝑶𝑵𝑮𝑰 𝑬𝑻𝑶𝑹𝑹𝑰 𝑱𝑼𝑳𝑰𝑬𝑵 !<span >💚</span><span >❤️</span></p>
</div>
</div>
</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F229148%2Fjulien-munoz|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17398&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyMjkxNDglMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjcwMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-julien-munoz.jpeg', true, '1717430422000', '1774831362910', '1774833441736');
