INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-baptiste-manciot-17384', 'Prolongation de Baptiste MANCIOT', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] 🤝 | 𝐏𝐑𝐎𝐋𝐎𝐍𝐆𝐀𝐓𝐈𝐎𝐍 |🚨 Il pointe le bout de son nez depuis maintenant deux ans en ayant pleinement intégré le groupe professionnel, du haut de ses 21 ans, notre jeune défenseur, 𝐁𝐚𝐩𝐭𝐢𝐬𝐭𝐞 𝐌𝐀𝐍𝐂𝐈𝐎𝐓 (🇫🇷), ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<div >
<div dir="auto">
<p><span >🤝</span> | 𝐏𝐑𝐎𝐋𝐎𝐍𝐆𝐀𝐓𝐈𝐎𝐍 |<span >🚨</span></p>
<p>Il pointe le bout de son nez depuis maintenant deux ans en ayant pleinement intégré le groupe professionnel, du haut de ses 21 ans, notre jeune défenseur, 𝐁𝐚𝐩𝐭𝐢𝐬𝐭𝐞 𝐌𝐀𝐍𝐂𝐈𝐎𝐓 (<span >🇫🇷</span>), poursuivra son apprentissage à l&rsquo;Hormadi la saison prochaine.</p>
<p>Avec 30 matchs au compteur, un premier but en Synerglace Ligue Magnus à Chamonix et un différentiel de +5 la saison dernière, 𝗕𝗮𝗽𝘁 a toujours su répondre présent de belle manière, même lorsqu&rsquo;il fallait dépanner à l&rsquo;offensive.<span >😤</span></p>
<p>C&rsquo;est en toute logique que le club compte encore sur lui et souhaite l&rsquo;accompagner dans son développement. 𝗕𝗮𝗽𝘁, nous te souhaitons à toi aussi un bel été, et on te dit à très vite sur le glaçon de la Barre !<span >💚</span><span >❤️</span></p>
</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F362574%2Fbaptiste-manciot|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17385&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzNjI1NzQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM4NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
