INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-victor-ranger', 'Prolongation de Victor RANGER', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] 🤝 | 𝐏𝐑𝐎𝐋𝐎𝐍𝐆𝐀𝐓𝐈𝐎𝐍 |🚨 Il entamera au mois d&rsquo;août prochain sa cinquième saison consécutive sous les couleurs de l&rsquo;Hormadi, pièce importante du noyau de français, notre attaquant et n°18, 𝐕𝐢𝐜𝐭𝐨𝐫 𝐑𝐀𝐍', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<div >
<div dir="auto">
<p><span >🤝</span> | 𝐏𝐑𝐎𝐋𝐎𝐍𝐆𝐀𝐓𝐈𝐎𝐍 |<span >🚨</span></p>
<p>Il entamera au mois d&rsquo;août prochain sa cinquième saison consécutive sous les couleurs de l&rsquo;Hormadi, pièce importante du noyau de français, notre attaquant et n°18, 𝐕𝐢𝐜𝐭𝐨𝐫 𝐑𝐀𝐍𝐆𝐄𝐑 (<span >🇫🇷</span>), poursuit une année supplémentaire.</p>
<p>Lui qui a fêté ses 25 ans au début du mois, souhaite s&rsquo;inscrire dans la durée avec son club de cœur et confirmer la saison prochaine, après deux dernières saisons très encourageantes dans un rôle plus offensif.<span >👊</span></p>
<p>Nous sommes ravis de pouvoir compter à nouveau sur 𝗩𝗶𝗰, nous lui souhaitons de passer un très bel été, et puis nous le retrouvons très bientôt sur le glaçon de la Barre !<span >💚</span><span >❤️</span></p>
</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F297247%2Fvictor-ranger|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17347&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyOTcyNDclMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjU1MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-victor-ranger.jpeg', true, '1716998431000', '1774831398202', '1774833441737');
