INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'retour-de-alexei-polodyan', 'Retour de Alexei POLODYAN', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] 𝐆𝐮𝐞𝐬𝐬 𝐰𝐡𝐨&rsquo;𝐬 𝐛𝐚𝐜𝐤 ?🤩👀 Vous l&rsquo;aviez probablement deviné et pour votre plus grand plaisir, 𝗠𝗮𝗴𝗶𝗰 𝗣𝗼𝗹𝗼 est de retour !✨ Après une saison en Gironde chez les Boxers de Bordeaux, le talentueux attaqu', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<div >
<div dir="auto">
<div >
<div dir="auto">
<p>𝐆𝐮𝐞𝐬𝐬 𝐰𝐡𝐨&rsquo;𝐬 𝐛𝐚𝐜𝐤 ?<span >🤩</span><span >👀</span></p>
<p>Vous l&rsquo;aviez probablement deviné et pour votre plus grand plaisir, 𝗠𝗮𝗴𝗶𝗰 𝗣𝗼𝗹𝗼 est de retour !<span >✨</span><br />
Après une saison en Gironde chez les Boxers de Bordeaux, le talentueux attaquant russe à la chevelure dorée, 𝐀𝐥𝐞𝐱𝐞𝐲 𝐏𝐎𝐋𝐎𝐃𝐘𝐀𝐍 (<span >🇷🇺</span>), revient à la maison et portera à nouveau le chandail de l&rsquo;Hormadi dès la rentrée prochaine.<span >😍</span></p>
<p>Arrivé en France et à Anglet au mois de novembre 2021, 𝗣𝗼𝗹𝗼 avait de suite marqué les esprits de par son patinage et ses mains en or, faisant de lui un élément essentiel de l&rsquo;effectif angloy. Deux saisons à la Barre, 75 matchs et 68 points au total sous nos couleurs avant de partir à Bordeaux l&rsquo;été dernier où il terminera vice-champion de France quelques mois plus tard.<br />
Désormais 𝗣𝗼𝗹𝗼 revient ici déterminé et compte bien continuer de faire lever les foules avec l&rsquo;Hormadi.<span >🔥</span></p>
<p>Nous sommes vraiment ravis de pouvoir compter sur lui et de le voir revenir au Pays Basque, auquel il est très attaché. 𝗣𝗼𝗹𝗼, (re) bienvenue au club, bel été à toi et on se donne rendez-vous très rapidement !<span >🤝</span></p>
<p>𝑶𝑵𝑮𝑰 𝑬𝑻𝑶𝑹𝑹𝑰 𝑷𝑶𝑳𝑶 !<span >💚</span><span >❤️</span></p>
</div>
</div>
</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F313724%2Falexei-polodyan|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17326&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzMTM3MjQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQzMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/retour-de-alexei-polodyan.jpeg', true, '1716566401000', '1774831403330', '1774833441738');
