INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'calendrier-playdown', 'Calendrier PlayDown', '[vc_row][vc_column][vc_column_text]Avec sa 10 ème place de la saison régulière, L&rsquo;Hormadi défendra sa place dans l&rsquo;élite du hockey français lors des Playdown. Un nouveau championnat à quatre équipes avec match aller/retour tout en conservant les points cumulés dans la phase régulière. Se', '<div ><p>[vc_row][vc_column][vc_column_text]Avec sa 10 ème place de la saison régulière, L&rsquo;Hormadi défendra sa place dans l&rsquo;élite du hockey français lors des Playdown.</p>
<p>Un nouveau championnat à quatre équipes avec match aller/retour tout en conservant les points cumulés dans la phase régulière.</p>
