INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-nick-jermain', 'Arrivée de Nick JERMAIN', '???????? ??????́? Voici la petite surprise de ce début de nouvelle année ! Il est fraîchement arrivé hier matin à l’aéroport de Biarritz, en provenance des Lions des Trois-Rivières en ECHL (3e échelon nord-américain), l’attaquant américain de 27 ans, ???? ???????, pose ses valises à la Barre afin de', '<div >
<div dir="auto">???????? ??????́? <span ><img loading="lazy" decoding="async"  src="https://static.xx.fbcdn.net/images/emoji.php/v9/tf2/2/16/1f1fa_1f1f8.png" alt="??" width="16" height="16" /></span></div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Voici la petite surprise de ce début de nouvelle année !<span ><img loading="lazy" decoding="async"  src="https://static.xx.fbcdn.net/images/emoji.php/v9/tc/2/16/1f973.png" alt="?" width="16" height="16" /></span></div>
<div dir="auto"><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2024/01/Capture-decran-2024-01-02-a-09.41.42.png" alt="" width="409" height="406" srcset="https://pro.hormadi.fr/wp-content/uploads/2024/01/Capture-decran-2024-01-02-a-09.41.42.png 592w, https://pro.hormadi.fr/wp-content/uploads/2024/01/Capture-decran-2024-01-02-a-09.41.42-300x298.png 300w, https://pro.hormadi.fr/wp-content/uploads/2024/01/Capture-decran-2024-01-02-a-09.41.42-150x150.png 150w, https://pro.hormadi.fr/wp-content/uploads/2024/01/Capture-decran-2024-01-02-a-09.41.42-128x128.png 128w, https://pro.hormadi.fr/wp-content/uploads/2024/01/Capture-decran-2024-01-02-a-09.41.42-32x32.png 32w, https://pro.hormadi.fr/wp-content/uploads/2024/01/Capture-decran-2024-01-02-a-09.41.42-200x200.png 200w, https://pro.hormadi.fr/wp-content/uploads/2024/01/Capture-decran-2024-01-02-a-09.41.42-80x80.png 80w, https://pro.hormadi.fr/wp-content/uploads/2024/01/Capture-decran-2024-01-02-a-09.41.42-98x98.png 98w" sizes="auto, (max-width: 409px) 100vw, 409px" /></div>
</div>
<div >
<div dir="auto">Il est fraîchement arrivé hier matin à l’aéroport de Biarritz, en provenance des Lions des Trois-Rivières en ECHL (3e échelon nord-américain), l’attaquant américain de 27 ans, ???? ???????, pose ses valises à la Barre afin de renforcer l’attaque angloye pour cette seconde partie de saison.<span ><img loading="lazy" decoding="async"  src="https://static.xx.fbcdn.net/images/emoji.php/v9/tef/2/16/1f525.png" alt="?" width="16" height="16" /></span></div>
</div>
<div >
<div dir="auto">Après un passage rapide l’an dernier en Extraliga Slovaque au HK Propad, Nick a principalement évolué en East Coast en ECHL, sous les couleurs des Lions des Trois-Rivières, des Mariners Maine ou encore des Komets de Fort Wayne.</div>
<div dir="auto">Après ses années universitaires à Quinnipiac, il avait également vécu une expérience post-covid en EIHL, l’élite britannique, à Coventry.<span ><img loading="lazy" decoding="async"  src="https://static.xx.fbcdn.net/images/emoji.php/v9/tb/2/16/1f4aa.png" alt="?" width="16" height="16" /></span></div>
</div>
<div >
<div dir="auto">Dans la force de l’âge, Nick rejoint donc les rangs basques, et sera présent à l’entraînement dès demain mardi, avec ses nouveaux coéquipiers.</div>
<div dir="auto">Le club met tout en œuvre actuellement afin que notre futur ?°?? soit qualifié au plus vite !<span ><img loading="lazy" decoding="async"  src="https://static.xx.fbcdn.net/images/emoji.php/v9/tc4/2/16/1fae1.png" alt="?" width="16" height="16" /></span></div>
</div>
<div >
<div dir="auto">??????? ???? ???? !<span ><img loading="lazy" decoding="async"  src="https://static.xx.fbcdn.net/images/emoji.php/v9/t3/2/16/1f91d.png" alt="?" width="16" height="16" /></span><span ><img loading="lazy" decoding="async"  src="https://static.xx.fbcdn.net/images/emoji.php/v9/t5b/2/16/1f30a.png" alt="?" width="16" height="16" /></span></div>
</div>
<p>#GoHormadi | #JoTaKeIrabaziArte</p>
<p>&nbsp;</p>
', 'Arrivées', '/images/news/arrivee-de-nick-jermain.png', true, '1704185018000', '1774831516585', '1774833441746');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'vente-aux-encheres-noel', '[VENTE AUX ENCHÈRES NOËL]🎄', '[vc_row][vc_column width= »1/2&Prime;][vc_single_image image= »17182&Prime; img_size= »full » alignment= »center »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17183&Prime; img_size= »full » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_btn title= »Page Faceb', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_single_image image= »17182&Prime; img_size= »full » alignment= »center »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »17183&Prime; img_size= »full » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_btn title= »Page Facebook » style= »custom » custom_background= »#2176ff » custom_text= »#ffffff » align= »center » css_animation= »bounceIn » link= »url:https%3A%2F%2Fwww.facebook.com%2Fanglethormadiofficiel|target:_blank »][vc_column_text]</p>
<p >C&rsquo;est parti !⏳</p>
<p >C’est le moment de tenter votre chance afin de vous procurer l’un de nos magnifiques maillots de Noël, qui ont été portés par l&rsquo;ensemble de nos joueurs lors de la rencontre face à Grenoble le vendredi 22 décembre.<span >😍</span></p>
<p>[/vc_column_text][vc_column_text]</p>
<p >Il n’y a pas d’autres moyens de se les procurer, ce sont des exemplaires uniques, officiels et dédicacés, dont le gagnant sera le seul possesseur !🤩</p>
<p >Les maillots sont des modèles joueurs et non des modèles type “répliqua”, ils sont donc de grande taille (L, XL ou XXL). Les maillots vous sont proposés à la vente dès aujourd&rsquo;hui jeudi 28 décembre 2023 à 13h, au lundi 8 janvier 2024 à 19h.🔥</p>
<p ><span >🚨Règlement de cette vente aux enchères (</span>𝑷𝑹𝑬𝑵𝑬𝒁<span >&#8211;</span>𝑬𝑵 𝑩𝑰𝑬𝑵 𝑪𝑶𝑵𝑵𝑨𝑰𝑺𝑺𝑨𝑵𝑪𝑬 𝑺𝑽𝑷 𝑨𝑭𝑰𝑵 𝑫<span >&lsquo;</span>𝑬́𝑽𝑰𝑻𝑬𝑹 𝑳𝑬𝑺 𝑸𝑼𝑰𝑷𝑹𝑶𝑸𝑼𝑶𝑺<span >) :</span></p>
<ul >
<li >Le prix de départ est fixé à 50€.</li>
<li >Le palier minimum pour une enchère est de 5.00€.</li>
<li >Pour enchérir il vous faudra commenter la photo du maillot en question avec le montant de votre enchère.</li>
<li >Les montants comprenant des centimes ne sont pas autorisés (pas d’enchères à 60,01€ par exemple).</li>
<li >Les enchères se termineront le lundi 8 janvier 2024 à 19h. L’heure de référence est celle de Facebook.</li>
</ul>
<p >Néanmoins, afin d’éviter un engorgement de dernière minute, si une enchère valide est proposée dans les quinze dernières minutes de l’enchère, l’heure de clôture sera repoussée de dix minutes, aussi souvent que nécessaire. (ex : enchère valide à 18h58, l&rsquo;enchère est repoussée jusqu&rsquo;à 19h08, etc)</p>
<p >🚨Une fois l’enchère clôturée, les maillots ne pourront être ni repris, ni échangés, ni remboursés. À compter de la fin de cette vente aux enchères, vous aurez jusqu’au lundi 22 janvier 2024 (2 semaines) dernier délai pour venir récupérer votre maillot, sinon, ce dernier, ira à la seconde enchère la plus élevée.</p>
<p >Enchères à distance👇 :</p>
<p >Vous pouvez enchérir et remporter un maillot même sans habiter à proximité d’Anglet. Il suffira de rajouter à votre enchère le montant des frais d’envoi en fonction du mode choisi (colis simple, suivi, en recommandé, etc…). Environ 10€ pour un envoi en France.</p>
<p >💵Les règlements se feront en carte bancaire, en espèce, par virement ou par chèque.</p>
<p >Pour toutes autres questions veuillez nous contacter par mail à contact@hormadi.fr ou par téléphone au 05.59.57.17.37 !</p>
<p >Bonne chance à tous !🍀</p>
<p >#GoHormadi | #JoTaKeIrabaziArte</p>
<p>[/vc_column_text][vc_btn title= »Page Facebook » style= »custom » custom_background= »#2176ff » custom_text= »#ffffff » css_animation= »bounceInDown » link= »url:https%3A%2F%2Fwww.facebook.com%2Fanglethormadiofficiel|target:_blank »][/vc_column][/vc_row]</p>
</div>', 'Jeu concours', '/images/news/vente-aux-encheres-noel.png', true, '1703840697000', '1774831518193', '1774833441747');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'vente-aux-encheres-octobre-rose-16985', '[VENTE AUX ENCHÈRES OCTOBRE ROSE]🎀', '[vc_row][vc_column width= »1/2&Prime;][vc_single_image image= »16996&Prime; img_size= »full » alignment= »center »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16995&Prime; img_size= »full » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_btn title= »Page Faceb', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_single_image image= »16996&Prime; img_size= »full » alignment= »center »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16995&Prime; img_size= »full » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_btn title= »Page Facebook » style= »custom » custom_background= »#2176ff » custom_text= »#ffffff » align= »center » css_animation= »bounceIn » link= »url:https%3A%2F%2Fwww.facebook.com%2Fanglethormadiofficiel|target:_blank »][vc_column_text]C&rsquo;est parti !⏳</p>
<p>C’est le moment de tenter votre chance sur notre page FACEBOOK afin de vous procurer l’un de nos maillots noirs et roses, qui ont été porté par l&rsquo;ensemble de nos joueurs tout au long de ce mois d&rsquo;Octobre Rose pour soutenir la lutte contre le cancer du sein.🖤🩷[/vc_column_text][vc_column_text]Il n’y a pas d’autres moyens de se les procurer, ce sont des exemplaires uniques, officiels et dédicacés, dont le gagnant sera le seul possesseur !🤩</p>
<p>Les maillots sont des modèles joueurs et non des modèles type “réplica”, ils sont donc de grande taille (L, XL ou XXL). Les maillots vous sont proposés à la vente dès aujourd&rsquo;hui jeudi 2 novembre 2023 à 18h, au lundi 13 novembre 2023 à 18h.</p>
<p>🚨Règlement de cette vente aux enchères :</p>
<ul>
<li>Le prix de départ est fixé à 50€.</li>
<li>Le palier minimum pour une enchère est de 5.00€.</li>
<li>Pour enchérir il vous faudra commenter la photo du maillot en question avec le montant de votre enchère.</li>
<li>Les montants comprenant des centimes ne sont pas autorisés (pas d’enchères à 60,01€ par exemple).</li>
<li>Les enchères se termineront le lundi 13 novembre à 18h. L’heure de référence est celle de Facebook.</li>
<li>Les dons récoltés seront reversé à la Ligue contre le cancer.</li>
</ul>
<p>Néanmoins, afin d’éviter un engorgement de dernière minute, si une enchère valide est proposée dans les quinze dernières minutes de l’enchère, l’heure de clôture sera repoussée de dix minutes, aussi souvent que nécessaire.</p>
<p>Une fois l’enchère clôturée, les maillots ne pourront être ni repris, ni échangés, ni remboursés. À compter de la fin de cette vente aux enchères, vous aurez jusqu’au vendredi 24 novembre 2023 (2 semaines) dernier délai pour venir récupérer votre maillot, sinon, ce dernier, ira à la seconde enchère la plus élevée.</p>
<p>Enchères à distance👇 :</p>
<p>Vous pouvez enchérir et remporter un maillot même sans habiter à proximité d’Anglet. Il suffira de rajouter à votre enchère le montant des frais d’envoi en fonction du mode choisi (colis simple, suivi, en recommandé, etc…). Environ 10€ pour un envoi en France.</p>
<p>💵Les règlements se feront en carte bancaire, en espèce, par virement ou par chèque.</p>
<p>Pour toutes autres questions veuillez nous contacter par mail à contact@hormadi.fr ou par téléphone au 05.59.57.17.37 !</p>
<p>Bonne chance à tous !🍀</p>
<p>#GoHormadi | #JoTaKeIrabaziArte<span > </span>[/vc_column_text][vc_btn title= »Page Facebook » style= »custom » custom_background= »#2176ff » custom_text= »#ffffff » css_animation= »bounceInDown » link= »url:https%3A%2F%2Fwww.facebook.com%2Fanglethormadiofficiel|target:_blank »][/vc_column][/vc_row]</p>
</div>', 'Vie du Club', '/images/news/vente-aux-encheres-octobre-rose-16985.png', true, '1698940779000', '1774831521167', '1774833441747');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'colin-doyle-ma-capacite-de-patinage-me-permet-de-contribuer-efficacement-dans-tous-les-domaines-de-la-patinoire', 'Colin Doyle : « Ma capacité de patinage me permet de contribuer efficacement dans tous les domaines de la patinoire »', 'Très en vue en ce début de camp d&rsquo;entraînement, le centre canadien, Colin Doyle, débarque à Anglet pour apporter son gros patinage et son énergie sur la glace. Entretien exclusif avec notre numéro 17. Le camp d’entraînement a démarré depuis quelques jours, comment te sentais-tu avant cette rep', '<h4>Très en vue en ce début de camp d&rsquo;entraînement, le centre canadien, Colin Doyle, débarque à Anglet pour apporter son gros patinage et son énergie sur la glace. Entretien exclusif avec notre numéro 17.</h4>
<figure id="attachment_16889" aria-describedby="caption-attachment-16889"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/Colin_Doyle-214x300.jpg" alt="" width="231" height="324" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/Colin_Doyle-214x300.jpg 214w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Colin_Doyle-731x1024.jpg 731w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Colin_Doyle-768x1076.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Colin_Doyle-1096x1536.jpg 1096w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Colin_Doyle-91x128.jpg 91w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Colin_Doyle-23x32.jpg 23w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Colin_Doyle-70x98.jpg 70w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Colin_Doyle.jpg 1142w" sizes="auto, (max-width: 231px) 100vw, 231px" /><figcaption id="caption-attachment-16889" ><span ><em>Colin Doyle ici, évoluait en NCAA, la meilleure ligue universitaire américaine.</em></span></figcaption></figure>
<p><em><strong>Le camp d’entraînement a démarré depuis quelques jours, comment te sentais-tu avant cette reprise ?</strong></em></p>
<p><span ><strong>Colin Doyle :</strong></span> « Je me sentais vraiment enthousiasmé à l&rsquo;approche du camp d&rsquo;entraînement ! J&rsquo;ai passé un super été, à m&rsquo;entraîner et à patiner, je n&rsquo;avais qu&rsquo;une hâte, c&rsquo;était de commencer à Anglet, de rencontrer mes nouveaux coéquipiers, d&rsquo;apprendre à connaître le personnel, le staff et de communiquer avec les partisans. »</p>
<p><strong><em>Y avait-il une forme d’appréhension chez toi à l’approche de cette nouvelle expérience en Europe et en France ?</em></strong></p>
<p><span ><strong>Colin Doyle :</strong></span> « Je ressentais définitivement un mélange d&rsquo;émotions à l&rsquo;approche de cette nouvelle expérience en Europe et en France. Bien qu&rsquo;il puisse y avoir un tout petit peu d&rsquo;appréhension, mon sentiment écrasant était l&rsquo;excitation. L&rsquo;idée de découvrir une nouvelle culture, d&rsquo;explorer un pays différent et de m&rsquo;immerger dans des opportunités uniques est incroyablement excitante. Je ne suis jamais allé en Europe auparavant, alors j&rsquo;ai hâte de vivre toutes les expériences uniques qui se présenteront à moi. Je suis vraiment reconnaissant pour cette opportunité incroyable et j&rsquo;ai hâte de voir ce que cette aventure me réserve. »</p>
<p><em><strong>Comment s’est déroulée ta préparation physique cet été ?</strong></em></p>
<p><span ><strong>Colin Doyle :</strong></span> « Ma préparation physique cet été s&rsquo;est super bien passée. Je suis resté avec une routine d&rsquo;entraînement qui s&rsquo;est avérée efficace pour moi au cours des dernières années. Je suis confiant pour ma prochaine saison grâce au travail que j&rsquo;ai fait avec mon entraîneur de force et de patinage à la maison et aux conseils de Florent Neyens. Cet effort constant m&rsquo;a donné l&rsquo;assurance que je serai bien préparé pour les défis de la saison à venir. »</p>
<figure id="attachment_16903" aria-describedby="caption-attachment-16903"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/entrainement-20-300x200.jpg" alt="" width="335" height="223" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-20-300x200.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-20-1024x683.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-20-768x512.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-20-1536x1024.jpg 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-20-2048x1365.jpg 2048w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-20-128x85.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-20-32x21.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-20-360x240.jpg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-20-98x65.jpg 98w" sizes="auto, (max-width: 335px) 100vw, 335px" /><figcaption id="caption-attachment-16903" ><span ><em>Colin Doyle en action à la Barre lors du premier jour du camp d&rsquo;entraînement.</em></span></figcaption></figure>
<p><em><strong>Peux-tu nous raconter un peu les raisons de cette décision de t’engager avec Anglet ?</strong></em></p>
<p><span ><strong>Colin Doyle :</strong></span> « J&rsquo;ai décidé de rejoindre Anglet pour plusieurs raisons, et elles ont toutes joué un rôle important dans ma décision. Tout d&rsquo;abord, l&rsquo;équipe elle-même semblait être un excellent choix. Leur façon de fonctionner, leur style de jeu et leurs objectifs correspondaient bien à ce que je recherchais dans une équipe. D&rsquo;après ce que j&rsquo;ai entendu, l&rsquo;enthousiasme et le soutien des fans ont également été un facteur majeur. Le sens de la communauté et la passion que les fans ont pour l&rsquo;équipe ont vraiment résonné en moi. Je crois qu&rsquo;avoir des partisans aussi dévoués et enthousiastes peut faire une énorme différence dans la création d&rsquo;une atmosphère positive à la fois sur et hors de la glace. L&rsquo;opportunité de faire partie de la meilleure ligue de hockey en France a été un grand attrait. Pouvoir concourir à un niveau élevé et me défier contre des adversaires talentueux est quelque chose qui me passionne vraiment. »</p>
<figure id="attachment_16888" aria-describedby="caption-attachment-16888"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle-300x300.jpg" alt="" width="306" height="306" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle-300x300.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle-150x150.jpg 150w, https://pro.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle-128x128.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle-32x32.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle-200x200.jpg 200w, https://pro.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle-255x255.jpg 255w, https://pro.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle-80x80.jpg 80w, https://pro.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle-98x98.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle-445x445.jpg 445w, https://pro.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle-270x270.jpg 270w, https://pro.hormadi.fr/wp-content/uploads/2023/08/03-23-2023-_imb0118-doyle.jpg 500w" sizes="auto, (max-width: 306px) 100vw, 306px" /><figcaption id="caption-attachment-16888" ><em><span >Colin Doyle a terminé la saison dernière en ECHL, chez les Ghost Pirates de Savannah.</span></em></figcaption></figure>
<p><em><strong>Tu arrives d’ECHL, des Savannah Ghost Pirates, là où tu as terminé cette dernière saison avec 3 points en 7 matchs, que retiens-tu de ce premier appel chez les professionnels en ECHL ?</strong></em></p>
<p><span ><strong>Colin Doyle :</strong></span> « Ma première convocation en ECHL avec les Savannah Ghost Pirates a été une expérience formidable. Après la fin de ma saison universitaire en NCAA, j&rsquo;ai eu la chance de rejoindre l&rsquo;équipe et de jouer mes premiers matchs professionnels. Je me souviens d&rsquo;avoir ressenti un mélange d&rsquo;excitation et de nervosité lorsque j&rsquo;ai sauté sur la glace pour ces matchs. J&rsquo;ai vraiment apprécié mon séjour à Savannah et j&rsquo;ai beaucoup appris au cours de ces sept matchs. Je suis extrêmement reconnaissant d&rsquo;avoir eu l&rsquo;opportunité de mettre en valeur mes capacités au niveau professionnel et de franchir cette étape importante dans le développement de ma carrière. »</p>
<p><em><strong>Avant ça, tu évoluais depuis 2018 en NCAA, à l’Université d’Alaska-Fairbanks, comment juges-tu ta progression au sein de ce qui se fait de mieux au niveau universitaire aux États-Unis ?</strong></em></p>
<p><span ><strong>Colin Doyle :</strong></span> « Jouer dans la NCAA à l&rsquo;Université d&rsquo;Alaska-Fairbanks a été une expérience incroyablement enrichissante pour moi. Ces cinq années ont été parmi les meilleures de ma vie, remplies de moments inoubliables et de croissance personnelle. Le niveau de compétition dans la NCAA est de premier ordre et je suis fier des progrès que j&rsquo;ai réalisés parmi certains des meilleurs joueurs universitaires des États-Unis.</p>
<p>Les expériences que j&rsquo;ai vécues pendant mon séjour en Alaska étaient vraiment incroyables. J&rsquo;ai eu l&rsquo;occasion de nouer de solides amitiés avec des coéquipiers, d&rsquo;apprendre auprès d&rsquo;entraîneurs dévoués et de me défier contre des adversaires de haut calibre. Cette période de mon parcours dans le hockey m&rsquo;a aidé à me façonner non seulement en tant que joueur, mais aussi en tant que personne. La combinaison d&rsquo;universitaires, d&rsquo;athlétisme et de l&rsquo;expérience universitaire globale a été inestimable, et je suis incroyablement reconnaissant pour les souvenirs et les leçons que j&rsquo;ai acquis au cours de mes années NCAA. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/doyle-300x223.png" alt="" width="300" height="223" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/doyle-300x223.png 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/doyle-1024x763.png 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/08/doyle-768x572.png 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/doyle-128x95.png 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/doyle-32x24.png 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/doyle-98x73.png 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/doyle-160x120.png 160w, https://pro.hormadi.fr/wp-content/uploads/2023/08/doyle.png 1207w" sizes="auto, (max-width: 300px) 100vw, 300px" /><br />
Aurais-tu aimé poursuivre ta carrière de hockeyeur en Amérique du Nord ou bien tu avais ce désir de voyager et te tester à l’étranger ?</strong></em></p>
<p><span ><strong>Colin Doyle :</strong> </span>« J&rsquo;étais enthousiasmé par l&rsquo;opportunité de voyager et de me tester à l&rsquo;étranger. Bien que poursuivre ma carrière de hockeyeur en Amérique du Nord soit également une voie valable, j&rsquo;ai ressenti un fort désir d&rsquo;explorer de nouveaux horizons et de me mettre au défi dans un cadre différent. L&rsquo;idée de faire l&rsquo;expérience d&rsquo;une nouvelle culture et de relever des défis divers m&rsquo;a vraiment séduit. J&rsquo;y voyais une chance d&rsquo;élargir mes perspectives sur et hors glace, et j&rsquo;avais hâte d&#8217;embrasser l&rsquo;aventure de jouer au hockey à Anglet. »</p>
<p><em><strong>Si on parle un peu du style de joueur que tu es sur la glace, plutôt un centre de métier avec un fort patinage, comment tu te décrirais et quelles sont tes qualités ?</strong></em></p>
<p><span ><strong>Colin Doyle :</strong></span> « Je suis un joueur polyvalent qui peut jouer à la fois comme centre et comme ailier. Sur la glace, je me considère comme un attaquant à double sens qui patine fort. Ma capacité de patinage me permet de contribuer efficacement dans tous les domaines de la patinoire. Je suis fier de mes compétences dans le cercle de mise au jeu. Je peux jouer à la fois en désavantage numérique et en avantage numérique. Une autre qualité qui me définit est mon échec avant implacable, qui met la pression sur les adversaires et contribue à créer des revirements. Ma solide éthique de travail est la pierre angulaire de mon style de jeu et je me consacre à donner le meilleur de moi-même à chaque match et à chaque entraînement. »</p>
<figure id="attachment_16891" aria-describedby="caption-attachment-16891"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/Doyler-300x206.jpeg" alt="" width="372" height="256" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/Doyler-300x206.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Doyler-768x528.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Doyler-128x88.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Doyler-32x22.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Doyler-98x67.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Doyler.jpeg 828w" sizes="auto, (max-width: 372px) 100vw, 372px" /><figcaption id="caption-attachment-16891" ><span ><em>Colin Doyle est un joueur de centre qui peut évoluer à l&rsquo;aile droite.</em></span></figcaption></figure>
<p><em><strong data-wp-editing="1">Il y aura quelques Canadiens et quelques Américains au sein de l’équipe d’Anglet la saison prochaine, c’est rassurant pour toi de savoir que tu seras entouré de joueurs avec une culture plus ou moins similaire ?</strong></em></p>
<p><span ><strong>Colin Doyle :</strong></span> « Absolument, je suis vraiment excité à l&rsquo;idée d&rsquo;avoir à la fois des Canadiens et des Américains dans l&rsquo;équipe d&rsquo;Anglet la saison prochaine. C&rsquo;est rassurant de savoir qu&rsquo;il y aura des joueurs avec une culture un peu similaire. Cependant, je suis également ravi d&rsquo;avoir l&rsquo;opportunité de rencontrer et de nouer des liens avec les joueurs français de l&rsquo;équipe. Embrasser de nouvelles perspectives et expériences est l&rsquo;une des raisons pour lesquelles je suis enthousiasmé par ce voyage à l&rsquo;étranger. Le mélange d&rsquo;horizons, de langues et d&rsquo;approches du jeu peut créer une dynamique d&rsquo;équipe vraiment unique, à la fois enrichissante et gratifiante. J&rsquo;ai hâte d&rsquo;établir des relations solides avec des joueurs de divers horizons culturels, et ensemble, nous créerons une équipe unie et solide qui pourra exceller sur et hors de la glace. »</p>
<p><em><strong>Quelle personnalité affiches-tu en dehors de la glace ?</strong></em></p>
<p><span ><strong>Colin Doyle :</strong> </span>« En dehors de la glace, je suis une personne amusante et énergique qui aime être avec ses coéquipiers. J&rsquo;ai une personnalité sociale et extravertie, et je m&rsquo;épanouis quand je suis avec les garçons de l&rsquo;équipe. J&rsquo;apprécie vraiment ces moments de camaraderie et d&rsquo;amitié, et je trouve de la joie à tirer sur la brise et à me connecter avec mes coéquipiers. Qu&rsquo;il s&rsquo;agisse de partager des histoires, de plaisanter ou simplement de passer du temps de qualité ensemble, je chéris les liens qui se forment hors de la glace. J&rsquo;aime aussi rencontrer des fans et des gens de la communauté. Je pense qu&rsquo;il est important de connaître les gens qui soutiennent l&rsquo;équipe. »</p>
<figure id="attachment_16905" aria-describedby="caption-attachment-16905"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/entrainement-21-295x300.jpg" alt="" width="295" height="300" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-21-295x300.jpg 295w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-21-1008x1024.jpg 1008w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-21-768x780.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-21-1512x1536.jpg 1512w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-21-126x128.jpg 126w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-21-32x32.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-21-80x80.jpg 80w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-21-96x98.jpg 96w, https://pro.hormadi.fr/wp-content/uploads/2023/08/entrainement-21.jpg 1932w" sizes="auto, (max-width: 295px) 100vw, 295px" /><figcaption id="caption-attachment-16905" ><span ><em>Colin Doyle portera le numéro 17 avec l&rsquo;Hormadi cette saison.</em></span></figcaption></figure>
<p><em><strong>Le camp d’entraînement a démarré ce dimanche, as-tu quelques mots pour les fans pour finir ?</strong></em></p>
<p><span ><strong>Colin Doyle :</strong></span> « À tous les fans qui nous soutiennent, je tiens à exprimer ma gratitude pour votre enthousiasme et vos encouragements indéfectibles. Un grand merci d&rsquo;être venu ce dimanche, nous allons nous préparer à tout donner, tant à l&rsquo;entraînement que tout au long de la saison. Vos encouragements depuis les tribunes alimentent notre détermination et nous incitent à repousser nos limites. Nous sommes ravis de montrer notre travail acharné et notre dévouement sur la glace ! »</p>
<p><span >Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</span></p>
', 'Interview', '/images/news/colin-doyle-ma-capacite-de-patinage-me-permet-de-contribuer-efficacement-dans-to.png', true, '1692346485000', '1774831522612', '1774833441748');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-trey-phillips', 'Arrivée de Trey PHILLIPS', '?ARRIVÉE 2023-2024? Il est bien là ! Découvrez notre toute dernière recrue… Retrouvez également sa vidéo d&rsquo;arrivée sur nos différents réseaux sociaux.? En provenance d’ECHL, plus précisément des Iowa Heartlanders, le défenseur offensif canadien de 30 ans, TREY PHILLIPS, vient boucler l’effecti', '<p><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/Copie-de-ARRIVEES-292x300.jpg" alt="" width="369" height="379" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-ARRIVEES-292x300.jpg 292w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-ARRIVEES-997x1024.jpg 997w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-ARRIVEES-768x789.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-ARRIVEES-125x128.jpg 125w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-ARRIVEES-32x32.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-ARRIVEES-95x98.jpg 95w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-ARRIVEES-457x470.jpg 457w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-ARRIVEES.jpg 1009w" sizes="auto, (max-width: 369px) 100vw, 369px" /></p>
<p>?ARRIVÉE 2023-2024?</p>
<p>Il est bien là ! Découvrez notre toute dernière recrue… Retrouvez également sa vidéo d&rsquo;arrivée sur nos différents réseaux sociaux.?<span > </span></p>
<p>En provenance d’ECHL, plus précisément des Iowa Heartlanders, le défenseur offensif canadien de 30 ans, <strong>TREY PHILLIPS</strong>, vient boucler l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine.</p>
<p>Avec pas moins de 140 matchs en ECHL, sous différents maillots, ce défenseur gaucher, au gabarit mobile (1.78m/82kg), viendra apporter à l’effectif angloy, son patinage, son aisance en zone offensive ainsi que son habilité sur les situations de powerplay.</p>
<p>L’ensemble du club se réjouit de pouvoir compter sur notre futur numéro 8 dans quelques jours pour le début du camp d’entraînement, et tient à lui souhaiter, la bienvenue à la Barre.</p>
<p>WELCOME HOME TREY !??</p>
<p>Avec ce dernier ajout défensif, nous vous annonçons que l’effectif est officiellement complet pour l’épisode 2023-2024 !✅</p>
<p>#GoHormadi | #JoTaKeIrabaziArte</p>
<p>&nbsp;</p>
', 'Arrivées', '/images/news/arrivee-de-trey-phillips.jpg', true, '1691596803000', '1774831524092', '1774833441748');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'michael-young-etre-un-bon-coequipier-est-lrsquoun-des-traits-les-plus-importants-a-mes-yeux-crsquoest-pourquoi-je-mrsquo', 'Michael Young : « Être un bon coéquipier est l&rsquo;un des traits les plus importants à mes yeux, c&rsquo;est pourquoi je m&rsquo;efforce d&rsquo;être fiable, dévoué et concentré »', 'En provenance des États-Unis dans le Massachusetts, et du meilleur championnat universitaire américain (NCAA), le robuste défenseur, Michael Young, arrive à la Barre pour apporter toute sa solidité défensive. Entretien exclusif avec notre numéro 2. À 24 ans, bientôt 25, tu quittes pour la première f', '<h4>En provenance des États-Unis dans le Massachusetts, et du meilleur championnat universitaire américain (NCAA), le robuste défenseur, Michael Young, arrive à la Barre pour apporter toute sa solidité défensive. Entretien exclusif avec notre numéro 2.</h4>
<figure id="attachment_16848" aria-describedby="caption-attachment-16848"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9-300x300.png" alt="" width="297" height="297" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9-300x300.png 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9-150x150.png 150w, https://pro.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9-128x128.png 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9-32x32.png 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9-200x200.png 200w, https://pro.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9-255x255.png 255w, https://pro.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9-80x80.png 80w, https://pro.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9-98x98.png 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9-445x445.png 445w, https://pro.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9-270x270.png 270w, https://pro.hormadi.fr/wp-content/uploads/2023/08/7e40b7a1-83c0-4279-881b-70cf18c06bc9.png 600w" sizes="auto, (max-width: 297px) 100vw, 297px" /><figcaption id="caption-attachment-16848" ><span ><em>Capitaine de l&rsquo;université de Yale en NCAA, le défenseur américain, Michael Young portera les couleurs de l&rsquo;Hormadi la saison prochaine.</em></span></figcaption></figure>
<p><em><strong>À 24 ans, bientôt 25, tu quittes pour la première fois le continent nord-américain afin de rejoindre l’Europe et la France la saison prochaine, quel sentiment demeure chez toi actuellement ?</strong></em></p>
<p><span ><strong>Michael Young :</strong></span> « J&rsquo;ai attendu avec impatience d&rsquo;aller à Anglet tout l&rsquo;été, mais j&rsquo;ai apprécié le temps passé à la maison avec ma famille. Je suis le plus jeune d&rsquo;une famille de cinq enfants, et j&rsquo;ai la chance d&rsquo;avoir la plupart de ma famille à Boston, ce qui me permet de passer du temps avec mes parents, mes frères et sœurs, mes neveux et nièces cet été avant le grand départ pour la France. »</p>
<p><em><strong>Pourquoi ce choix de venir à Anglet, comment cela s’est-il passé ?</strong></em></p>
<p><span ><strong>Michael Young :</strong></span> « Alors que je terminais ma carrière universitaire à Yale, je savais que je voulais jouer professionnellement à l&rsquo;étranger en raison de la qualité du hockey et de la qualité de vie. Peu après avoir obtenu mon diplôme universitaire, j&rsquo;ai eu la chance d&rsquo;entrer en contact avec la direction et les entraîneurs de l&rsquo;Hormadi, et au fur et à mesure que j&rsquo;en apprenais davantage sur l&rsquo;équipe, l&rsquo;endroit et la culture, j&rsquo;étais sûr de vouloir jouer à Anglet. »</p>
<p><em><strong>Connaissais-tu déjà un peu la ligue française avant ta signature ?</strong></em></p>
<p><span ><strong>Michael Young :</strong></span> « Je dirais que mes connaissances étaient initialement limitées. Cependant, j&rsquo;ai quelques anciens coéquipiers qui ont joué dans la Synerglace Ligue Magnus, la Division 1 en France, et d&rsquo;autres ligues en Europe l&rsquo;année dernière. Comme le dit l&rsquo;adage, « le monde du hockey est petit », et ils connaissaient tous la ligue française, soit de première main, soit par l&rsquo;intermédiaire de leurs propres coéquipiers. Ils ont eu la gentillesse de me faire part de leurs réflexions, et j&rsquo;ai entendu des commentaires élogieux sur la ligue française. »</p>
<figure id="attachment_16849" aria-describedby="caption-attachment-16849"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/Michael-Young-300x200.jpg" alt="" width="330" height="220" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/Michael-Young-300x200.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Michael-Young-768x511.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Michael-Young-128x85.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Michael-Young-32x21.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Michael-Young-360x240.jpg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Michael-Young-98x65.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Michael-Young.jpg 1024w" sizes="auto, (max-width: 330px) 100vw, 330px" /><figcaption id="caption-attachment-16849" ><span ><em>Michael Young découvrira pour la première fois l&rsquo;Europe et la France dès le mois de septembre.</em></span></figcaption></figure>
<p><em><strong>Comment évalues-tu ce changement de carrière pour toi, personnellement, tu avais envie d’emprunter un nouveau chemin ?</strong></em></p>
<p><span ><strong>Michael Young :</strong></span> « Comme la plupart des joueurs, mon objectif a toujours été de jouer au hockey de manière professionnelle, et je suis donc extrêmement reconnaissant de cette opportunité. À Yale, le hockey est évidemment très important, mais le diplôme universitaire l&rsquo;est tout autant et demande beaucoup de temps. C&rsquo;est pourquoi, avec le hockey comme seul objectif cette année, je suis ravi de pouvoir me consacrer encore plus au jeu. »</p>
<p><em><strong>Tu sors de quatre dernières années à l’Université de Yale en NCAA (meilleure ligue universitaire américaine), que retiens-tu de ton parcours universitaire ?</strong></em></p>
<p><span ><strong>Michael Young :</strong></span> « Je garde de nombreux bons souvenirs de ma carrière universitaire, tant sur la glace qu&rsquo;en dehors. Avec la rotation minimale des joueurs dans la NCAA, l&rsquo;équipe était très soudée et les sept d&rsquo;entre nous de la promotion 2023 resteront proches pendant longtemps. L&rsquo;annulation par Yale de notre saison 20/21 en raison de la pandémie nous a mis en difficulté, mais nous avons appris l&rsquo;importance d&rsquo;un état d&rsquo;esprit de croissance et de la persévérance. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/Young-2-300x200.jpeg" alt="" width="300" height="200" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-2-300x200.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-2-768x512.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-2-128x85.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-2-32x21.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-2-360x240.jpeg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-2-98x65.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-2.jpeg 1024w" sizes="auto, (max-width: 300px) 100vw, 300px" />Tu étais d’ailleurs le capitaine de ton équipe la saison dernière, tu as ce leadership en toi ?</strong></em></p>
<p><span ><strong>Michael Young :</strong></span> « J&rsquo;ai été élu capitaine par mes coéquipiers au début de la saison dernière, j&rsquo;étais très fier et c&rsquo;est un honneur que je ne considère pas comme acquis. Tout au long de ma carrière, j&rsquo;ai toujours pensé qu&rsquo;une bonne attitude, une solide éthique de travail et la persévérance étaient des qualités essentielles pour un joueur et en particulier pour un leader. J&rsquo;essaie d&rsquo;apporter ces qualités sur la patinoire en permanence et je comprends qu&rsquo;il faut toute une équipe pour gagner. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/Young-4-300x282.jpeg" alt="" width="272" height="255" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-4-300x282.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-4-768x723.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-4-128x121.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-4-32x30.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-4-98x92.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-4.jpeg 1024w" sizes="auto, (max-width: 272px) 100vw, 272px" />Tu possèdes un gabarit imposant, tu es droitier également, comment décrirais-tu le style de défenseur que tu es aujourd’hui, plutôt défensif  ?</strong></em></p>
<p><span ><strong>Michael Young :</strong></span> « J&rsquo;ai toujours cru qu&rsquo;une bonne défense était la pierre angulaire d&rsquo;une culture et d&rsquo;une saison gagnantes, alors je m&rsquo;efforce de m&rsquo;occuper de ce côté de la rondelle avant tout, en utilisant particulièrement ma force autour du filet et dans les coins. Sur le plan offensif, je cherche à me joindre à la ruée lorsque les conditions sont propices et à envoyer des rondelles au filet depuis la ligne bleue pour créer de l&rsquo;offensive. »</p>
<p><em><strong>De par ta personnalité, que penses-tu pouvoir apporter au groupe, que ce soit sur ou en dehors de la glace ?</strong></em></p>
<p><span ><strong>Michael Young :</strong></span> « Être un bon coéquipier est l&rsquo;un des traits les plus importants à mes yeux, c&rsquo;est pourquoi je m&rsquo;efforce d&rsquo;être fiable, dévoué et concentré, tout en étant prompt à rire et à apprécier le voyage. Une attitude positive est importante pour surmonter les hauts et les bas d&rsquo;une saison et même d&rsquo;une journée. Je cherche à apporter de l&rsquo;intensité et un haut niveau de compétitivité sur la glace tout en étant de bonne humeur et facile à vivre en dehors de la glace. »</p>
<figure id="attachment_16851" aria-describedby="caption-attachment-16851"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/Young-3-300x200.jpeg" alt="" width="300" height="200" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-3-300x200.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-3-768x512.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-3-128x85.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-3-32x21.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-3-360x240.jpeg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-3-98x65.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-3.jpeg 1024w" sizes="auto, (max-width: 300px) 100vw, 300px" /><figcaption id="caption-attachment-16851" ><span ><em>Michael Young fait 1.85m pour 95kg.</em></span></figcaption></figure>
<p><em><strong>Plusieurs joueurs ou anciens joueurs provenant de NCAA ont signé à Anglet comme toi, en connais-tu ?</strong></em></p>
<p><strong><span >Michael Young :</span></strong> « Je ne connais aucun d&rsquo;entre eux personnellement, mais je sais qu&rsquo;ils ont des amis communs. Je suis impatient de les rencontrer et de commencer le camp dans quelques jours avec ce groupe qui semble compétitif à mes yeux. »</p>
<p><em><strong>Pour ta première saison à l’étranger et à Anglet, quels sont tes objectifs personnels et collectifs ?</strong></em></p>
<p><span ><strong>Michael Young :</strong></span> « Étant nouveau dans l&rsquo;équipe et dans la ligue française, mes objectifs ne sont pas très précis, mais ils consistent à faire tout ce que je peux pour mettre l&rsquo;équipe en position de gagner. Les objectifs collectifs à mes yeux sont de grandir et de s&rsquo;améliorer tout au long de l&rsquo;année et de jouer notre meilleur hockey lorsqu&rsquo;il y a du matériel en jeu. »</p>
<figure id="attachment_16853" aria-describedby="caption-attachment-16853"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/Young-225x300.jpeg" alt="" width="192" height="256" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-225x300.jpeg 225w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-96x128.jpeg 96w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-24x32.jpeg 24w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young-74x98.jpeg 74w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Young.jpeg 768w" sizes="auto, (max-width: 192px) 100vw, 192px" /><figcaption id="caption-attachment-16853" ><span ><em>Michael Young portera le numéro 2 la saison prochaine à l&rsquo;Hormadi.</em></span></figcaption></figure>
<p><em><strong>Enfin, as-tu quelques mots pour les fans à quelques semaines du début du camp ?</strong></em></p>
<p><span ><strong>Michael Young :</strong></span> « J&rsquo;espère que l&rsquo;été a été agréable pour tous les fans, et j&rsquo;espère encore plus qu&rsquo;ils sont prêts pour la saison de hockey et pour faire du bruit à la patinoire de la Barre. Je suis impatient de rencontrer les fans en août et tout au long de l&rsquo;année. Nous apprécions toujours votre soutien ! Soyez prudents et à très bientôt ! »</p>
<p><span ><em>Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</em></span></p>
', 'Interview', '/images/news/michael-young-etre-un-bon-coequipier-est-lrsquoun-des-traits-les-plus-importants.png', true, '1691506222000', '1774831526813', '1774833441751');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-drsquoolivier-dame-malka', 'Départ d&rsquo;Olivier DAME-MALKA', '[vc_row][vc_column][vc_column_text] Il est l’ultime et dernier départ de cette intersaison, après mûre réflexion, l’ex-international français, OLIVIER DAME-MALKA, ne portera plus les couleurs angloyes au mois de septembre prochain. Arrivé l’été dernier en provenance du Danemark, « ODM » aura inscrit', '<div ><p>[vc_row][vc_column][vc_column_text]<img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-300x300.jpg" alt="" width="300" height="300" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-300x300.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-1024x1024.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-150x150.jpg 150w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-768x768.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-128x128.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-32x32.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-200x200.jpg 200w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-255x255.jpg 255w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-80x80.jpg 80w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-740x740.jpg 740w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-98x98.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-445x445.jpg 445w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2-270x270.jpg 270w, https://pro.hormadi.fr/wp-content/uploads/2023/08/DEPART-2.jpg 1080w" sizes="auto, (max-width: 300px) 100vw, 300px" /><br />
Il est l’ultime et dernier départ de cette intersaison, après mûre réflexion, l’ex-international français, <strong>OLIVIER DAME-MALKA</strong>, ne portera plus les couleurs angloyes au mois de septembre prochain.</p>
<p>Arrivé l’été dernier en provenance du Danemark, « ODM » aura inscrit 33 points en 41 affrontements toutes compétitions confondues lors du précédent exercice.</p>
<p>Nous le remercions pour cette saison, et nous lui souhaitons bonne chance dans ses projets futurs.</p>
<p>MILESKER OLI !</p>
<p>#GoHormadi | #JoTaKeIrabaziArte[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F37073%2Folivier-dame-malka|target:_blank »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzNzA3MyUyMiUyMHdpZHRoJTNEJTIyMTAwJTI1JTIyJTIwaGVpZ2h0JTNEJTIyNzQ1JTIyJTIwc2Nyb2xsaW5nJTNEJTIybm8lMjIlMjBmcmFtZWJvcmRlciUzRCUyMjAlMjIlM0UlM0MlMkZpZnJhbWUlM0U=[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-drsquoolivier-dame-malka.jpg', true, '1691424001000', '1774831529231', '1774833441751');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'hugo-reinhardt-ce-que-jrsquoai-appris-au-fil-des-ans-crsquoest-que-le-hockey-est-bien-plus-amusant-lorsque-vous-jouez-co', 'Hugo Reinhardt : « Ce que j&rsquo;ai appris au fil des ans, c&rsquo;est que le hockey est bien plus amusant lorsque vous jouez collectivement du bon hockey »', 'Lui, n&rsquo;est pas nord-américain, bien qu&rsquo;il y ait évolué, le centre suédois de 27 ans, Hugo Reinhardt, passé par la formation du Frölunda HC, apportera son style de jeu nordique à la Barre la saison prochaine. Entretien exclusif avec notre numéro 13. Un Suédois en Synerglace Ligue Magnus e', '<h4>Lui, n&rsquo;est pas nord-américain, bien qu&rsquo;il y ait évolué, le centre suédois de 27 ans, Hugo Reinhardt, passé par la formation du Frölunda HC, apportera son style de jeu nordique à la Barre la saison prochaine. Entretien exclusif avec notre numéro 13.</h4>
<figure id="attachment_16788" aria-describedby="caption-attachment-16788"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-250x300.png" alt="" width="233" height="280" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-250x300.png 250w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-853x1024.png 853w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-768x922.png 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-107x128.png 107w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-27x32.png 27w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-82x98.png 82w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt.png 1000w" sizes="auto, (max-width: 233px) 100vw, 233px" /><figcaption id="caption-attachment-16788" ><span ><em>Hugo Reinhardt ici, sous les couleurs de Tingsryds AIF (Allsvenskan) lors de la saison 2021-2022.</em></span></figcaption></figure>
<p><em><strong>Un Suédois en Synerglace Ligue Magnus est assez rare, encore plus à Anglet, comment s’est décidé ton choix et cette décision de signer ici ?</strong></em></p>
<p><span ><strong>Hugo Reinhardt :</strong></span> « Lorsque j&rsquo;ai reçu l&rsquo;appel d&rsquo;Anglet, j&rsquo;ai été très enthousiaste et encore plus enthousiaste lorsque j&rsquo;ai parlé aux entraîneurs et aux personnes impliquées dans l&rsquo;organisation de toute l&rsquo;expérience et de la façon dont ils voulaient jouer, de la belle ville et de la façon dont ils semblaient traiter les joueurs. »</p>
<p><em><strong>Tu arrives tout droit d’EIHL, le championnat britannique, tout comme Craig Puffer qui a signé à Anglet aussi, comment évalues-tu cette saison à Dundee où tu étais assistant capitaine ?</strong></em></p>
<p><span ><strong>Hugo Reinhardt :</strong></span> « La saison passée a connu des hauts et des bas, nous n&rsquo;avons pas eu le succès que nous espérions, ce qui a pesé sur l&rsquo;ambiance. C&rsquo;était un bon groupe, mais nous avons dû faire face à de nombreuses blessures, y compris les miennes. J&rsquo;ai cependant beaucoup appris de mon passage à Dundee et j&rsquo;espère pouvoir en tirer profit pour l&rsquo;avenir. »</p>
<figure id="attachment_16786" aria-describedby="caption-attachment-16786"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-1-300x255.jpeg" alt="" width="274" height="233" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-1-300x255.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-1-768x654.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-1-128x109.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-1-32x27.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-1-98x83.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-1.jpeg 899w" sizes="auto, (max-width: 274px) 100vw, 274px" /><figcaption id="caption-attachment-16786" ><span ><em>Hugo Reinhardt portait les couleurs des Stars de Dundee la saison passée en EIHL.</em></span></figcaption></figure>
<p><em><strong>Craig Puffer qui a évolué au Danemark et en Norvège, nous disait que l’EIHL était une ligue bien différente des ligues nordiques, tu confirmes ?</strong></em></p>
<p><span ><strong>Hugo Reinhardt :</strong> </span>« Je peux définitivement confirmer que notre façon de jouer, nous les joueurs nordiques, est différente de celle de l&rsquo;EIHL. J&rsquo;ai l&rsquo;impression que nous avons un style de jeu bien plus européen alors que l&rsquo;EIHL est plus influencée par l&rsquo;Amérique du Nord. C&rsquo;est le ressenti que j&rsquo;ai. »</p>
<p><em><strong>Tu es passé en junior de U16 à U20, par ce qui se fait de mieux en Europe, au HC Frölunda en Suède, ça était un vrai passage marquant pour toi d’être au sein d’une organisation comme Frölunda ?</strong></em></p>
<p><span ><strong>Hugo Reinhardt :</strong></span> « C&rsquo;est à Göteborg, où se trouve Frölunda, que j&rsquo;ai grandi et que je me considère toujours comme chez moi. En y repensant maintenant que je suis plus âgé, je comprends pourquoi ils sont les meilleurs d&rsquo;Europe, très professionnels et très doués pour former de grands joueurs de hockey. Je pense que dans ma catégorie d&rsquo;âge, il y a eu 12 joueurs recrutés par la NHL. C&rsquo;est là que j&rsquo;ai appris le hockey et que j&rsquo;ai rencontré la plupart des amis que j&rsquo;ai encore aujourd&rsquo;hui. »</p>
<p><em><strong>Penses-tu que tu aurais pu évoluer en SHL (élite suédoise) après ton junior ?</strong></em></p>
<p><strong><span >Hugo Reinhardt :</span></strong> « Je m&rsquo;entraînais avec l&rsquo;équipe de la SHL en faisant des allers-retours, j&rsquo;avais encore une année de junior quand j&rsquo;ai déménagé aux États-Unis, alors qui sait, ce qui aurait pu se passer si j&rsquo;étais resté, mais j&rsquo;ai pris un chemin différent et je suis très heureux de l&rsquo;avoir fait. »</p>
<figure id="attachment_16789" aria-describedby="caption-attachment-16789"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/D2Y5pG0X0AAa9YP-300x162.jpg" alt="" width="326" height="176" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/D2Y5pG0X0AAa9YP-300x162.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/D2Y5pG0X0AAa9YP-768x415.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/D2Y5pG0X0AAa9YP-128x69.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/D2Y5pG0X0AAa9YP-32x17.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/D2Y5pG0X0AAa9YP-98x53.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/D2Y5pG0X0AAa9YP.jpg 1000w" sizes="auto, (max-width: 326px) 100vw, 326px" /><figcaption id="caption-attachment-16789" ><span ><em>Après Frölunda, Hugo Reinhardt a passé quatre saisons en NCAA, la meilleure ligue universitaire américaine.</em></span></figcaption></figure>
<p><em><strong>Fini Frölunda, tu t’es expatrié durant 5 saisons en Amérique du Nord, en NCAA (meilleure ligue universitaire américaine), pourquoi ce changement radical et que retiens-tu de cette expérience ?</strong></em></p>
<p><span ><strong>Hugo Reinhardt :</strong> </span>« J&rsquo;aimais l&rsquo;idée d&rsquo;obtenir un diplôme universitaire tout en jouant au hockey, ce qui est très difficile à combiner en Suède. J&rsquo;ai eu l&rsquo;idée par un autre gars que je connaissais qui a déménagé et qui a absolument adoré, alors j&rsquo;ai d&rsquo;abord essayé le hockey universitaire et j&rsquo;ai senti que ça me convenait bien, alors je suis resté pour 4 ans de plus. Le fait que je me sois engagé dans la même université que mon bon ami de chez nous m&rsquo;a également aidé, car nous pouvions nous soutenir mutuellement de temps en temps. J&rsquo;ai également rencontré les coéquipiers et les amis les plus extraordinaires tout au long de mon parcours. »</p>
<p><em><strong>Finalement, tu reviens ensuite au pays en 2020 à Timrå, avec qui, tu es sacré champion d’Allsvenskan et promu dans la prestigieuse SHL, sûrement le moment le plus marquant de ta carrière ?</strong></em></p>
<p><span ><strong>Hugo Reinhardt :</strong></span> « Cette année-là a été difficile dans le monde entier à cause de l&rsquo;épidémie, mais nous avons réussi à faire le meilleur de cette saison. Ce groupe m&rsquo;a vraiment montré ce qu&rsquo;il fallait faire et à quel point les bons caractères et la mentalité de gagnant sont importants. Tout le monde se sentait impliqué, quel que soit son rôle dans l&rsquo;équipe. C&rsquo;était une belle façon de commencer ma carrière professionnelle. »</p>
<figure id="attachment_16787" aria-describedby="caption-attachment-16787"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-2-240x300.jpeg" alt="" width="211" height="264" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-2-240x300.jpeg 240w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-2-819x1024.jpeg 819w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-2-768x960.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-2-102x128.jpeg 102w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-2-26x32.jpeg 26w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-2-85x105.jpeg 85w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-2-78x98.jpeg 78w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Reinhardt-2.jpeg 1170w" sizes="auto, (max-width: 211px) 100vw, 211px" /><figcaption id="caption-attachment-16787" ><span ><em>Hugo Reinhardt champion d&rsquo;Allsvenskan et promu en SHL, ici avec Timrå IK en 2021.</em></span></figcaption></figure>
<p><em><strong>Tu évolueras donc à Anglet la saison prochaine, connais-tu un peu la France et sa ligue ?</strong></em></p>
<p><strong><span >Hugo Reinhardt :</span></strong> « J&rsquo;ai passé quelques vacances en France, jamais à Anglet, mais c&rsquo;est un très beau pays à tous points de vue. Je ne connais pas très bien la ligue, mais j&rsquo;ai entendu des gens en parler et ils disent que c&rsquo;est un hockey amusant et créatif, ce qui semble très excitant. »</p>
<p><em><strong>Penses-tu que c’est une destination idéale pour toi, qui peut de donner un nouvel élan ?</strong></em></p>
<p><strong><span >Hugo Reinhardt :</span></strong> « Je pense que oui, il est difficile de trouver un meilleur endroit pour vivre et jouer au hockey, alors je suis certain que je vais m&rsquo;y plaire. »</p>
<p><em><strong>Tu es un joueur de centre de métier, comment décrirais-tu le genre de centre que tu es, plutôt two-way ?</strong></em></p>
<p><span ><strong>Hugo Reinhardt :</strong></span> « J&rsquo;ai joué au centre pendant la plus grande partie de ma carrière, mais ces dernières années, j&rsquo;ai surtout joué à l&rsquo;aile. J&rsquo;aime jouer les deux et je me considère comme un joueur qui travaille dur, qui joue dans les deux sens et qui a de l&rsquo;énergie. »</p>
<p><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-08-1-300x225.jpg" alt="" width="280" height="210" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-08-1-300x225.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-08-1-768x576.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-08-1-128x96.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-08-1-32x24.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-08-1-98x74.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-08-1-160x120.jpg 160w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-08-1.jpg 1024w" sizes="auto, (max-width: 280px) 100vw, 280px" /></p>
<p><em><strong>Ton jeu a-t-il évolué depuis ton passage en Amérique du Nord, tu es devenu plus complet ?</strong></em></p>
<p><span ><strong>Hugo Reinhardt :</strong></span> « Mon entraîneur à l&rsquo;université en NCAA, est comme un modèle pour moi et j&rsquo;ai beaucoup appris de lui, tant sur la glace qu&rsquo;en dehors. Je pense donc que je suis un joueur plus mature, plus complet avec une meilleure routine et de meilleures connaissances qu&rsquo;auparavant. »</p>
<p><em><strong>Quels sont tes objectifs personnels et collectifs la saison prochaine à Anglet ?</strong></em></p>
<p><span ><strong>Hugo Reinhardt :</strong></span> « Personnellement, je veux être le plus important possible, je veux aider l&rsquo;équipe à réussir, mais ce que j&rsquo;ai appris au fil des ans, c&rsquo;est que le hockey est bien plus amusant lorsque vous jouez collectivement du bon hockey, alors je veux que nous gagnions autant de matchs que possible et que nous jouions notre meilleur hockey lorsque cela compte vraiment. »</p>
<figure id="attachment_16791" aria-describedby="caption-attachment-16791"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-04-300x225.jpg" alt="" width="300" height="225" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-04-300x225.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-04-768x576.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-04-128x96.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-04-32x24.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-04-98x74.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-04-160x120.jpg 160w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Hugo-Reinhardt-Dundee-Stars-04.jpg 1024w" sizes="auto, (max-width: 300px) 100vw, 300px" /><figcaption id="caption-attachment-16791" ><span ><em>Hugo Reinhardt portera le numéro 13 la saison prochaine à l&rsquo;Hormadi.</em></span></figcaption></figure>
<p><strong>Enfin, as-tu quelques mots pour les fans à l’approche du début du camp ?</strong></p>
<p><span ><strong>Hugo Reinhardt :</strong></span> « Tout ce que j&rsquo;ai à dire, c&rsquo;est que j&rsquo;ai hâte de vous rencontrer et que je vais faire de mon mieux pour apprendre le français (rires). »</p>
<p><em><span >Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</span></em></p>
', 'Interview', '/images/news/hugo-reinhardt-ce-que-jrsquoai-appris-au-fil-des-ans-crsquoest-que-le-hockey-est.png', true, '1691245065000', '1774831530229', '1774833441752');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'sam-dunn-cette-equipe-ce-nrsquoest-pas-seulement-nous-les-joueurs-mais-nous-tous-les-supporteurs-les-joueurs-et-le-perso', 'Sam Dunn : « Cette équipe, ce n&rsquo;est pas seulement nous les joueurs, mais nous tous – les supporteurs, les joueurs et le personnel »', 'Coéquipier de Keith Getson à l&rsquo;Université de Saint-Mary&rsquo;s, le défenseur canadien, Sam Dunn, doté d&rsquo;un fort gabarit et d&rsquo;une aisance dans les deux sens de la glace, a également choisi de poursuivre son chemin à l&rsquo;Hormadi après avoir terminé sa saison en ECHL. Entretien e', '<h4>Coéquipier de Keith Getson à l&rsquo;Université de Saint-Mary&rsquo;s, le défenseur canadien, Sam Dunn, doté d&rsquo;un fort gabarit et d&rsquo;une aisance dans les deux sens de la glace, a également choisi de poursuivre son chemin à l&rsquo;Hormadi après avoir terminé sa saison en ECHL. Entretien exclusif avec notre numéro 46.</h4>
<figure id="attachment_16823" aria-describedby="caption-attachment-16823"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/h53cscq69zjl96st-225x300.jpg" alt="" width="242" height="323" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/h53cscq69zjl96st-225x300.jpg 225w, https://pro.hormadi.fr/wp-content/uploads/2023/08/h53cscq69zjl96st-96x128.jpg 96w, https://pro.hormadi.fr/wp-content/uploads/2023/08/h53cscq69zjl96st-24x32.jpg 24w, https://pro.hormadi.fr/wp-content/uploads/2023/08/h53cscq69zjl96st-74x98.jpg 74w, https://pro.hormadi.fr/wp-content/uploads/2023/08/h53cscq69zjl96st.jpg 450w" sizes="auto, (max-width: 242px) 100vw, 242px" /><figcaption id="caption-attachment-16823" ><span ><em>Comme Keith Getson, Sam Dunn débarque à l&rsquo;Hormadi en provenance de Saint-Mary&rsquo;s (USports).</em></span></figcaption></figure>
<p><em><strong>Tu vas découvrir pour la toute première fois à partir du mois d’août, une nouvelle expérience en France, comment abordes-tu cela ?</strong></em></p>
<p><span ><strong>Sam Dunn :</strong></span> « Je suis absolument ravie de venir en France. L&rsquo;impatience de rejoindre Anglet a été alimentée par toutes les choses positives que j&rsquo;ai entendues à propos de la ville et de l&rsquo;équipe, ce qui rend cette opportunité encore plus excitante. J&rsquo;ai eu la chance de voyager dans des pays comme l&rsquo;Allemagne, la Suède, la Lettonie et la République Tchèque, mais visiter la France sera une expérience entièrement nouvelle et unique pour moi. Heureusement, je parle français, donc je vois cela comme une chance d&rsquo;utiliser la langue et de m&rsquo;immerger complètement dans sa culture. J&rsquo;ai hâte de voyager avec l&rsquo;équipe dans différentes villes de France, avec l&rsquo;objectif de gagner chaque match, et de savourer l&rsquo;opportunité d&rsquo;explorer et d&rsquo;apprécier la beauté du pays. »</p>
<p><em><strong>Comment s’est concrétisée ta signature à Anglet, pourquoi ce choix ?</strong></em></p>
<p><strong><span >Sam Dunn :</span></strong> « La décision de signer pour Anglet a été amenée par Keith Getson, qui avait déjà rejoint l&rsquo;équipe et avait mentionné leur besoin de défenseurs. Les entraîneurs et moi-même avons eu plusieurs discussions sur des sujets tels que l&rsquo;équipe, la ville et d&rsquo;autres détails cruciaux. En fin de compte, j&rsquo;ai choisi Anglet parce qu&rsquo;il semblait correspondre parfaitement à ma carrière de hockeyeur et à ma vie personnelle. La forte culture de l&rsquo;équipe et son ambition de réussir correspondent à mes propres aspirations, ce qui en fait l&rsquo;endroit idéal pour poursuivre mon parcours dans le hockey. Je suis enthousiaste à l&rsquo;idée de ce nouveau chapitre et j&rsquo;ai hâte de contribuer de mon mieux au succès d&rsquo;Anglet sur la glace. »</p>
<p><em><strong>Tu as donc consulté Keith Getson, qui était avec toi à Saint-Mary’s (USports) et qui sera à Anglet aussi la saison prochaine ?</strong></em></p>
<p><span ><strong>Sam Dunn :</strong> </span>« Oui, au cours des deux derniers mois, j&rsquo;ai été en contact avec Keith Getson, qui était également avec moi à Saint Mary&rsquo;s (Usports), et j&rsquo;ai pris contact avec d&rsquo;autres joueurs, notamment Colin Doyle, Cole Thiessen et Dylan St. Cyr. J&rsquo;ai eu la chance de connaître plusieurs de ces joueurs pour les avoir déjà affrontés ou côtoyés. J&rsquo;ai également été réconforté par le fait que nous rejoignions une nouvelle équipe, dans une nouvelle ligue et dans un pays différent. Je crois fermement que ces joueurs seront tous des ajouts précieux à l&rsquo;équipe et je suis vraiment impatient de voir comment nos efforts contribueront au succès de l&rsquo;équipe sur la glace. »</p>
<figure id="attachment_16820" aria-describedby="caption-attachment-16820"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/36275763_1772188379505013_1244923702701719552_n-300x200.jpg" alt="" width="368" height="245" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/36275763_1772188379505013_1244923702701719552_n-300x200.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/36275763_1772188379505013_1244923702701719552_n-1024x683.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/08/36275763_1772188379505013_1244923702701719552_n-768x512.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/36275763_1772188379505013_1244923702701719552_n-128x85.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/36275763_1772188379505013_1244923702701719552_n-32x21.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/36275763_1772188379505013_1244923702701719552_n-360x240.jpg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/08/36275763_1772188379505013_1244923702701719552_n-98x65.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/36275763_1772188379505013_1244923702701719552_n.jpg 1500w" sizes="auto, (max-width: 368px) 100vw, 368px" /><figcaption id="caption-attachment-16820" ><span ><em>Sam Dunn ici, sous le chandail des Remparts du Québec (LHJMQ), avant d&rsquo;être invité au camp de développement de Columbus.</em></span></figcaption></figure>
<p><strong><em>Tu es passé lors de ton junior par la LHJMQ chez les Remparts du Québec, avec de belles performances, ça était le point de départ de ta carrière ?</em></strong></p>
<p><span ><strong>Sam Dunn :</strong></span> « Oui, jouer dans la LHJMQ avec les Remparts de Québec a marqué un point de départ crucial dans ma carrière de hockeyeur. Dès le début de ma carrière de hockeyeur, je l&rsquo;ai abordée avec dévouement et sérieux. Lorsque j&rsquo;ai été repêché dans la Ligue de hockey de l&rsquo;Ontario, j&rsquo;ai su que je voulais poursuivre ma passion et m&rsquo;efforcer d&rsquo;atteindre les plus hauts niveaux de jeu. Après avoir passé quelques années en Junior A, j&rsquo;ai eu l&rsquo;incroyable opportunité de signer avec les Remparts de Québec, où j&rsquo;ai passé deux années transformatrices. Ces deux années ont été cruciales pour ma croissance en tant que joueur, et je l&rsquo;attribue à la fantastique culture d&rsquo;équipe et aux opportunités de développement offertes par les Remparts. Mon séjour au Québec m&rsquo;a permis d&rsquo;améliorer considérablement mes compétences et m&rsquo;a ouvert des portes pour progresser dans ma carrière. »</p>
<p><em><strong>D’ailleurs, cela t’avait permis d’être invité au camp de développement des Blue Jackets de Columbus (NHL) en 2018 après ton junior, que retiens-tu de cette expérience ?</strong></em></p>
<p><span ><strong>Sam Dunn :</strong> </span>« L&rsquo;invitation au camp de développement des Columbus Blue Jackets (NHL) en 2018 reste un souvenir précieux pour moi. C&rsquo;était vraiment une expérience incroyable, d&rsquo;être entouré d&rsquo;un tel niveau de talent venant du monde entier. Le fait d&rsquo;être témoin du calibre des joueurs présents au camp a été pour moi une grande source de motivation pour affiner mes compétences et poursuivre mon développement. Le camp m&rsquo;a permis d&rsquo;apprendre et d&rsquo;évaluer les aspects de mon jeu que je devais améliorer. Dans l&rsquo;ensemble, ce fut une opportunité fantastique qui a laissé un impact durable sur mon parcours au hockey. »</p>
<figure id="attachment_16822" aria-describedby="caption-attachment-16822"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/Fo3b4leXwAMeA0E-300x200.jpeg" alt="" width="401" height="267" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/Fo3b4leXwAMeA0E-300x200.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Fo3b4leXwAMeA0E-1024x683.jpeg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Fo3b4leXwAMeA0E-768x512.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Fo3b4leXwAMeA0E-1536x1024.jpeg 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Fo3b4leXwAMeA0E-2048x1365.jpeg 2048w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Fo3b4leXwAMeA0E-128x85.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Fo3b4leXwAMeA0E-32x21.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Fo3b4leXwAMeA0E-360x240.jpeg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Fo3b4leXwAMeA0E-98x65.jpeg 98w" sizes="auto, (max-width: 401px) 100vw, 401px" /><figcaption id="caption-attachment-16822" ><span ><em>Sam Dunn sur cette photo, deuxième en partant de la gauche, numéro 5 avec le « A ».</em></span></figcaption></figure>
<p><strong><em>Tu as ensuite poursuivi ton parcours en USports durant 4 saisons, au sein de l’une des meilleures universités du pays à Saint-Mary&rsquo;s, comment juges-tu ta progression durant ce temps-là ?</em></strong></p>
<p><span ><strong>Sam Dunn :</strong> </span>« Mes quatre années à Saint Mary&rsquo;s ne seront jamais oubliées. Même si nous jouions moins de matchs que dans la plupart des ligues, nous pouvions nous entraîner tous les jours et développer nos compétences. Mon développement a fait de grands progrès pendant ce séjour et je pense que cela m&rsquo;a aidé à développer un jeu plus mature. Au-delà de ça, je pense que cela m&rsquo;a aidé à mûrir en tant que joueur et en tant que personne. L&rsquo;un des aspects les plus significatifs de mon séjour à SMU a été l&rsquo;importance du leadership, un aspect que j&rsquo;aimerais également apporter à Anglet. Mais, je dirais que quoi qu&rsquo;il arrive, je me concentre sur le fait d&rsquo;être le meilleur joueur possible pour l&rsquo;équipe. »</p>
<p><em><strong>Tu as bouclé la saison dernière en ECHL, chez les professionnels, dans le second club affilié de Montréal aux Lions de Trois-Rivières, cela était une récompense pour toi ?</strong></em></p>
<p><span ><strong>Sam Dunn :</strong></span> « Oui, terminer la saison dernière dans l&rsquo;ECHL avec les professionnels de la deuxième filiale montréalaise des Lions de Trois-Rivières a été pour moi une expérience enrichissante. Après avoir participé aux championnats nationaux avec SMU, j&rsquo;ai été contacté pour rejoindre les Lions, et j&rsquo;étais vraiment reconnaissant d&rsquo;avoir cette chance. Cela m&rsquo;a permis de constater que mon travail acharné portait ses fruits. L&rsquo;ECHL m&rsquo;a offert une expérience d&rsquo;apprentissage précieuse, car le niveau de compétition, le rythme, les compétences et le jeu en général étaient stimulants et m&rsquo;ont motivé à continuer de chercher à m&rsquo;améliorer. Les Lions de Trois-Rivières se sont avérés une organisation incroyablement professionnelle qui traitait bien ses joueurs, et je chéris les liens que j&rsquo;ai établis pendant mon séjour avec eux. »</p>
<figure id="attachment_16821" aria-describedby="caption-attachment-16821"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/Dunn-1-300x298.jpeg" alt="" width="320" height="318" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/Dunn-1-300x298.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Dunn-1-150x150.jpeg 150w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Dunn-1-768x763.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Dunn-1-128x128.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Dunn-1-32x32.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Dunn-1-200x200.jpeg 200w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Dunn-1-80x80.jpeg 80w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Dunn-1-98x98.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Dunn-1.jpeg 828w" sizes="auto, (max-width: 320px) 100vw, 320px" /><figcaption id="caption-attachment-16821" ><span ><em>Sam Dunn a terminé la saison dernière en ECHL, avec les Lions des Trois-Rivières, club affilié des Canadiens de Montréal.</em></span></figcaption></figure>
<p><em><strong>Avais-tu la possibilité justement de continuer ton parcours en Amérique du Nord, en ECHL par exemple ?</strong></em></p>
<p><strong><span >Sam Dunn :</span></strong> « Oui, j&rsquo;ai eu la possibilité de poursuivre ma carrière en Amérique du Nord, notamment avec Trois Rivières cette saison. Cependant, j&rsquo;ai pris la décision de signer avec Anglet, car cela répondait à un rêve que je caressais depuis mon plus jeune âge. Ayant voyagé en Europe pour jouer au hockey lorsque j&rsquo;étais enfant, j&rsquo;ai toujours su que je voulais y jouer un jour. Après mûre réflexion, j&rsquo;ai pensé qu&rsquo;Anglet serait l&rsquo;endroit idéal pour poursuivre ma carrière de hockeyeur. »</p>
<p><em><strong>Tu es donc un défenseur droitier, au physique imposant sur la glace, a priori à l’aise dans les deux sens de la glace, quel type défenseur es-tu selon toi ?</strong></em></p>
<p><span ><strong>Sam Dunn :</strong></span> « En tant que défenseur droitier de grande taille, je suis fier d&rsquo;être un joueur polyvalent à double sens. J&rsquo;excelle dans diverses positions, que ce soit en supériorité numérique, sur les tirs de barrage ou sur le jeu régulier. Mon objectif principal est de sécuriser la zone défensive rapidement et efficacement afin de créer des transitions rapides vers la zone offensive. En contribuant à la fois à l&rsquo;offensive et à la défensive, je vise à être un joueur bien équilibré qui donne le ton à l&rsquo;équipe et aide à atteindre le succès sur tous les fronts. »</p>
<p><em><strong>Quels sont tes objectifs à l’Hormadi la saison prochaine ?</strong></em></p>
<p><strong><span >Sam Dunn :</span> </strong>« Mes objectifs à l&rsquo;Hormadi pour la prochaine saison sont d&rsquo;avoir une saison réussie à la fois personnellement et en tant qu&rsquo;équipe. Je suis enthousiasmé par le potentiel de notre groupe de joueurs talentueux et j&rsquo;ai l&rsquo;intention de contribuer de manière significative à notre succès. Je me concentrerai sur l&rsquo;amélioration de mes compétences, en devenant un atout fiable à chaque match, et en créant cette culture de la victoire. »</p>
<figure id="attachment_16824" aria-describedby="caption-attachment-16824"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/SMU-Dal-021123-0433-300x200.jpg" alt="" width="401" height="267" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/SMU-Dal-021123-0433-300x200.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/SMU-Dal-021123-0433-1024x683.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/08/SMU-Dal-021123-0433-768x512.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/08/SMU-Dal-021123-0433-1536x1024.jpg 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/08/SMU-Dal-021123-0433-2048x1365.jpg 2048w, https://pro.hormadi.fr/wp-content/uploads/2023/08/SMU-Dal-021123-0433-128x85.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/SMU-Dal-021123-0433-32x21.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/SMU-Dal-021123-0433-360x240.jpg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/08/SMU-Dal-021123-0433-98x65.jpg 98w" sizes="auto, (max-width: 401px) 100vw, 401px" /><figcaption id="caption-attachment-16824" ><span ><em>Sam Dunn arborera le numéro 46 la saison prochaine à l&rsquo;Hormadi.</em></span></figcaption></figure>
<p><em><strong>Enfin, as-tu quelques mots pour les fans avant la reprise dans quelques semaines ?</strong></em></p>
<p><strong><span >Sam Dunn :</span></strong> « Avant toute chose, permettez-moi de vous dire à quel point je suis ravi et reconnaissant de pouvoir compter sur votre soutien. Une saison passionnante nous attend, et je ne pourrais pas être plus heureux de la partager avec des supporteurs aussi extraordinaires que vous. Cette équipe, ce n&rsquo;est pas seulement nous les joueurs, mais nous tous &#8211; les supporteurs, les joueurs et le personnel. Créons une atmosphère électrisante dans les tribunes, en faisant de notre maison une forteresse et un endroit intimidant pour tout adversaire. Nos victoires seront vos victoires, et nos défaites ne feront que nous rendre plus forts à mesure que nous apprendrons et grandirons ensemble. En attendant, allez Hormadi ! »</p>
<p><em><span >Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</span></em></p>
', 'Interview', '/images/news/sam-dunn-cette-equipe-ce-nrsquoest-pas-seulement-nous-les-joueurs-mais-nous-tous.png', true, '1691076738000', '1774831532024', '1774833441752');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'match-concert-1er-septembresoutien-au-club', '[MATCH + CONCERT 1ER SEPTEMBRE/SOUTIEN AU CLUB]', '[vc_row][vc_column][vc_column_text]L’Anglet Hormadi Pays Basque fait appel à vous !? Un évènement unique, puisque nous accueillerons ERICK BAERT, l’ovni de l’imitation. Ce dernier, en pleine tournée européenne, pose ses valises à la Barre avec ses musiciens, le temps d’un soir pour vous faire revivr', '<div ><p>[vc_row][vc_column][vc_column_text]L’Anglet Hormadi Pays Basque fait appel à vous !?</p>
<p><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/08/Copie-de-Copie-de-MATCH-AFFICHE--300x184.jpg" alt="" width="368" height="226" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-Copie-de-MATCH-AFFICHE--300x184.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-Copie-de-MATCH-AFFICHE--128x79.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-Copie-de-MATCH-AFFICHE--32x20.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-Copie-de-MATCH-AFFICHE--98x60.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/08/Copie-de-Copie-de-MATCH-AFFICHE-.jpg 570w" sizes="auto, (max-width: 368px) 100vw, 368px" /></p>
<p>Un évènement unique, puisque nous accueillerons ERICK BAERT, l’ovni de l’imitation. Ce dernier, en pleine tournée européenne, pose ses valises à la Barre avec ses musiciens, le temps d’un soir pour vous faire revivre plus de 100 voix différentes d’artistes connus mondialement et de toutes les époques : Johnny Hallyday, Coldplay, Orelsan, Christophe Maé, Dire Straits, ZZ Top, Cure, et bien d’autres encore.</p>
<p>Il y en aura pour tous les goûts, alors l’ensemble du Club de l’Anglet Hormadi Pays Basque compte sur vous pour vous manifester en masse dans les tribunes. Vous aiderez grandement le Club financièrement en participant à cette soirée, et cela permettrait également de lancer définitivement cette nouvelle saison tous ensemble, avant la reprise du championnat le samedi 09 septembre.</p>
<p>N’hésitez pas à en parler autour de vous, à partager ce post, et bien évidemment, de prendre vos places si ce n’est pas déjà fait, sur ce même site, dans l&rsquo;onglet billetterie puis billetterie en ligne.</p>
<p>?Pour les abonné(e)s et futur(e)s abonné(e)s, vous bénéficiez d’un tarif réduit pour le concert, afin d’en profiter, veuillez confirmer votre présence par mail (contact@hormadi.fr), par téléphone (O5.59.57.17.37) ou lors de votre passage à la patinoire durant le mois d’août.</p>
<p>#GoHormadi | #JoTaKeIrabaziArte[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][/vc_column][/vc_row]</p>
</div>', 'Vie du Club', '/images/news/match-concert-1er-septembresoutien-au-club.jpg', true, '1690903984000', '1774831534058', '1774833441752');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'keith-getson-je-souhaite-que-lrsquoon-transmette-du-plaisir-et-des-emotions-aux-fans-cette-saison', 'Keith Getson : « Je souhaite que l&rsquo;on transmette du plaisir et des émotions aux fans cette saison »', 'Il sera l&rsquo;une des fers de lances de l&rsquo;offensive basque la saison prochaine, le capitaine de l&rsquo;Université de Saint-Mary&rsquo;s, Keith Getson, découvrira la France et la Synerglace Ligue Magnus à partir du mois de septembre. Entretien exclusif avec notre numéro 16. Tu débarques tout', '<h4>Il sera l&rsquo;une des fers de lances de l&rsquo;offensive basque la saison prochaine, le capitaine de l&rsquo;Université de Saint-Mary&rsquo;s, Keith Getson, découvrira la France et la Synerglace Ligue Magnus à partir du mois de septembre. Entretien exclusif avec notre numéro 16.</h4>
<figure id="attachment_16753" aria-describedby="caption-attachment-16753"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/8jyrkjx9f60fj9n3-225x300.jpg" alt="" width="245" height="326" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/8jyrkjx9f60fj9n3-225x300.jpg 225w, https://pro.hormadi.fr/wp-content/uploads/2023/07/8jyrkjx9f60fj9n3-96x128.jpg 96w, https://pro.hormadi.fr/wp-content/uploads/2023/07/8jyrkjx9f60fj9n3-24x32.jpg 24w, https://pro.hormadi.fr/wp-content/uploads/2023/07/8jyrkjx9f60fj9n3-74x98.jpg 74w, https://pro.hormadi.fr/wp-content/uploads/2023/07/8jyrkjx9f60fj9n3.jpg 450w" sizes="auto, (max-width: 245px) 100vw, 245px" /><figcaption id="caption-attachment-16753" ><span ><em>Keith Getson débarque de l&rsquo;une des meilleures universités d&rsquo;USports, de Saint-Mary&rsquo;s, où il était le capitaine.</em></span></figcaption></figure>
<p><em><strong>Tu débarques tout droit d’USports, de l’Université de Saint-Mary’s, pour ta première expérience en Europe avec Anglet, quels sentiments demeurent chez toi avant la reprise ?</strong></em></p>
<p><span ><strong>Keith Getson :</strong> </span>« Avant ce début de saison et de cette nouvelle aventure, j&rsquo;ai vraiment hâte de rencontrer tous les membres de l&rsquo;équipe et de découvrir l&rsquo;Europe pour la première fois. Ça va être, j&rsquo;en suis sûr, une riche expérience. L&rsquo;excitation est présente depuis que je me suis engagé à Anglet. »</p>
<p><em><strong>Tu as d&rsquo;ailleurs rapidement trouvé un accord avec Anglet, quelles ont été les raisons de ce choix ?</strong></em></p>
<p><span ><strong>Keith Getson :</strong> </span>« Mes conversations avec le staff d&rsquo;Anglet, ont toutes été très positives du premier moment où ils m&rsquo;ont contacté jusqu&rsquo;à la signature, et il m&rsquo;a semblé que c&rsquo;était une excellente opportunité dès le départ, je n&rsquo;ai donc pas hésité à donner mon accord. »</p>
<p><strong><em>Connaissais-tu la France avant de signer à l&rsquo;Hormadi ?</em></strong></p>
<p><span ><strong>Keith Getson :</strong></span> « Non du tout, pour le coup, je ne connais pas très bien la France, car ça va être la première fois que je vais me rendre en Europe. Cependant, j&rsquo;ai entendu beaucoup de bonnes choses sur la région, le niveau et l&rsquo;engouement autour du hockey sur glace à Anglet, j&rsquo;ai donc hâte d&rsquo;en faire l&rsquo;expérience moi-même. »</p>
<figure id="attachment_16751" aria-describedby="caption-attachment-16751"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/FeT6vtvXkAQDHcN-300x200.jpeg" alt="" width="352" height="234" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/FeT6vtvXkAQDHcN-300x200.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/FeT6vtvXkAQDHcN-1024x683.jpeg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/07/FeT6vtvXkAQDHcN-768x512.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/FeT6vtvXkAQDHcN-128x85.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/FeT6vtvXkAQDHcN-32x21.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/FeT6vtvXkAQDHcN-360x240.jpeg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/07/FeT6vtvXkAQDHcN-98x65.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/FeT6vtvXkAQDHcN.jpeg 1440w" sizes="auto, (max-width: 352px) 100vw, 352px" /><figcaption id="caption-attachment-16751" ><span ><em>S</em><em>ur cette photo, deuxième en partant de la gauche, Keith Getson avec le « C » et son coéquipier et futur défenseur angloy, Sam Dunn tout à droite.</em></span></figcaption></figure>
<p><em><strong>Tu ne seras pas le seul de Saint-Mary’s à rejoindre l’Hormadi, puisque ton coéquipier Sam Dunn prend la même direction, c’est rassurant pour toi ?</strong></em></p>
<p><strong><span >Keith Getson :</span></strong> « Oui définitivement, le fait que Sam ait également rejoint l&rsquo;Hormadi est rassurant. La transition sera plus facile pour moi comme pour lui, mais j&rsquo;ai hâte de rencontrer tous mes autres coéquipiers. Nous nous connaissons depuis un bon moment, puisqu&rsquo;on est arrivé à l&rsquo;Université de Saint-Mary la même année, en 2019, depuis, nous avons toujours évolué ensemble, et je suis très content de l&rsquo;avoir à mes côtés de nouveau. »</p>
<p><em><strong>Toi aussi, comme Sam, tu es passé en junior par la LHJMQ, avec Charlottetown puis Halifax, avec des statistiques qui parlent d’elles-mêmes, avais-tu dans un coin de ta tête, cet espoir d’être repêché en NHL ?</strong></em></p>
<p><span ><strong>Keith Getson :</strong></span> « C&rsquo;est compliqué, évidemment, comme toujours productif en junior, c&rsquo;est le rêve d&rsquo;être repêché, mais sincèrement, je n&rsquo;y ai jamais accordé trop d&rsquo;importance non plus. Il faut rester réaliste, et puis je pense qu&rsquo;il y a d&rsquo;autres très belles opportunités qui ont le mérite d&rsquo;être vécu lorsque nous sommes pas repêchés, des fois même plus intéressantes. »</p>
<p><strong><em><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.29.44-269x300.png" alt="" width="254" height="283" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.29.44-269x300.png 269w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.29.44-115x128.png 115w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.29.44-29x32.png 29w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.29.44-88x98.png 88w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.29.44.png 650w" sizes="auto, (max-width: 254px) 100vw, 254px" />En 2019, tu as quand même eu le privilège d’être invité au camp des rookies des Rangers de New York, c’était une sacrée opportunité et une belle expérience je suppose ?</em></strong></p>
<p><span ><strong>Keith Getson</strong> <strong>:</strong></span> « Oh oui, le camp des recrues des New York Rangers a été une expérience formidable pour moi et je suis reconnaissant d&rsquo;y avoir été invité à ce moment-là. Il est toujours important d&rsquo;apprendre des joueurs et des individus du niveau suivant pour améliorer ses propres compétences. J&rsquo;ai pu côtoyer des gars comme Kaapo Kakko, Adam Fox ou encore Igor Shesterkin, qui sont tous devenus aujourd&rsquo;hui, des références mondiales à leurs postes. »</p>
<p><em><strong>Tu as connu la Memorial Cup, le tournoi que tous les juniors canadiens souhaitent remporter à cet âge, quels souvenirs gardes-tu ?</strong></em></p>
<p><span ><strong>Keith Getson :</strong></span> « Mes souvenirs de la Coupe Memoriale sont tout simplement extraordinaires. Même si notre équipe s&rsquo;est inclinée de justesse en finale, c&rsquo;est une autre expérience dont j&rsquo;ai tiré profit et que je ne considère pas comme acquise. »</p>
<p><em><strong>Tu avais d’ailleurs fait le tour des réseaux sociaux pour cette fameuse charge en 2019 à Halifax lors de la Memorial Cup, tu t’en souviens encore ?</strong></em></p>
<p><span ><strong>Keith Getson :</strong></span> « Oui elle reste gravée, on m&rsquo;a souvent posé des questions sur cette charge (rires). Pour résumer, mon équipe était déjà en situation d&rsquo;infériorité numérique, alors si j&rsquo;étais resté sur la glace ou si j&rsquo;avais changé, nous aurions été menés 5 contre 3. C&rsquo;était une collision solide, mais je n&rsquo;ai pas été blessé par le coup, alors je suis heureux de pouvoir y repenser aujourd&rsquo;hui et d&rsquo;en rire. »</p>
<figure id="attachment_16756" aria-describedby="caption-attachment-16756"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.31.25-217x300.png" alt="" width="224" height="310" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.31.25-217x300.png 217w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.31.25-741x1024.png 741w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.31.25-93x128.png 93w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.31.25-23x32.png 23w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.31.25-71x98.png 71w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.31.25.png 768w" sizes="auto, (max-width: 224px) 100vw, 224px" /><figcaption id="caption-attachment-16756" ><span ><em>Keith Getson a inscrit 16 buts la saison dernière en USports.</em></span></figcaption></figure>
<p><em><strong>Après ça, tu as continué ton parcours à Saint-Mary’s en USports, où tu étais le capitaine, tout comme à Charlottetown, tu as en toi ce leadership capable de porter un groupe ?</strong></em></p>
<p><strong><span >Keith Getson</span> </strong>: « Oui, je crois que j&rsquo;ai des qualités de leader au sein d&rsquo;une équipe et dans les équipes pour lesquelles j&rsquo;ai déjà joué, que ce soit à Saint-Mary&rsquo;s ou même lorsque j&rsquo;étais en junior, j&rsquo;ai régulièrement eu des responsabilités. C&rsquo;est ce qui fait partie de ma personne. »</p>
<p><em><strong>Tu es un centre, capable de scorer comme tu l’as souvent fait lors des dernières saisons, quelles sont tes qualités si tu devais décrire le style de centre que tu es ?</strong></em></p>
<p><strong><span >Keith Getson :</span></strong> « En tant que joueur, je me décrirais comme un centre à deux voies. J&rsquo;ai la capacité de contribuer à l&rsquo;offensive, mais j&rsquo;ai aussi aimé m&rsquo;améliorer du côté défensif de la rondelle et j&rsquo;aime être un joueur fiable auquel on peut faire confiance dans son propre camp dans toutes les situations. »</p>
<p><em><strong>Tu sembles être parti pour jouer les premiers rôles à Anglet la saison prochaine, c’est ce que tu aimes aussi ?</strong></em></p>
<p><strong><span >Keith Getson :</span></strong> « Je m&rsquo;efforce de jouer un rôle important dans toutes les équipes auxquelles j&rsquo;ai été associé. Toutefois, je jouerai le rôle dont l&rsquo;équipe a besoin pour assurer son succès, car pour moi, c&rsquo;est ce qui prime avant tout. »</p>
<figure id="attachment_16752" aria-describedby="caption-attachment-16752"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.21.09-170x300.png" alt="" width="170" height="300" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.21.09-170x300.png 170w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.21.09-73x128.png 73w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.21.09-18x32.png 18w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.21.09-56x98.png 56w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-28-a-14.21.09.png 576w" sizes="auto, (max-width: 170px) 100vw, 170px" /><figcaption id="caption-attachment-16752" ><em><span >Keith Getson arborera le numéro 16 à l&rsquo;Hormadi lors du prochain exercice.</span></em></figcaption></figure>
<p><em><strong>Parlons d’objectifs pour la saison prochaine, quels sont les tiens ?</strong></em></p>
<p><span ><strong>Keith Getson :</strong></span> « Je n&rsquo;ai pas d&rsquo;objectifs chiffrés pour le moment, mais je dirais que mon but est de progresser au mieux de mes capacités pendant la saison et de créer des liens avec mes coéquipiers pour former la meilleure équipe possible. Sur le plan sportif, je souhaite que l&rsquo;on transmette du plaisir et des émotions aux fans, si nous arrivons à faire cela, nul doute que la saison sera belle. »</p>
<p><em><strong>Enfin, pour conclure, as-tu quelques mots pour les fans à quelques semaines de la reprise ?</strong></em></p>
<p><span ><strong>Keith Getson :</strong></span> « Pour les supporters, je suis très enthousiaste à l&rsquo;idée de jouer devant vous cette saison, j&rsquo;espère que ce sera une année pleine de succès que nous pourrons savourer ensemble. Mon arrivée à Anglet s&rsquo;approche, j&rsquo;ai donc hâte de tous vous rencontrer. On se dit à très vite ! »</p>
<p><span ><em>Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</em></span></p>
', 'Interview', '/images/news/keith-getson-je-souhaite-que-lrsquoon-transmette-du-plaisir-et-des-emotions-aux-.png', true, '1690819393000', '1774831536056', '1774833441753');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'vincent-deslauriers-aux-fans-drsquoanglet-je-veux-vous-dire-que-vous-allez-voir-sur-la-patinoire-un-joueur-electrisant-e', 'Vincent Deslauriers : « Aux fans d&rsquo;Anglet, je veux vous dire que vous allez voir sur la patinoire un joueur électrisant, énergétique qui ne lâche jamais »', 'Il sera le seul pur Québécois de souche de l&rsquo;effectif angloy mais pas que, l&rsquo;ailier droit, Vincent Deslauriers, pose valises à Anglet et amène avec lui tout son bagage offensif et ses qualités de finisseur. Entretien exclusif avec « Délo », notre futur numéro 21. De St-Anne-des-Plaines à', '<h4>Il sera le seul pur Québécois de souche de l&rsquo;effectif angloy mais pas que, l&rsquo;ailier droit, Vincent Deslauriers, pose valises à Anglet et amène avec lui tout son bagage offensif et ses qualités de finisseur. Entretien exclusif avec « Délo », notre futur numéro 21.</h4>
<figure id="attachment_16741" aria-describedby="caption-attachment-16741"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/25546-294x300.jpg" alt="" width="372" height="379" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/25546-294x300.jpg 294w, https://pro.hormadi.fr/wp-content/uploads/2023/07/25546-125x128.jpg 125w, https://pro.hormadi.fr/wp-content/uploads/2023/07/25546-32x32.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/25546-96x98.jpg 96w, https://pro.hormadi.fr/wp-content/uploads/2023/07/25546.jpg 480w" sizes="auto, (max-width: 372px) 100vw, 372px" /><figcaption id="caption-attachment-16741" ><span ><em>En provenance de l&rsquo;Université de Moncton, où il était le capitaine, Vincent Deslauriers portera le maillot angloy au mois de septembre. @Photo Univ. of Moncton</em></span></figcaption></figure>
<p><strong><em>De St-Anne-des-Plaines à Sherbrooke en passant par Baie-Comeau ou encore Moncton, te voilà aujourd’hui à l’Hormadi et en professionnel à 26 ans, comment tu te sens actuellement ?</em></strong></p>
<p><span ><strong>Vincent Deslauriers :</strong> </span>« Actuellement, je me sens extrêmement excité et honoré de rejoindre l&rsquo;équipe d&rsquo;Anglet. Mon parcours jusqu&rsquo;ici a été rempli de défis et de succès. Je suis prêt à tout donner sur la glace et à apporter mon meilleur jeu pour l&rsquo;Hormadi. »</p>
<p><em><strong>Tu as passé tout ton junior en LHJMQ, ce qui se fait de mieux au Québec, tu y as bien performé chez le Phoenix et au Drakkar, ça était le premier tremplin de ta jeune carrière ?</strong></em></p>
<p><span ><strong>Vincent Deslauriers :</strong></span> « Absolument, mes années passées dans la LHJMQ ont été cruciales pour mon développement. Jouer pour le Phoenix et le Drakkar m&rsquo;a permis de gagner en expérience et de me faire remarquer en tant que joueur talentueux. C&rsquo;était en effet un des premiers pas importants de ma carrière de hockeyeur. »</p>
<p><strong><em>Tu as ensuite poursuivi ton chemin en USports, à l’Université Moncton, avec là aussi, de très belles productions offensives dès ton arrivée et ce, jusqu’à la saison dernière, comment juges-tu ta progression durant ces 5 saisons à Moncton ?</em></strong></p>
<p><span ><strong>Vincent Deslauriers :</strong></span> « Mon passage à l&rsquo;Université Moncton, chez les Aigles Bleus, a été très bénéfique pour ma progression en tant que joueur mais également humainement. J&rsquo;ai réussi à maintenir des performances offensives satisfaisantes tout au long de ces cinq saisons. Cela m&rsquo;a aidé à améliorer mon jeu dans différents aspects et à gagner en confiance sur la glace. »</p>
<figure id="attachment_16737" aria-describedby="caption-attachment-16737"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/1a14a0ddeb6d3642bd414841383393a8-cropped-269x300.jpeg" alt="" width="282" height="314" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/1a14a0ddeb6d3642bd414841383393a8-cropped-269x300.jpeg 269w, https://pro.hormadi.fr/wp-content/uploads/2023/07/1a14a0ddeb6d3642bd414841383393a8-cropped-115x128.jpeg 115w, https://pro.hormadi.fr/wp-content/uploads/2023/07/1a14a0ddeb6d3642bd414841383393a8-cropped-29x32.jpeg 29w, https://pro.hormadi.fr/wp-content/uploads/2023/07/1a14a0ddeb6d3642bd414841383393a8-cropped-88x98.jpeg 88w, https://pro.hormadi.fr/wp-content/uploads/2023/07/1a14a0ddeb6d3642bd414841383393a8-cropped.jpeg 500w" sizes="auto, (max-width: 282px) 100vw, 282px" /><figcaption id="caption-attachment-16737" ><span ><em>Vincent Deslauriers était le solide capitaine à Moncton.</em></span></figcaption></figure>
<p><strong><em>Tu étais notamment le capitaine de ton équipe la saison dernière, outre tes performances sur la glace, tu sais aussi apporter du leadership à un vestiaire ?</em></strong></p>
<p><span ><strong>Vincent Deslauriers :</strong></span> « Oui, être capitaine de l&rsquo;équipe pour mes 3 dernières années a été une expérience formidable. J&rsquo;ai toujours cherché à encourager mes coéquipiers et à apporter du leadership dans le vestiaire en servant d&rsquo;exemple sur la patinoire. Je crois énormément en l&rsquo;importance de l&rsquo;esprit d&rsquo;équipe pour obtenir de bons résultats. »</p>
<p><em><strong>D’ailleurs, tu as été récompenser en janvier dernier de par tes performances chez les Aigles Bleus, te permettant de faire partie de la sélection « USports All-Stars ». Cette dernière, réunissait les meilleurs joueurs canadiens d’USports afin d’affronter par deux fois lors de matchs de préparation, Connor Bedard et Team Canada U20, quelle expérience gardes-tu ?</strong></em></p>
<p><strong><span >Vincent Deslauriers :</span></strong> « Faire partie de la sélection « USports All-Stars » et affronter des joueurs talentueux comme Connor Bedard et Adam Fantili, le premier choix et troisième choix du repêchage NHL cette année en 2023, a été une expérience incroyable. Cela m&rsquo;a permis de me mesurer à un niveau élevé de compétition, face à des futures stars du hockey mondial et d&rsquo;apprendre de nouvelles choses pour améliorer mon jeu. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/deslauriers2-300x167.jpg" alt="" width="316" height="176" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/deslauriers2-300x167.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/deslauriers2-768x427.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/deslauriers2-128x71.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/deslauriers2-32x18.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/deslauriers2-98x54.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/deslauriers2.jpg 812w" sizes="auto, (max-width: 316px) 100vw, 316px" />Comment s’est réalisée cette signature à Anglet et ce choix de rejoindre la France ?</strong></em></p>
<p><span ><strong>Vincent Deslauriers :</strong></span> « La signature à Anglet s&rsquo;est faite tout naturellement, après des discussions avec le staff sportif et une bonne compréhension de leur vision du hockey sur glace et de ce qu&rsquo;ils attendaient de moi dans leur système de jeu. Rejoindre la France est une opportunité passionnante, et je suis ravi de découvrir une nouvelle culture et de jouer dans la Synerglace Ligue Magnus. »</p>
<p><em><strong>Un certain nombre de joueurs provenant d’USports signent régulièrement en Ligue Magnus, c’était aussi un argument pour toi ?</strong></em></p>
<p><span ><strong>Vincent Deslauriers :</strong></span> « Oui, voir d&rsquo;autres joueurs provenant d&rsquo;USports réussir en Synerglace Ligue Magnus a été un facteur positif dans ma décision. Cela montre que le niveau de jeu est respecté, et cela m&rsquo;a encouragé à saisir cette belle opportunité. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/24764-300x300.jpg" alt="" width="278" height="278" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/24764-300x300.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/24764-150x150.jpg 150w, https://pro.hormadi.fr/wp-content/uploads/2023/07/24764-128x128.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/24764-32x32.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/24764-200x200.jpg 200w, https://pro.hormadi.fr/wp-content/uploads/2023/07/24764-255x255.jpg 255w, https://pro.hormadi.fr/wp-content/uploads/2023/07/24764-80x80.jpg 80w, https://pro.hormadi.fr/wp-content/uploads/2023/07/24764-98x98.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/24764-445x445.jpg 445w, https://pro.hormadi.fr/wp-content/uploads/2023/07/24764-270x270.jpg 270w, https://pro.hormadi.fr/wp-content/uploads/2023/07/24764.jpg 480w" sizes="auto, (max-width: 278px) 100vw, 278px" />Tu es donc un ailier droit, adroit dans les zones de marque, comment définirais-tu le style de joueur que tu es et quelles sont tes qualités ?</strong></em></p>
<p><span ><strong>Vincent Deslauriers :</strong></span> « En tant qu&rsquo;ailier droit et parfois au centre, je considère mon style de jeu comme offensif, mais surtout polyvalent. J&rsquo;ai la capacité de marquer et de créer des occasions de but. Je travaille également dur pour contribuer dans les tâches défensives et aider l&rsquo;équipe dans tous les aspects du jeu. »</p>
<p><strong>On connaît les Québécois pour leur personnalité atypique et leur caractère sur la glace, c’est aussi ton cas ?</strong></p>
<p><strong><span >Vincent Deslauriers :</span></strong> « Oui, le caractère québécois a certainement influencé ma personnalité sur la glace. Je suis passionné et déterminé à donner le meilleur de moi-même à chaque match. L&rsquo;engagement et l&rsquo;intensité font partie intégrante de mon jeu. »</p>
<p><em><strong>Quels sont tes objectifs la saison prochaine sous le chandail d’Anglet ?</strong></em></p>
<p><span ><strong>Vincent Deslauriers :</strong></span> « Mes objectifs pour la saison prochaine avec Anglet sont les suivants : aider l&rsquo;équipe à atteindre ses plus hauts sommets, contribuer de manière significative aux performances offensives de l&rsquo;équipe, et bien sûr, viser les séries éliminatoires et le championnat. »</p>
<figure id="attachment_16738" aria-describedby="caption-attachment-16738"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/35_vincent_deslauriers_aigles-e1508279909843-300x166.jpg" alt="" width="300" height="166" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/35_vincent_deslauriers_aigles-e1508279909843-300x166.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/35_vincent_deslauriers_aigles-e1508279909843-1024x568.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/07/35_vincent_deslauriers_aigles-e1508279909843-768x426.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/35_vincent_deslauriers_aigles-e1508279909843-1536x852.jpg 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/07/35_vincent_deslauriers_aigles-e1508279909843-128x71.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/35_vincent_deslauriers_aigles-e1508279909843-32x18.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/35_vincent_deslauriers_aigles-e1508279909843-1170x650.jpg 1170w, https://pro.hormadi.fr/wp-content/uploads/2023/07/35_vincent_deslauriers_aigles-e1508279909843-98x54.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/35_vincent_deslauriers_aigles-e1508279909843.jpg 1817w" sizes="auto, (max-width: 300px) 100vw, 300px" /><figcaption id="caption-attachment-16738" ><span ><em>Vincent Deslauriers portera le numéro 21 la saison prochaine à l&rsquo;Hormadi.</em></span></figcaption></figure>
<p><em><span ><strong>Pour finir, un petit mot pour nos partisans à l’approche du début du camp ?</strong></span></em></p>
<p><span ><strong>Vincent Deslauriers :</strong></span> « Aux fans d&rsquo;Anglet, je veux vous dire que vous allez voir sur la patinoire un joueur électrisant, énergétique qui ne lâche jamais. J&rsquo;ai hâte de vous rencontrer et de jouer devant vous. Nous allons tout donner pour vous offrir un hockey de haut niveau et rendre fier notre formidable public. Allez l&rsquo;Hormadi ! »</p>
<p><span ><em>Recueilli Matthieu Lalanne et Anaïs Domengie&#8230;</em></span></p>
<p>&nbsp;</p>
', 'Interview', '/images/news/vincent-deslauriers-aux-fans-drsquoanglet-je-veux-vous-dire-que-vous-allez-voir-.png', true, '1690466457000', '1774831537956', '1774833441756');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'samuel-rousseau-jrsquoai-de-suite-accroche-au-discours-de-pierrick-et-sa-philosophie-de-travail-son-engagement-me-plaisa', 'Samuel Rousseau : « J&rsquo;ai de suite accroché au discours de Pierrick et sa philosophie de travail, son engagement me plaisait beaucoup. »', 'En provenance des Scorpions de Mulhouse, notre nouvel attaquant français, Samuel Rousseau, débarque à la Barre avec ambitions. Il fera partie du renouveau de l&rsquo;effectif angloy et par la même occasion du renforcement de notre noyau de JFL. Entretien exclusif avec notre futur numéro 20. Tu conna', '<h4>En provenance des Scorpions de Mulhouse, notre nouvel attaquant français, Samuel Rousseau, débarque à la Barre avec ambitions. Il fera partie du renouveau de l&rsquo;effectif angloy et par la même occasion du renforcement de notre noyau de JFL. Entretien exclusif avec notre futur numéro 20.</h4>
<figure id="attachment_16713" aria-describedby="caption-attachment-16713"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Samuel-Rousseau-1.png" alt="" width="364" height="354" /><figcaption id="caption-attachment-16713" ><span ><em>Samuel Rousseau évoluait chez les Scorpions de Mulhouse lors des quatre dernières saisons. @Photo de Vincent VOEGTLIN</em></span></figcaption></figure>
<p><strong><em>Tu connaîtras la saison prochaine ton troisième club et déjà ta 7e saison en Synerglace Ligue Magnus, à 23 ans bientôt, tu as déjà une certaine expérience du haut niveau ?</em></strong></p>
<p><span ><strong>Samuel Rousseau :</strong></span> « Oui effectivement, je vais effectuer ma septième saison consécutive au plus haut niveau du hockey sur glace français, pour un joueur de 23 ans, c&rsquo;est déjà bien. J&rsquo;ai commencé très tôt à Strasbourg à l&rsquo;époque, donc j&rsquo;ai eu cette chance de baigner dans le haut niveau assez jeune. Cela m&rsquo;a permis de comprendre les choses rapidement, et l&rsquo;exigence que demande l&rsquo;élite au quotidien, ça me fait déjà une bonne expérience. »</p>
<p><em><strong>Tu es toujours resté en Alsace durant ta jeune carrière, à partir du mois d’août, tu changes de cap, c’est ce que tu recherchais, sortir de ta zone de confort ?</strong></em></p>
<p><strong><span >Samuel Rousseau :</span></strong> « C&rsquo;est vrai que c&rsquo;est l&rsquo;une des raisons pour lesquelles j&rsquo;ai voulu rejoindre Anglet. J&rsquo;ai toujours évolué en Alsace depuis tout petit, j&rsquo;avais cette envie de découvrir autre chose, une autre culture, un autre paysage, et me mettre au défi en partant loin de chez moi. C&rsquo;est exactement ce que je recherchais en venant au Pays Basque. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Rousseau-1-300x253.jpeg" alt="" width="300" height="253" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-1-300x253.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-1-768x647.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-1-128x108.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-1-32x27.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-1-98x82.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-1.jpeg 1024w" sizes="auto, (max-width: 300px) 100vw, 300px" />Pourquoi ce choix de rejoindre Anglet ?</strong></em></p>
<p><span ><strong>Samuel Rousseau :</strong></span> « Quand j&rsquo;ai pu échanger avec Pierrick (Rézard) dès la fin de saison, j&rsquo;ai de suite accrocher avec son discours et sa philosophie de travail, son engagement me plaisait beaucoup. J&rsquo;ai toujours eu des souvenirs, que c&rsquo;était difficile de venir jouer à Anglet, avec cette petite glace, cette patinoire qui a son charme. Ça n&rsquo;a pas été très compliqué pour moi de prendre cette décision. »</p>
<p><em><strong>Justement, tu connais bien la Barre, pour y être venu plusieurs fois avec Strasbourg et Mulhouse, quels souvenirs gardes-tu lors de tes visites face à l’Hormadi ?</strong></em></p>
<p><strong><span >Samuel Rousseau :</span></strong> « Comme j&rsquo;ai pu le dire juste avant, c&rsquo;est surtout cette petite glace, la seule en Synerglace Ligue Magnus, qui rend la tâche difficile lorsque l&rsquo;équipe visiteuse y débarque. Les repères ne sont plus les mêmes, c&rsquo;est tout de suite différent. Puis, également, ça était souvent pour moi le déplacement le plus long, entre l&rsquo;Alsace et le Pays Basque, c&rsquo;est usant et quand tu arrives contre une équipe qui veut te montrer qu&rsquo;elle est chez elle, ce n&rsquo;est pas simple. Et puis évidemment, la plage à côté (rires) ».</p>
<figure id="attachment_16720" aria-describedby="caption-attachment-16720"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Rousseau-4-300x200.jpeg" alt="" width="340" height="227" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-4-300x200.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-4-768x512.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-4-128x85.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-4-32x21.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-4-360x240.jpeg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-4-98x65.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-4.jpeg 1024w" sizes="auto, (max-width: 340px) 100vw, 340px" /><figcaption id="caption-attachment-16720" ><span ><em>Samuel Rousseau ici, arborant le « A » sur son chandail.</em></span></figcaption></figure>
<p><em><strong>Tu as connu une très belle saison sur plan sportif l’an passé chez les Scorpions de Mulhouse, avec un notamment un beau premier tour de playoffs face aux BDL, cela t’a permis de passer un cap en tant que joueur ?</strong></em></p>
<p><strong><span >Samuel Rousseau :</span> </strong>« Oui franchement, c&rsquo;était une très belle saison, avec à la clé, une huitième place qualificative en playoffs et un beau duel face à Grenoble. Grâce à Anglet d&rsquo;ailleurs qui avait battu Chamonix à la dernière journée, donc merci (rires). Plus sérieusement, ça était une année intéressante pour moi, c&rsquo;est là où j&rsquo;ai le plus progressé, j&rsquo;ai bien plus de temps de jeu, avec des responsabilités importantes, j&rsquo;ai acquis de l&rsquo;expérience. Tout cela m&rsquo;a fait passer un cap en tant que joueur mais aussi en tant que personne. »</p>
<p><em><strong>Comment as-tu vécu cette dernière saison personnellement, entre le sportif et l’extra-sportif  ?</strong></em></p>
<p><strong><span >Samuel Rousseau :</span></strong> « Pour être honnête, on avait un bon groupe, avec des bons gars, cela a permis en quelque sorte de faire passer la pilule. On partait du fait que l&rsquo;extra-sportif, on n&rsquo;y pouvait rien, donc on s&rsquo;est vraiment focus sur la glace, on était tous dans le même bateau et la récompense est tombée à la fin avec cette place en playoffs. Ça était aussi galère, car nous avons eu beaucoup de blessures, ce qui m&rsquo;a offert beaucoup plus de temps de jeu, j&rsquo;en ai profité et je n&rsquo;allais pas m&rsquo;en plaindre. Pour ce qu&rsquo;il s&rsquo;est passé ensuite, on le sentait arrivé, mais nous, on est resté concentré sur notre job. »</p>
<figure id="attachment_16721" aria-describedby="caption-attachment-16721"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-300x300.jpeg" alt="" width="300" height="300" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-300x300.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-150x150.jpeg 150w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-768x767.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-128x128.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-32x32.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-200x200.jpeg 200w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-255x255.jpeg 255w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-80x80.jpeg 80w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-740x740.jpeg 740w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-98x98.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-445x445.jpeg 445w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF-270x270.jpeg 270w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Rousseau-EDF.jpeg 828w" sizes="auto, (max-width: 300px) 100vw, 300px" /><figcaption id="caption-attachment-16721" ><em><span >Samuel Rousseau compte 41 sélections en Équipe de France junior.</span></em></figcaption></figure>
<p><strong>Tu as également 41 sélections en Équipe de France U20 et U18, te permettant de découvrir des tournois internationaux, as-tu dans un coin de ta tête de porter le chandail des Séniors un jour ?</strong></p>
<p><span ><strong>Samuel Rousseau :</strong></span> « Évidemment, c&rsquo;est dans un coin de ma tête, mais je suis conscient, je sais ce que ça prend, je sais que pour l&rsquo;instant, j&rsquo;ai encore du chemin à parcourir. Et ça passe par devenir plus régulier dans mes productions offensives, je ne veux pas brûler les étapes, chaque chose en son temps et dans le bon ordre. »</p>
<p><em><strong>Pour ceux qui te connaissent moins, tu es un joueur polyvalent dans les deux sens de la glace, capable d’évoluer à l’aile comme au centre, comment décrirais-tu tes qualités et le style de joueur que tu es ?</strong></em></p>
<p><span ><strong>Samuel Rousseau :</strong></span> « Oui je me décrirais comme un joueur polyvalent, je suis capable d&rsquo;être bon aussi bien offensivement que défensivement. Lorsque j&rsquo;ai fait mes débuts avec Strasbourg en Synerglace Ligue Magnus ou même à Mulhouse, je devais assuré défensivement dans un premier temps pour ensuite jouer un autre rôle. Maintenant, avec la saison qui vient de s&rsquo;écouler, j&rsquo;ai passé un cap offensivement, en marquant plus des points. J&rsquo;aime travailler dans les deux sens de la glace, et également, je peux jouer au centre comme à l&rsquo;aile. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/046-ROUSSEAUsamuel-MULHOUSE-20211126.jpg-1-300x200.webp" alt="" width="268" height="178" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/046-ROUSSEAUsamuel-MULHOUSE-20211126.jpg-1-300x200.webp 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/046-ROUSSEAUsamuel-MULHOUSE-20211126.jpg-1-128x86.webp 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/046-ROUSSEAUsamuel-MULHOUSE-20211126.jpg-1-32x21.webp 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/046-ROUSSEAUsamuel-MULHOUSE-20211126.jpg-1-360x240.webp 360w, https://pro.hormadi.fr/wp-content/uploads/2023/07/046-ROUSSEAUsamuel-MULHOUSE-20211126.jpg-1-98x65.webp 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/046-ROUSSEAUsamuel-MULHOUSE-20211126.jpg-1.webp 702w" sizes="auto, (max-width: 268px) 100vw, 268px" />En termes de production justement, tu progresses significativement, ce sera aussi l’un de tes objectifs avec Anglet la saison prochaine ?</strong></em></p>
<p><strong><span >Samuel Rousseau :</span></strong> « Oui totalement, il faut que j&rsquo;arrive à être encore plus décisif, je pense pouvoir faire bien mieux lorsque je me présente devant la cage, dans les zones de marque, je dois travailler sur ça encore. Ce sera l&rsquo;un de mes objectifs avec Anglet, même si pour moi, la performance collective prime sur le reste et l&rsquo;individualisme. C&rsquo;est un collectif qui te fait gagner des matchs. »</p>
<p><em><strong>Tu parles de performance collective, quelles sont donc tes ambitions collectives la saison prochaine ?</strong></em></p>
<p><span ><strong>Samuel Rousseau :</strong></span> « Je crois que l&rsquo;Hormadi n&rsquo;a toujours pas eu l&rsquo;occasion de jouer les playoffs, donc ce sera forcément l&rsquo;ambition de tout le monde, c&rsquo;est quelque chose d&rsquo;assez fort en émotions quand tu les vis. Donc voilà, dans un premier temps, bien respecté le processus, et je l&rsquo;espère, être dans le top 8. Et si je peux rajouter, un beau parcours en Coupe de France, sur des matchs à élimination directe, ça peut aller vite, surtout si le tirage au sort est favorable avec des réceptions à la Barre, où il sera encore plus dur de manœuvrer pour l&rsquo;adversaire. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-24-a-14.51.00-300x215.png" alt="" width="240" height="172" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-24-a-14.51.00-300x215.png 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-24-a-14.51.00-1024x735.png 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-24-a-14.51.00-768x551.png 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-24-a-14.51.00-1536x1103.png 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-24-a-14.51.00-128x92.png 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-24-a-14.51.00-32x23.png 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-24-a-14.51.00-255x183.png 255w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-24-a-14.51.00-350x250.png 350w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-24-a-14.51.00-98x70.png 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-24-a-14.51.00.png 1872w" sizes="auto, (max-width: 240px) 100vw, 240px" />Connais-tu certains joueurs du futur effectif ?</strong></em></p>
<p><span ><strong>Samuel Rousseau :</strong></span> « Je connais très bien Victor Ranger, avec qui j&rsquo;ai évolué chez les jeunes en Équipe de France, c&rsquo;est un bon ami à moi. Pour les autres, non pas spécialement, mais comme le monde du hockey en France est petit, je connais de nom et de tête quasiment tous les joueurs français de l&rsquo;effectif, et j&rsquo;ai vraiment hâte de découvrir chacun d&rsquo;eux à la rentrée. »</p>
<p><em><strong>Plutôt charcuterie basque ou flammekueche alsacienne ?</strong></em></p>
<p><span ><strong>Samuel Rousseau :</strong> </span>« Pour l&rsquo;instant flammekueche alsacienne, je ne peux pas renier mes racines (rires). Mais j&rsquo;ai eu la chance de rapidement visiter le Pays Basque cet été, le mois dernier, sans avoir trop le temps de goûter la charcuterie, peut-être que je changerais d&rsquo;opinion sur le sujet prochainement (rires). »</p>
<figure id="attachment_16712" aria-describedby="caption-attachment-16712"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/rousseau-276x300.jpg" alt="" width="276" height="300" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/rousseau-276x300.jpg 276w, https://pro.hormadi.fr/wp-content/uploads/2023/07/rousseau-118x128.jpg 118w, https://pro.hormadi.fr/wp-content/uploads/2023/07/rousseau-29x32.jpg 29w, https://pro.hormadi.fr/wp-content/uploads/2023/07/rousseau-90x98.jpg 90w, https://pro.hormadi.fr/wp-content/uploads/2023/07/rousseau.jpg 500w" sizes="auto, (max-width: 276px) 100vw, 276px" /><figcaption id="caption-attachment-16712" ><span ><em>Samuel Rousseau portera le numéro 20 à l&rsquo;Hormadi la saison prochaine.</em></span></figcaption></figure>
<p><em><strong>Pour conclure, as-tu quelques mots pour les supporteurs avant la reprise du camp ?</strong></em></p>
<p><span ><strong>Samuel Rousseau :</strong></span> « L&rsquo;intersaison estivale est très longue, je pense qu&rsquo;on a tous très hâte de reprendre, moi le premier. Je me languis de faire connaissance et vous rencontrer dès le premier match amical à la Barre face à Bordeaux, et même avant durant le camp de préparation. D&rsquo;ici là, portez-vous bien et à bientôt ! »</p>
<p><span ><em>Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</em></span></p>
', 'Interview', '/images/news/samuel-rousseau-jrsquoai-de-suite-accroche-au-discours-de-pierrick-et-sa-philoso.png', true, '1690297504000', '1774831579443', '1774833441757');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'cole-thiessen-mes-principales-qualites-sont-mes-capacites-de-patinage-mon-qi-hockey-et-ma-patience-avec-la-rondelle', 'Cole Thiessen : « Mes principales qualités sont mes capacités de patinage, mon QI hockey et ma patience avec la rondelle. »', 'Il fera partie du tout nouveau visage de l&rsquo;arrière-garde angloye la saison prochaine, le défenseur offensif droitier, Cole Thiessen, débarque à l&rsquo;Hormadi en provenance du Canada, pour sa toute première expérience en Europe. Entretien exclusif avec notre futur numéro 22. Ce sera ta toute ', '<h4>Il fera partie du tout nouveau visage de l&rsquo;arrière-garde angloye la saison prochaine, le défenseur offensif droitier, Cole Thiessen, débarque à l&rsquo;Hormadi en provenance du Canada, pour sa toute première expérience en Europe. Entretien exclusif avec notre futur numéro 22.</h4>
<figure id="attachment_16537" aria-describedby="caption-attachment-16537"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-214x300.jpg" alt="" width="239" height="335" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-214x300.jpg 214w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-731x1024.jpg 731w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-768x1076.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-1097x1536.jpg 1097w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-91x128.jpg 91w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-23x32.jpg 23w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-70x98.jpg 70w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen.jpg 1428w" sizes="auto, (max-width: 239px) 100vw, 239px" /><figcaption id="caption-attachment-16537" ><span ><em>Cole Thiessen sous les couleurs des Badgers (USports) la saison dernière.</em></span></figcaption></figure>
<p><em><strong>Ce sera ta toute première expérience la saison prochaine en dehors du pays et du continent nord-américain, quel sentiment demeures chez toi, de l’excitation, un peu d’appréhension aussi ?</strong></em></p>
<p><span ><strong>Cole Thiessen :</strong></span> « Je suis vraiment très enthousiaste et impatient d&rsquo;arriver à Anglet. J&rsquo;ai hâte de rencontrer tout le monde au sein de l&rsquo;organisation et de commencer notre voyage vers une saison réussie. Évidemment, commencer avec une nouvelle équipe et quitter l&rsquo;Amérique du Nord s&rsquo;accompagne toujours d&rsquo;un peu d&rsquo;appréhension, mais je pense qu&rsquo;il s&rsquo;agit plutôt de nerfs d&rsquo;excitation et d&rsquo;anticipation en ce qui me concerne. »</p>
<p><em><strong>Tu viens donc de terminer ton cursus universitaire à Brock, après 4 saisons passées en USports, on a pu constater notamment que cette dernière saison a été très productive pour toi en plus d’être assistant capitaine, comment juges-tu ta progression ?</strong></em></p>
<p><span ><strong>Cole Thiessen :</strong></span> « J&rsquo;ai l&rsquo;impression que mon jeu a progressé de manière significative au cours des dernières années au niveau USports. En tant que joueur, je crois que je me suis développé plus tard dans ma carrière que d&rsquo;autres, car je pense certainement que cette dernière année à l&rsquo;Université de Brock a été ma meilleure année de hockey à ce jour. Il ne fait aucun doute qu&rsquo;il y a encore beaucoup de place pour la croissance et l&rsquo;amélioration, ce que j&rsquo;ai hâte de faire au cours de la prochaine saison avec l&rsquo;Hormadi. »</p>
<figure id="attachment_16536" aria-describedby="caption-attachment-16536"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-2-300x169.jpg" alt="" width="361" height="203" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-2-300x169.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-2-1024x575.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-2-768x432.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-2-1536x863.jpg 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-2-128x72.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-2-32x18.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-2-98x55.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/ColeThiessen-2.jpg 2000w" sizes="auto, (max-width: 361px) 100vw, 361px" /><figcaption id="caption-attachment-16536" ><span ><em>Cole Thiessen était assistant capitaine de son Université de Brock.</em></span></figcaption></figure>
<p><em><strong>Bien que ce soit une ligue universitaire, l’USports est un championnat avec un très bon niveau de hockey, qui permet aux jeunes joueurs canadiens de s’offrir des opportunités à l’étranger, c’est ton cas ?</strong></em></p>
<p><span ><strong>Cole Thiessen :</strong></span> « À mon avis, l&rsquo;USports est une ligue très sous-estimée. Année après année, la ligue continue de se développer et de s&rsquo;améliorer significativement, formant des joueurs d&rsquo;élite qui peuvent décrocher de gros contrats dans les ligues professionnelles, tout en bénéficiant d&rsquo;une éducation. Les possibilités offertes par le sport américain sont infinies, et c&rsquo;est bien ce qui s&rsquo;est passé dans mon cas. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.05.40-200x300.jpeg" alt="" width="167" height="251" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.05.40-200x300.jpeg 200w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.05.40-682x1024.jpeg 682w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.05.40-768x1153.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.05.40-1023x1536.jpeg 1023w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.05.40-85x128.jpeg 85w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.05.40-21x32.jpeg 21w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.05.40-65x98.jpeg 65w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.05.40.jpeg 1066w" sizes="auto, (max-width: 167px) 100vw, 167px" />Comment s’est passée ta signature à Anglet, et pourquoi ce choix de venir en France ?</strong></em></p>
<p><span ><strong>Cole Thiessen :</strong></span> « Après ma saison à l&rsquo;Université de Brock, j&rsquo;ai commencé à chercher des équipes à l&rsquo;étranger et j&rsquo;ai eu la chance d&rsquo;entrer en contact avec Anglet rapidement. Après plusieurs discussions avec l&rsquo;organisation, j&rsquo;ai senti que c&rsquo;était le meilleur choix pour moi en tant que joueur et en tant que personne. Pour ce qui est de la raison pour laquelle j&rsquo;ai choisi la France, j&rsquo;ai entendu beaucoup de bonnes choses sur la ligue et le pays, de la part de mes anciens coéquipiers et amis qui ont pu déjà y évoluer. Ensuite, j&rsquo;ai fait mes propres recherches et j&rsquo;ai réalisé à quel point la Synerglace Ligue Magnus était forte et performante. Finalement, la décision a été facile à prendre une fois que j&rsquo;ai eu l&rsquo;opportunité de jouer pour Anglet et en Synerglace Ligue Magnus. »</p>
<p><em><strong>On peut se douter que la décision de partir n’est jamais simple lorsque tu arrives au bout de ton cursus universitaire, avais-tu vraiment cette volonté de partir à l’étranger après Brock ou avais-tu d’autres idées en tête ?</strong></em></p>
<p><span ><strong>Cole Thiessen :</strong></span> « Comme tu l&rsquo;as dit, il n&rsquo;est jamais facile d&rsquo;arriver à la fin de son parcours universitaire, qui a été pour moi les quatre meilleures années de ma vie. Cela dit, je pense que partir à l&rsquo;étranger a toujours été mon plan après avoir terminé ma carrière universitaire. Le fait d&rsquo;avoir eu l&rsquo;occasion de voir d&rsquo;anciens coéquipiers de l&rsquo;Université Brock aller jouer à l&rsquo;étranger m&rsquo;a certainement ouvert les yeux sur cette possibilité, et depuis, j&rsquo;ai pour objectif de jouer au hockey à l&rsquo;étranger. »</p>
<figure id="attachment_16541" aria-describedby="caption-attachment-16541"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-2-300x200.jpeg" alt="" width="353" height="235" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-2-300x200.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-2-768x512.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-2-128x85.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-2-32x21.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-2-360x240.jpeg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-2-98x65.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-2.jpeg 1024w" sizes="auto, (max-width: 353px) 100vw, 353px" /><figcaption id="caption-attachment-16541" ><span ><em>Cole Thiessen a inscrit 22 points en 31 matchs en USports l&rsquo;an passé.</em></span></figcaption></figure>
<p><em><strong>Connaissais-tu déjà un peu la ligue française ?</strong></em></p>
<p><span ><strong>Cole Thiessen :</strong></span> « Je connaissais un peu le championnat grâce à l&rsquo;un de mes anciens coéquipiers (Skylar Pacheco ex-Amiens) qui a joué deux ans en Ligue Magnus. Après avoir discuté avec lui, il n&rsquo;avait que de bonnes choses à dire sur le championnat et le pays dans son ensemble. Cependant, à part cela, je ne savais pas grand-chose d&rsquo;autre sur le championnat. J&rsquo;ai fait ma propre analyse du championnat après ma saison USports et j&rsquo;ai réalisé à quel point il s&rsquo;agissait d&rsquo;une bonne ligue. »</p>
<p><em><strong>Tu es donc un défenseur droitier, assez mobile et offensif, comment toi définirais-tu le style de défenseur que tu es aujourd’hui et quelles sont tes qualités premières ?</strong></em></p>
<p><span ><strong>Cole Thiessen :</strong> </span>« Comme tu l&rsquo;as mentionné, je me décrirais comme un défenseur offensif. Je suis un joueur qui utilise mon habileté à patiner et ma tromperie pour sortir efficacement de notre zone et créer des occasions de marquer. Mon QI hockey me permet d&rsquo;anticiper efficacement les jeux, tout en me permettant de bien me positionner dans les trois zones de la glace. Enfin, grâce à mon jeu offensif, je suis un joueur qui se sent à l&rsquo;aise en powerplay (supériorité numérique). Je dirais que mes principales qualités sont mes capacités de patinage, mon QI hockey et ma patience avec la rondelle. Comme je suis un petit défenseur, je suis également fier de mon éthique de travail et de ma compétitivité. »</p>
<figure id="attachment_16539" aria-describedby="caption-attachment-16539"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.06.41-300x200.jpeg" alt="" width="329" height="219" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.06.41-300x200.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.06.41-1024x682.jpeg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.06.41-768x512.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.06.41-1536x1023.jpeg 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.06.41-128x85.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.06.41-32x21.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.06.41-360x240.jpeg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.06.41-98x65.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.06.41.jpeg 1600w" sizes="auto, (max-width: 329px) 100vw, 329px" /><figcaption id="caption-attachment-16539" ><span ><em>Cole Thiessen est un défenseur offensif et très mobile dû à son petit gabarit.</em></span></figcaption></figure>
<p><strong><em>On a pu voir une belle production en termes de points la saison dernière en USports, tu es un défenseur qui sait aussi mettre des points et inscrire son nom au tableau d’affichage ?</em></strong></p>
<p><span ><strong>Cole Thiessen :</strong></span> « En tant que défenseur offensif, je suis fier d&rsquo;être un joueur qui peut fournir à mon équipe des occasions de marquer tout au long du match. Cela me donne l&rsquo;occasion de marquer des points. Cependant, je pense qu&rsquo;il est important pour moi de ne pas trop me concentrer sur l&rsquo;aspect production, mais plutôt sur mon jeu global et sur la façon dont je vais donner à mon équipe la meilleure chance de gagner chaque match. »</p>
<blockquote><p>&nbsp;</p>
<p><span ><em>« Il est important pour moi de me concentrer sur la façon dont je vais donner à mon équipe la meilleure chance de gagner chaque match</em></span><span ><em>« </em></span></p></blockquote>
<p><em><strong>Tu n’es pas le seul joueur à avoir signé à Anglet en provenance d’USports, Keith Getson, Sam Dunn ou encore Vincent Deslauriers seront à tes côtés, les connais-tu personnellement ?</strong></em></p>
<p><span ><strong>Cole Thiessen :</strong></span> « Je ne les connais pas personnellement, mais j&rsquo;ai grandi en jouant contre Sam (Dunn) pendant la majeure partie de ma vie. J&rsquo;ai vraiment hâte d&rsquo;apprendre à les connaître tous les trois ainsi que le reste de l&rsquo;équipe et d&rsquo;avoir l&rsquo;occasion de construire de solides amitiés et des souvenirs tout au long de l&rsquo;année. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-1-300x200.jpeg" alt="" width="362" height="241" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-1-300x200.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-1-768x512.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-1-128x85.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-1-32x21.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-1-360x240.jpeg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-1-98x65.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-1.jpeg 1024w" sizes="auto, (max-width: 362px) 100vw, 362px" />Est-ce aussi rassurant, de pouvoir se dire que d’autres joueurs d’une même ligne te rejoignent afin de faciliter l’adaptation ?</strong></em></p>
<p><strong><span >Cole Thiessen :</span></strong>  » Je pense que cela sera certainement très utile, car cela permet de se familiariser avec les débuts et de s&rsquo;adapter à un nouvel environnement. De plus, il est toujours agréable de découvrir un nouvel endroit avec des personnes de la même lignée. »</p>
<p><em><strong>Quelle est ta personnalité en dehors de la glace ?</strong></em></p>
<p><strong><span >Cole Thiessen :</span> </strong>« J&rsquo;essaie d&rsquo;être quelqu&rsquo;un d&rsquo;agréable à côtoyer. Je suis une personne heureuse, qui a de la chance, et j&rsquo;essaie de refléter cela dans tous les aspects de ma vie. J&rsquo;aime passer du temps avec ma famille et mes amis, car je chéris les liens que nous partageons et les souvenirs que nous créons ensemble. J&rsquo;ai tendance à suivre le cours des choses, à accepter les rebondissements de la vie avec positivité et ouverture d&rsquo;esprit. En ce qui concerne les activités hors glace, j&rsquo;aime jouer au golf, voyager et créer de nouvelles expériences et de nouveaux souvenirs. »</p>
<blockquote><p><span ><em>« Je veux avant tout, être le meilleur coéquipier possible »</em></span></p></blockquote>
<p><em><strong> Quels sont tes objectifs pour la saison prochaine ?</strong></em></p>
<p><span ><strong>Cole Thiessen :</strong></span> « En ce qui me concerne, je veux avant tout, être le meilleur coéquipier possible. Qu&rsquo;il s&rsquo;agisse de pousser les autres joueurs à donner le meilleur d&rsquo;eux-mêmes ou d&rsquo;avoir une attitude positive et contagieuse, je veux m&rsquo;assurer d&rsquo;être le meilleur coéquipier possible jour après jour. En termes de performances sur la glace, je veux donner à mon équipe les meilleures chances de gagner chaque match. Je vise à produire de l&rsquo;offensive, tout en étant un défenseur fiable dans toutes les situations. »</p>
<figure id="attachment_16542" aria-describedby="caption-attachment-16542"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-300x200.jpeg" alt="" width="421" height="280" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-300x200.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-768x512.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-128x85.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-32x21.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-360x240.jpeg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39-98x65.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/WhatsApp-Image-2023-06-14-at-13.11.39.jpeg 1024w" sizes="auto, (max-width: 421px) 100vw, 421px" /><figcaption id="caption-attachment-16542" ><em><span >Cole Thiessen portera le numéro 22 à l&rsquo;Hormadi.</span></em></figcaption></figure>
<p><em><strong>Pour terminer, as-tu quelques mots pour les fans alors que la reprise se rapproche ?</strong></em></p>
<p><span ><strong>Cole Thiessen :</strong> </span>« Je voulais prendre un moment pour exprimer personnellement mon enthousiasme pour la saison à venir. J&rsquo;ai vraiment hâte de jouer devant des supporters aussi passionnés et dévoués. Votre soutien et votre dévouement inébranlables sont ce qui nous motive, nous les joueurs, et nous permettent de prendre plaisir à venir à la patinoire tous les jours. Mais il ne s&rsquo;agit pas seulement du jeu en lui-même ; je suis vraiment enthousiaste à l&rsquo;idée de rencontrer chacun d&rsquo;entre vous tout au long de la saison. J&rsquo;espère que la saison à venir sera couronnée de succès ! Rendez-vous en août ! »</p>
<p><span ><em>Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</em></span></p>
', 'Interview', '/images/news/cole-thiessen-mes-principales-qualites-sont-mes-capacites-de-patinage-mon-qi-hoc.png', true, '1689950404000', '1774831601646', '1774833441757');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'hockey-concert', 'Hockey Concert', '[vc_row][vc_column][vc_column_text] HOCKEY + CONCERT LE 1ER SEPTEMBRE 2023 [/vc_column_text][vc_video link= »https://youtu.be/Dl8gSQLjLqA » align= »center »][vc_row_inner][vc_column_inner width= »1/2&Prime;][vc_separator border_width= »2&Prime;][vc_column_text] ANGLET VS BORDEAUX Match de pré-saison', '<div ><p>[vc_row][vc_column][vc_column_text]</p>
<h1 ><strong>HOCKEY + CONCERT </strong></h1>
<h3 >LE 1ER SEPTEMBRE 2023</h3>
<p>[/vc_column_text][vc_video link= »https://youtu.be/Dl8gSQLjLqA » align= »center »][vc_row_inner][vc_column_inner width= »1/2&Prime;][vc_separator border_width= »2&Prime;][vc_column_text]</p>
<h3 >ANGLET VS BORDEAUX<br />
<em>Match de pré-saison</em></h3>
<p>[/vc_column_text][vc_hoverbox image= »16639&Prime; primary_title= » » hover_title= »Match Anglet vs Bordeaux » shape= »square » hover_background_color= »custom » hover_custom_background= »#a5cfca »]Un derby de plus à la barre mais celui là est amical.<br />
les hommes de <strong>Pierrick REZARD</strong> peaufineront les détails pour être prêts pour le début de saison le 9 septembre à la Barre contre Briançon.</p>
<p>Ce match de pré-saison est l&rsquo;avant dernier dune série de 5 matchs de préparation.<br />
<strong>Coup d&rsquo;envoi : 19h00</strong>[/vc_hoverbox][/vc_column_inner][vc_column_inner width= »1/2&Prime;][vc_separator border_width= »2&Prime;][vc_column_text]</p>
<h3 >CONCERT ERICK BAERT<em><br />
The Voice performer</em></h3>
<p>[/vc_column_text][vc_hoverbox image= »16643&Prime; primary_title= » » hover_title= »Concert Erick BAERT » shape= »square » hover_background_color= »custom » hover_custom_background= »#a5cfca »]Un imitateur différent&#8230;<br />
Dans le milieu de l’imitation se pose toujours le dilemme entre la caricature amusante ou la performance vocale époustouflante.<br />
À travers son spectacle, <strong>Erick</strong> a choisi son camp en vous promettant de vivre 100 concerts à lui tout seul.</p>
<p><strong>Un feu d&rsquo;artifice vocal qui explose à la vitesse du son.</strong>[/vc_hoverbox][/vc_column_inner][/vc_row_inner][/vc_column][/vc_row][vc_row][vc_column][vc_empty_space height= »70px »][stm_tickets_for_next_match tfnm_event= »16634&Prime; tfnm_btn_title= »Billetterie Tarif unique 25€ » tfnm_title= »Match + Concert Erik BAERT » tfnm_btn_link= »https://www.hormadi.fr/billetterie-en-ligne/ »][vc_empty_space][/vc_column][/vc_row]</p>
</div>', 'Club', '/images/news/hockey-concert.jpg', true, '1689678371000', '1774831603485', '1774831603485');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'guillaume-duquenne-jrsquoai-appris-la-loi-de-la-concurrence-car-rien-nest-acquis-et-personne-na-de-place-definitive', 'Guillaume Duquenne : « J&rsquo;ai appris la loi de la concurrence, car rien n’est acquis et personne n’a de place définitive »', 'Visage bien connu de la Division 1 pour y avoir performé au cours des cinq dernières saisons, le portier français de 30 ans, Guillaume Duquenne, formera la paire avec Dylan St. Cyr dans les filets basques la saison prochaine. Entretien exclusif avec notre numéro 59. Sept ans après tes dernières appa', '<h4>Visage bien connu de la Division 1 pour y avoir performé au cours des cinq dernières saisons, le portier français de 30 ans, Guillaume Duquenne, formera la paire avec Dylan St. Cyr dans les filets basques la saison prochaine. Entretien exclusif avec notre numéro 59.</h4>
<figure id="attachment_16551" aria-describedby="caption-attachment-16551"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/305118668_10160021460884399_3091010995041836540_n-300x183.jpg" alt="" width="468" height="286" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/305118668_10160021460884399_3091010995041836540_n-300x183.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/305118668_10160021460884399_3091010995041836540_n-1024x626.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/07/305118668_10160021460884399_3091010995041836540_n-768x469.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/305118668_10160021460884399_3091010995041836540_n-128x78.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/305118668_10160021460884399_3091010995041836540_n-32x20.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/305118668_10160021460884399_3091010995041836540_n-570x350.jpg 570w, https://pro.hormadi.fr/wp-content/uploads/2023/07/305118668_10160021460884399_3091010995041836540_n-98x60.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/305118668_10160021460884399_3091010995041836540_n-720x440.jpg 720w, https://pro.hormadi.fr/wp-content/uploads/2023/07/305118668_10160021460884399_3091010995041836540_n.jpg 1440w" sizes="auto, (max-width: 468px) 100vw, 468px" /><figcaption id="caption-attachment-16551" ><span ><em>Guillaume Duquenne évoluait à Neuilly-sur-Marne (D1) la saison dernière.</em></span></figcaption></figure>
<p><em><strong>Sept ans après tes dernières apparitions en Synerglace Ligue Magnus sous les couleurs d’Amiens à l’époque, tu fais ton retour dans l’élite du hockey sur glace français, c’est une satisfaction pour toi ?</strong></em></p>
<p><strong><span >Guillaume Duquenne :</span></strong> « Oui c’est une réelle satisfaction pour moi de remonter dans l’élite du hockey français.<br />
C’était devenu un objectif depuis quelques saisons maintenant, je suis impatient de découvrir le rythme de la Synerglace Ligue Magnus à 44 matchs. »</p>
<p><em><strong>Pourquoi ce choix de venir à Anglet, qu’est-ce qui t’as convaincu de rejoindre la Barre ?</strong></em></p>
<p><strong><span >Guillaume Duquenne :</span></strong> « Le McDo à côté (rires). Non plus sérieusement, j’ai été coaché pendant 2 saisons à Dunkerque par Pierrick (Rézard), je sais comment il travaille au quotidien et ce que cela peut m’apporter personnellement. Le fonctionnement du club, du staff et les objectifs présentés par Pierrick m’ont également convaincu de rejoindre l&rsquo;Hormadi. »</p>
<p><em><strong>Tu es d’ailleurs venu faire un petit tour au Pays Basque la semaine dernière, comment cela s’est passé ?</strong></em></p>
<p><strong><span >Guillaume Duquenne :</span></strong> « Cela s’est très bien passé, j’ai reçu un très bel accueil par l’ensemble du staff sportif et administratif, j&rsquo;en suis très reconnaissant, j&rsquo;ai été ravi car j’ai pu également travailler avec Florent Neyens (préparateur physique) ce qui nous a permis aussi de se connaître et de discuter de la saison à venir. »</p>
<figure id="attachment_16553" aria-describedby="caption-attachment-16553"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-300x300.jpg" alt="" width="326" height="326" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-300x300.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-150x150.jpg 150w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-768x767.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-128x128.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-32x32.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-200x200.jpg 200w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-255x255.jpg 255w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-80x80.jpg 80w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-740x740.jpg 740w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-98x98.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-445x445.jpg 445w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n-270x270.jpg 270w, https://pro.hormadi.fr/wp-content/uploads/2023/07/319183450_10160280869319399_1688110582047770678_n.jpg 961w" sizes="auto, (max-width: 326px) 100vw, 326px" /><figcaption id="caption-attachment-16553" ><span ><em>Photo de @Denis Broyer.</em></span></figcaption></figure>
<p><em><strong>Ce sera assurément un changement de statut également pour toi, comment abordes-tu cela ?</strong></em></p>
<p><strong><span >Guillaume Duquenne :</span> </strong>« Je savais pertinemment que pour monter de la Division 1 à la Synerglace Ligue Magnus, il fallait passer par cette étape.<br />
Maintenant, continuer de garder l’état d’esprit d’un numéro 1 et de travailler chaque jour, pour mon développement et pour le bien-être du groupe. »</p>
<p><em><strong>Tu sors de 5 saisons pleines en D1 sous les couleurs de Dunkerque notamment et Neuilly-sur-Marne la saison dernière, avec des performances te permettant de faire partie des meilleurs portiers de D1, comment juges-tu ta progression au fil des saisons ?</strong></em></p>
<p><strong><span >Guillaume Duquenne :</span></strong> « J&rsquo;ai eu l’opportunité de travailler avec des personnes et des clubs qui m’ont fait confiance, et grâce à qui j’ai pu m’épanouir et m’affirmer au fil des saisons. Je fais en sorte de garder une bonne attitude sur et en dehors de la glace mais également une bonne éthique de travail afin de continuer cette évolution permanente. »</p>
<figure id="attachment_16548" aria-describedby="caption-attachment-16548"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/740-200x300.jpg" alt="" width="218" height="327" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/740-200x300.jpg 200w, https://pro.hormadi.fr/wp-content/uploads/2023/07/740-683x1024.jpg 683w, https://pro.hormadi.fr/wp-content/uploads/2023/07/740-768x1152.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/740-1024x1536.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/07/740-85x128.jpg 85w, https://pro.hormadi.fr/wp-content/uploads/2023/07/740-21x32.jpg 21w, https://pro.hormadi.fr/wp-content/uploads/2023/07/740-65x98.jpg 65w, https://pro.hormadi.fr/wp-content/uploads/2023/07/740.jpg 1200w" sizes="auto, (max-width: 218px) 100vw, 218px" /><figcaption id="caption-attachment-16548" ><span ><em>Guillaume Duquenne, plus jeune, sous les couleurs des Dragons de Rouen.</em></span></figcaption></figure>
<p><em><strong>Tu es aussi passé par la bonne école de Rouen ou encore Gap lorsque tu étais jeune, des grosses écuries qui ont la culture de la gagne, c’est ce qu’ils t’avaient imprégné à l’époque ?</strong></em></p>
<p><strong><span >Guillaume Duquenne :</span> </strong>« Ce sont des formations qui m’ont appris ce qu’est le haut niveau, car chaque saison dans les différentes catégories vous visez le titre de champion de France. J&rsquo;ai également appris la loi de la concurrence, car rien n’est acquis et personne n’a de place définitive. Et enfin, l’éthique de travail à avoir pour être le plus professionnel possible. »</p>
<p><em><strong>Ton binôme dans les cages se nomme Dylan St. Cyr pour la saison prochaine, quel sentiment demeure chez toi de pouvoir travailler avec lui ?</strong></em></p>
<p><strong><span >Guillaume Duquenne :</span></strong> « Je suis impatient de faire sa connaissance. J’ai vu qu’il faisait l’effort de parler français et travailler avec lui ça ne peut être qu&rsquo;une expérience enrichissante au vu de son parcours ainsi que son histoire familiale. »</p>
<p><em><strong>Vous avez justement deux styles totalement différents, toi, tu es plutôt grand et imposant dans tes filets, quelles sont tes qualités et quel style de gardien es-tu ?</strong></em></p>
<p><strong><span >Guillaume Duquenne :</span> </strong>« Oui tout à fait, comme tu le cites, nous avons deux styles opposés lui et moi. Je suis assez grand et imposant, je prends de la place dans ma cage, j’aime beaucoup travailler la coordination des yeux et répéter des exercices techniques pour me sentir en confiance. »</p>
<figure id="attachment_16555" aria-describedby="caption-attachment-16555"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-300x300.jpg" alt="" width="320" height="320" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-300x300.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-150x150.jpg 150w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-768x769.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-128x128.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-32x32.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-200x200.jpg 200w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-255x255.jpg 255w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-80x80.jpg 80w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-740x740.jpg 740w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-98x98.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-445x445.jpg 445w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n-270x270.jpg 270w, https://pro.hormadi.fr/wp-content/uploads/2023/07/333506365_1520201758502629_6381871353625256496_n.jpg 908w" sizes="auto, (max-width: 320px) 100vw, 320px" /><figcaption id="caption-attachment-16555" ><em><span >Guillaume Duquenne portera le numéro 59 la saison prochaine. Photo de @Denis Broyer</span></em></figcaption></figure>
<blockquote><p><em><span >« Je vais partir pour 15 jours de stage spécifique gardien »</span></em></p></blockquote>
<p><em><strong>On va parler objectifs, quels sont les tiens avec l’Hormadi ?</strong></em></p>
<p><strong><span >Guillaume Duquenne :</span></strong> « Tout d’abord, d’arriver prêt. Pour cela, j’ai effectué la préparation du club qui était innovante et correspondait à mes besoins. La semaine prochaine, je vais partir pour 15 jours de stage spécifique gardien.<br />
Les objectifs en saison, seront de continuer de travailler, de trouver le juste milieu entre se tenir prêt et compenser les matchs que je ne jouerai pas. Ensuite, d’être performant lorsque je serai dans la cage afin de faire ma place et bien évidemment d’aider le groupe à aller le plus loin possible. »</p>
<p><em><strong>L’effectif est quasiment au complet, quel regard portes-tu sur ce dernier aujourd’hui ?</strong></em></p>
<p><span ><strong>Guillaume Duquenne :</strong></span> « Je trouve que l’équipe est très homogène, il y a déjà un noyau fort dans ce groupe qui nous aidera, j’en suis sûr, à vite nous adapter et nous sentir à l’aise. Ce qui nous permettra d’avancer en équipe tout au long de cette saison. »</p>
<figure id="attachment_16550" aria-describedby="caption-attachment-16550"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/c39e90e7576eb53559e8f0186a76c05d-cropped-300x190.jpeg" alt="" width="362" height="229" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/c39e90e7576eb53559e8f0186a76c05d-cropped-300x190.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/c39e90e7576eb53559e8f0186a76c05d-cropped-128x81.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/c39e90e7576eb53559e8f0186a76c05d-cropped-32x20.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/c39e90e7576eb53559e8f0186a76c05d-cropped-98x62.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/c39e90e7576eb53559e8f0186a76c05d-cropped-350x220.jpeg 350w, https://pro.hormadi.fr/wp-content/uploads/2023/07/c39e90e7576eb53559e8f0186a76c05d-cropped-110x70.jpeg 110w, https://pro.hormadi.fr/wp-content/uploads/2023/07/c39e90e7576eb53559e8f0186a76c05d-cropped.jpeg 500w" sizes="auto, (max-width: 362px) 100vw, 362px" /><figcaption id="caption-attachment-16550" ><span ><em>Guillaume Duquenne sous les couleurs des Corsaires de Dunkerque.</em></span></figcaption></figure>
<p><em><strong>Enfin, as-tu quelques mots pour les fans avant la reprise ?</strong></em></p>
<p><strong><span >Guillaume Duquenne :</span> </strong>« Je suis très impatient de les rencontrer, d’apprendre les coutumes locales et surtout de se sentir soutenu et encouragé à chaque match à la Barre comme à l&rsquo;extérieur, afin de vibrer tous ensemble tout au long de cette toute nouvelle aventure. »</p>
<p><span ><em>Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</em></span></p>
', 'Interview', '/images/news/guillaume-duquenne-jrsquoai-appris-la-loi-de-la-concurrence-car-rien-nest-acquis.png', true, '1689607853000', '1774831606852', '1774833441758');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'communique-officiel', '🚨[COMMUNIQUÉ OFFICIEL]🚨', 'Nous avons le grand plaisir aujourd’hui de vous annoncer que l’Anglet Hormadi Pays Basque a été officiellement VALIDÉ par la CNSCG en Synerglace Ligue Magnus pour la saison 2023-2024.🥳🔥 Au mois de septembre, nous entamerons donc TOUS ENSEMBLE : partenaires, sponsors, supporteurs, bénévoles, notre ', '<div  data-block="true" data-editor="6gep6" data-offset-key="dn0h8-0-0">
<div data-offset-key="dn0h8-0-0"></div>
<div  data-offset-key="dn0h8-0-0"><span data-offset-key="1lijn-0-0">Nous avons le grand plaisir aujourd’hui de vous annoncer que l’Anglet Hormadi Pays Basque a été officiellement VALIDÉ par la CNSCG en </span><span  spellcheck="false" data-offset-key="1lijn-1-0"><span data-offset-key="1lijn-1-0">Synerglace Ligue Magnus</span></span><span data-offset-key="1lijn-2-0"> pour la saison 2023-2024.🥳🔥</span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="e3o9k-0-0">
<div  data-offset-key="e3o9k-0-0"><span data-offset-key="e3o9k-0-0"> </span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="d6kr3-0-0">
<div  data-offset-key="d6kr3-0-0"><span data-offset-key="d6kr3-0-0">Au mois de septembre, nous entamerons donc TOUS ENSEMBLE : partenaires, sponsors, supporteurs, bénévoles, notre 6e saison consécutive dans l’élite de notre sport.💚❤️</span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="1gglp-0-0">
<div  data-offset-key="1gglp-0-0"><span data-offset-key="1gglp-0-0"> </span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="a6a9i-0-0">
<div  data-offset-key="a6a9i-0-0"><span data-offset-key="a6a9i-0-0">Notre président, Cédric Cazenabe, tenait à adresser quelques mots à ce sujet-là : </span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="ar8o1-0-0">
<div  data-offset-key="ar8o1-0-0"><span data-offset-key="ar8o1-0-0"> </span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="5r7ph-0-0">
<div  data-offset-key="5r7ph-0-0"><span data-offset-key="5r7ph-0-0">« Je me réjouis pour ma première saison officielle de vous annoncer la validation de notre club en Synerglace Ligue Magnus pour la 6ème saison consécutive. Notre combat sera sur la glace avec notre équipe et notre staff, mais aussi, donner une stabilité financière et stratégique pour garantir une continuité saine de notre beau club dans la durée. Nous voulons par ce petit mot, vous indiquer de grands changements lors de nos matchs, mais également, sur l’approche d’accompagnement de nos partenaires nouveaux ou renouvelants. </span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="54rgd-0-0">
<div  data-offset-key="54rgd-0-0"><span data-offset-key="54rgd-0-0">Alors juste, MERCI à l’ensemble de nos soutiens, des équipes internes du club, nos bénévoles, nos abonnés et nos supporters ainsi que toute personne qui suit notre club.</span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="a99ou-0-0">
<div  data-offset-key="a99ou-0-0"><span data-offset-key="a99ou-0-0">En dernier mot, retrouvons-nous le 1er septembre à la Barre pour un grand événement annoncé sous quelques jours. »</span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="2i0l6-0-0">
<div  data-offset-key="2i0l6-0-0"><span data-offset-key="2i0l6-0-0"> </span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="59g67-0-0">
<div  data-offset-key="59g67-0-0"><span data-offset-key="59g67-0-0">Restez connectés, la suite arrive bientôt…⏳</span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="foigi-0-0">
<div  data-offset-key="foigi-0-0"><span data-offset-key="foigi-0-0"> </span></div>
</div>
<div  data-block="true" data-editor="6gep6" data-offset-key="cflj3-0-0">
<div  data-offset-key="cflj3-0-0"><span  spellcheck="false" data-offset-key="cflj3-0-0"><span data-offset-key="cflj3-0-0">#GoHormadi</span></span><span data-offset-key="cflj3-1-0"> | </span><span  spellcheck="false" data-offset-key="cflj3-2-0"><span data-offset-key="cflj3-2-0">#JoTaKeIrabaziArte</span></span></div>
</div>
', 'Vie du Club', '/images/news/communique-officiel.jpg', true, '1689088891000', '1774831607807', '1774833441758');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'craig-puffer-jrsquoaime-quand-la-pression-monte-et-repondre-present-dans-les-moments-importants', 'Craig Puffer : « J&rsquo;aime quand la pression monte et répondre présent dans les moments importants »', 'Après des passages très remarqués en Norvège puis au Danemark notamment, l&rsquo;ailier gaucher américain, Craig Puffer, a fait le choix de poursuivre son chemin européen à la Barre la saison prochaine. Entretien exclusif avec notre futur numéro 71, qui sera vraisemblablement l&rsquo;une des têtes d', '<h4>Après des passages très remarqués en Norvège puis au Danemark notamment, l&rsquo;ailier gaucher américain, Craig Puffer, a fait le choix de poursuivre son chemin européen à la Barre la saison prochaine. Entretien exclusif avec notre futur numéro 71, qui sera vraisemblablement l&rsquo;une des têtes d&rsquo;affiche de l&rsquo;effectif angloy lors du prochain exercice.</h4>
<figure id="attachment_16496" aria-describedby="caption-attachment-16496"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Puffer-2-300x200.jpg" alt="" width="422" height="281" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-2-300x200.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-2-1024x683.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-2-768x512.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-2-128x85.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-2-32x21.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-2-360x240.jpg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-2-98x65.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-2.jpg 1400w" sizes="auto, (max-width: 422px) 100vw, 422px" /><figcaption id="caption-attachment-16496" ><span ><em>Craig Puffer sous les couleurs d&rsquo;Esbjerg (2021-2022).</em></span></figcaption></figure>
<p><em><strong>Cela fait maintenant 4 ans que tu évolues en Europe, ce sera ta cinquième année à partir du mois de septembre ici à Anglet, tu t’es désormais bien adapté à cette culture et ce train de vie qui est différent des États-Unis ?</strong></em></p>
<p><span ><strong>Craig Puffer :</strong></span> « Oui, j&rsquo;aime vraiment être à l&rsquo;étranger. J&rsquo;aime découvrir les nouvelles cultures que chaque pays a à offrir. Ces quatre dernières années ont été très amusantes et j&rsquo;ai vraiment hâte de pouvoir découvrir la France et Anglet en particulier ! »</p>
<p><em><strong>Tu as connu 3 clubs en Europe depuis ton arrivée en 2019 : Manglerud en élite norvégienne, Esbjerg en élite danoise et enfin la saison passée Nottingham en EIHL, le championnat britannique. Ce sont des ligues avec un hockey différent selon toi ?</strong></em></p>
<p><span ><strong>Craig Puffer :</strong></span> « J&rsquo;ai l&rsquo;impression que toutes ces ligues sont similaires, surtout pour le Danemark et la Norvège, qui ont ce style nordique, et de ce fait, mon style de jeu semble bien correspondre à celles-ci. J&rsquo;ai également entendu de bonnes choses de la part d&rsquo;anciens joueurs avec qui j&rsquo;ai pu évoluer sur la ligue française et je suis impatient de commencer ce nouveau chapitre et cette nouvelle saison. »</p>
<p><em><strong>Tu as affolé les compteurs en Norvège et lors de tes deux saisons au Danemark, avec pas moins d’un point par match en moyenne, tu étais dans une forme étincelante durant cette période ?</strong></em></p>
<p><strong><span ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/puffer-300x200.jpg" alt="" width="383" height="255" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/puffer-300x200.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/puffer-1024x682.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/07/puffer-768x512.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/puffer-128x85.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/puffer-32x21.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/puffer-360x240.jpg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/07/puffer-98x65.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/07/puffer.jpg 1400w" sizes="auto, (max-width: 383px) 100vw, 383px" />Craig Puffer :</span></strong> « Oui, la Norvège était ma première saison complète après ma carrière universitaire et je me suis tout de suite sentie à l&rsquo;aise avec Manglerud. J&rsquo;ai eu la chance de jouer avec d&rsquo;excellents joueurs et, heureusement, j&rsquo;ai pu faire de bonnes performances moi-même. Quant au Danemark, je m&rsquo;étais déjà bien adapté au hockey européen et j&rsquo;ai pu jouer en toute confiance. J&rsquo;ai vraiment apprécié mes deux saisons à Esbjerg. »</p>
<p><em><strong>La saison dernière à Nottingham, tu as découvert un championnat bien différent des ligues nordiques, cela a été plus difficile pour toi ?</strong></em></p>
<p><span ><strong>Craig Puffer :</strong></span> « La ligue anglaise est considérée comme un peu différente et plus comparable au hockey nord-américain, mais j&rsquo;ai quand même trouvé cela agréable. Nous avions une équipe très talentueuse l&rsquo;année dernière et les rôles étaient bien répartis. Nottingham a été un endroit formidable, mais j&rsquo;ai hâte de retrouver le hockey européen. »</p>
<p><em><strong>Tu rejoins donc l’Hormadi la saison prochaine, quelles ont été les raisons de ce choix de venir à Anglet et en France ?</strong></em></p>
<p><strong><span >Craig Puffer : </span></strong><span ><span >« Comme je l&rsquo;ai déjà dit, d&rsquo;anciens joueurs m&rsquo;ont dit beaucoup de bien de la ligue et d&rsquo;Anglet en particulier. Anglet m&rsquo;a contacté au tout début de l&rsquo;intersaison, le club était sur mon radar. Après avoir discuté avec Xavier (Daramy), j&rsquo;ai compris qu&rsquo;Anglet était une organisation formidable et qu&rsquo;elle me conviendrait parfaitement afin que je puisse m&rsquo;épanouir sur la glace à 200%. »</span></span></p>
<figure id="attachment_16498" aria-describedby="caption-attachment-16498"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-03-a-10.37.09-267x300.png" alt="" width="340" height="382" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-03-a-10.37.09-267x300.png 267w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-03-a-10.37.09-114x128.png 114w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-03-a-10.37.09-28x32.png 28w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-03-a-10.37.09-87x98.png 87w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Capture-decran-2023-07-03-a-10.37.09.png 542w" sizes="auto, (max-width: 340px) 100vw, 340px" /><figcaption id="caption-attachment-16498" ><span ><em>L&rsquo;ailier gauche américain évoluait à Nottingham en EIHL la saison dernière.</em></span></figcaption></figure>
<p><em><strong>Tu joueras sans aucun doute un rôle majeur dans l’équipe avec des responsabilités offensives, tu seras l’une des pointures, est-ce un rôle qui te plaît et qui ressemble à celui que tu as connu en Norvège ou au Danemark ?</strong></em></p>
<p><span ><strong>Craig Puffer :</strong></span> « Oui, c&rsquo;est toujours agréable de pouvoir compter sur une contribution à l&rsquo;équipe d&rsquo;une manière ou d&rsquo;une autre. J&rsquo;ai eu des rôles similaires dans le passé, comme vous l&rsquo;avez mentionné, et je pense que c&rsquo;est à ce moment-là que je peux être créatif et donner le meilleur de moi-même. »</p>
<p><em><strong>Quel profil d’ailier es-tu sur la glace ? Plutôt bon buteur et bon patineur ?</strong></em></p>
<p><strong><span >Craig Puffer :</span></strong> « J&rsquo;ai le sentiment d&rsquo;être un joueur à double sens, capable de contribuer offensivement tout en étant responsable défensivement. J&rsquo;ai eu du succès en tant que marqueur de buts au cours des dernières années et je crois que ma force est de bien voir la glace et d&rsquo;essayer d&rsquo;avoir une longueur d&rsquo;avance sur le jeu. J&rsquo;essaye toujours d&rsquo;anticiper mon mouvement, et de réfléchir rapidement à comment l&rsquo;action peut se conclure. J&rsquo;ai joué plusieurs rôles dans des équipes et je suis prêt à contribuer du mieux que je peux. »</p>
<p><strong><em>Peux-tu nous parler un peu de ta personnalité sur et en dehors de la glace ?</em></strong></p>
<p><strong><span >Craig Puffer :</span></strong> « Sur la glace, j&rsquo;aime être près du palet et m&rsquo;impliquer autant que possible. En dehors de la glace, je suis plutôt une personne très calme et j&rsquo;aime voyager, jouer au golf et explorer les villes voisines. »</p>
<figure id="attachment_16495" aria-describedby="caption-attachment-16495"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Puffer-.jpg-300x173.webp" alt="" width="345" height="199" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-.jpg-300x173.webp 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-.jpg-1024x592.webp 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-.jpg-768x444.webp 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-.jpg-1536x887.webp 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-.jpg-2048x1183.webp 2048w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-.jpg-128x74.webp 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-.jpg-32x18.webp 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Puffer-.jpg-98x57.webp 98w" sizes="auto, (max-width: 345px) 100vw, 345px" /><figcaption id="caption-attachment-16495" ><span ><em>Craig Puffer portera le numéro 71 à l&rsquo;Hormadi la saison prochaine.</em></span></figcaption></figure>
<p><em><strong>Tu es un gars qui performe en play-offs et décisifs dans les moments importants, on l’a vu au Danemark notamment, c’est je suppose, l’un de tes objectifs également avec Anglet ?</strong></em></p>
<p><strong><span >Craig Puffer :</span></strong> « J&rsquo;aimerais avoir un impact dans les séries éliminatoires. J&rsquo;aime quand la pression monte et répondre présent dans les moments importants notamment lorsqu&rsquo;on joue en post-saison. Cependant, je ne regarde pas au-delà des matchs de la saison régulière et je prendrai les choses au fur et à mesure, c&rsquo;est la règle première. »</p>
<p><em><strong>La construction de l’effectif touche bientôt à sa fin, il sera composé d’un certain nombre de joueurs nord-américains passés par la NCAA comme toi, quel regard portes-tu sur l’équipe actuellement et connais-tu certains gars qui feront partie de l’équipe la saison prochaine ?</strong></em></p>
<p><span ><strong>Craig Puffer :</strong></span> « Oui, c&rsquo;est cool de voir des coéquipiers suivre la voie du hockey universitaire. Je pense que c&rsquo;est la meilleure façon de procéder et que nous devrions tous nous sentir à l&rsquo;aise dès le départ en ayant des parcours similaires. Je ne connais personne personnellement, mais j&rsquo;ai contacté quelques gars jusqu&rsquo;à présent afin de commencer à intégrer au mieux l&rsquo;équipe et faire également connaissance avec tout le monde. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/07/Craig-Puffer-300x200.jpg" alt="" width="338" height="225" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/07/Craig-Puffer-300x200.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Craig-Puffer-1024x683.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Craig-Puffer-768x512.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Craig-Puffer-1536x1024.jpg 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Craig-Puffer-2048x1365.jpg 2048w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Craig-Puffer-128x85.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Craig-Puffer-32x21.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Craig-Puffer-360x240.jpg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/07/Craig-Puffer-98x65.jpg 98w" sizes="auto, (max-width: 338px) 100vw, 338px" />Pour conclure, as-tu quelques mots pour les fans avant ton arrivée en France au mois d’août ?</strong></em></p>
<p><strong><span >Craig Puffer :</span></strong> « Je suis impatient d&rsquo;arriver à Anglet, de voir tous les fans, j&rsquo;ai eu de bons échos sur eux, de jouer devant vous et, je l&rsquo;espère, de faire vibrer l&rsquo;arène toute au long de l&rsquo;année. On se voit tous dès le mois d&rsquo;août ! »</p>
<p><span >Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</span></p>
<p>&nbsp;</p>
', 'Interview', '/images/news/craig-puffer-jrsquoaime-quand-la-pression-monte-et-repondre-present-dans-les-mom.jpg', true, '1688568338000', '1774831610433', '1774833441758');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'dylan-st-cyr-etre-une-equipe-qui-a-une-bonne-culture-et-qui-aime-etre-sur-la-patinoire-est-probablement-la-chose-la-plus', 'Dylan St. Cyr : « Être une équipe qui a une bonne culture et qui aime être sur la patinoire, est probablement la chose la plus importante à mes yeux »', 'Il sera l&rsquo;une des attractions la saison prochaine, Dylan St. Cyr, le portier américain champion du monde U18 avec Team USA en 2017, a fait le choix de quitter l&rsquo;Amérique du Nord afin de rejoindre le Pays Basque et l&rsquo;Hormadi dès le mois d&rsquo;août. Fils de Manon Rhéaume, première ', '<h4>Il sera l&rsquo;une des attractions la saison prochaine, Dylan St. Cyr, le portier américain champion du monde U18 avec Team USA en 2017, a fait le choix de quitter l&rsquo;Amérique du Nord afin de rejoindre le Pays Basque et l&rsquo;Hormadi dès le mois d&rsquo;août. Fils de Manon Rhéaume, première femme qui a évolué dans la NHL, Dylan possède une histoire particulière en plus d&rsquo;avoir du talent. Entretien exclusif avec notre futur gardien et numéro 37 angloy.</h4>
<figure id="attachment_16422" aria-describedby="caption-attachment-16422"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/Dylan-St.-Cyr.jpg-300x169.webp" alt="" width="466" height="262" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/Dylan-St.-Cyr.jpg-300x169.webp 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Dylan-St.-Cyr.jpg-1024x576.webp 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Dylan-St.-Cyr.jpg-768x432.webp 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Dylan-St.-Cyr.jpg-1536x864.webp 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Dylan-St.-Cyr.jpg-128x72.webp 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Dylan-St.-Cyr.jpg-32x18.webp 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Dylan-St.-Cyr.jpg-98x55.webp 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Dylan-St.-Cyr.jpg.webp 1920w" sizes="auto, (max-width: 466px) 100vw, 466px" /><figcaption id="caption-attachment-16422" ><em><span >Dylan St. Cyr à Michigan State (NCAA).</span></em></figcaption></figure>
<p><em><strong>Tu connaîtras ta première expérience en dehors du continent nord-américain la saison prochaine, as-tu une forme d’appréhension de quitter le pays ?</strong></em></p>
<p><strong><span >Dylan St. Cyr :</span></strong> « Je suis déjà allé en Europe à plusieurs reprises pour participer à des tournois internationaux notamment, donc je ne dirais pas que j&rsquo;appréhende nécessairement de jouer au hockey en dehors de l&rsquo;Amérique du Nord. Cependant, c&rsquo;est certainement la première fois que je vais vivre en dehors des États-Unis. Je dirais plutôt que je suis vraiment très enthousiaste à l&rsquo;idée de déménager et que j&rsquo;ai hâte de m&rsquo;immerger dans une toute nouvelle culture. »</p>
<p>&nbsp;</p>
<p><em><strong>Tu sors de 5 bonnes saisons en NCAA (meilleure ligue universitaire américaine), avec des passages à Notre Dame, Quinnipiac et Michigan State, trois universités réputées aux États-Unis, comment juges-tu ta </strong></em><em><strong>progression au cours de ces 5 années ?</strong></em></p>
<p><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/00a848d3-9832-4dbd-92ca-bb86e7f31666-DSC_7457.jpg-300x200.webp" alt="" width="246" height="164" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/00a848d3-9832-4dbd-92ca-bb86e7f31666-DSC_7457.jpg-300x200.webp 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/00a848d3-9832-4dbd-92ca-bb86e7f31666-DSC_7457.jpg-1024x683.webp 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/06/00a848d3-9832-4dbd-92ca-bb86e7f31666-DSC_7457.jpg-768x512.webp 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/00a848d3-9832-4dbd-92ca-bb86e7f31666-DSC_7457.jpg-1536x1024.webp 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/06/00a848d3-9832-4dbd-92ca-bb86e7f31666-DSC_7457.jpg-2048x1365.webp 2048w, https://pro.hormadi.fr/wp-content/uploads/2023/06/00a848d3-9832-4dbd-92ca-bb86e7f31666-DSC_7457.jpg-128x85.webp 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/00a848d3-9832-4dbd-92ca-bb86e7f31666-DSC_7457.jpg-32x21.webp 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/00a848d3-9832-4dbd-92ca-bb86e7f31666-DSC_7457.jpg-360x240.webp 360w, https://pro.hormadi.fr/wp-content/uploads/2023/06/00a848d3-9832-4dbd-92ca-bb86e7f31666-DSC_7457.jpg-98x65.webp 98w" sizes="auto, (max-width: 246px) 100vw, 246px" /></p>
<p><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/2-3-HCK-29-900x643-2-300x214.jpg" alt="" width="230" height="164" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/2-3-HCK-29-900x643-2-300x214.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/2-3-HCK-29-900x643-2-768x549.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/2-3-HCK-29-900x643-2-128x91.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/2-3-HCK-29-900x643-2-32x23.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/2-3-HCK-29-900x643-2-255x183.jpg 255w, https://pro.hormadi.fr/wp-content/uploads/2023/06/2-3-HCK-29-900x643-2-350x250.jpg 350w, https://pro.hormadi.fr/wp-content/uploads/2023/06/2-3-HCK-29-900x643-2-98x70.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/2-3-HCK-29-900x643-2.jpg 900w" sizes="auto, (max-width: 230px) 100vw, 230px" /></p>
<p><strong><span >Dylan St. Cyr :</span> </strong>« Le parcours était vraiment unique. Être gardien de but à l&rsquo;université, peut être difficile si l&rsquo;on n&rsquo;est pas le titulaire, car le calendrier permet à un seul gardien d&rsquo;assumer la majeure partie des matchs. Cela dit, je crois que tous les revers que j&rsquo;ai rencontrés à l&rsquo;université m&rsquo;ont permis de grandir non seulement en tant que joueur de hockey, mais aussi en tant que personne. J&rsquo;ai vécu une expérience formidable dans chacune de mes destinations, et je suis très heureux de sortir de ma meilleure saison à Michigan State. »</p>
<figure id="attachment_16444" aria-describedby="caption-attachment-16444"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/Fslv9z0X0AA5Qr0-300x200.jpeg" alt="" width="372" height="248" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/Fslv9z0X0AA5Qr0-300x200.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Fslv9z0X0AA5Qr0-1024x683.jpeg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Fslv9z0X0AA5Qr0-768x512.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Fslv9z0X0AA5Qr0-1536x1024.jpeg 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Fslv9z0X0AA5Qr0-2048x1366.jpeg 2048w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Fslv9z0X0AA5Qr0-128x85.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Fslv9z0X0AA5Qr0-32x21.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Fslv9z0X0AA5Qr0-360x240.jpeg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Fslv9z0X0AA5Qr0-98x65.jpeg 98w" sizes="auto, (max-width: 372px) 100vw, 372px" /><figcaption id="caption-attachment-16444" ><em><span >Dylan St. Cyr lors de ses débuts en AHL avec les Griffins Grand Rapids.</span></em></figcaption></figure>
<p><em><strong>En fin de saison dernière, tu es appelé en AHL par les Griffins Grand Rapids, le club école de Détroit, avec qui tu as réalisé un blanchissage notamment, que retiens-tu de cette expérience et quel sentiment apparaît lorsqu’on passe de la NCAA au monde professionnel et l’AHL ?</strong></em></p>
<p><strong><span >Dylan St. Cyr :</span></strong> « Eh bien, c&rsquo;était vraiment une expérience amusante et je me suis retrouvé dans cette atmosphère. Je suis entré en jeu à la moitié du match en remplacement de l&rsquo;autre gardien, ce n&rsquo;est donc pas comme ça que l&rsquo;on résume sa première expérience professionnelle, mais je me suis senti chanceux d&rsquo;avoir pu prendre part au match. La différence entre l&rsquo;AHL et la NCAA était clairement perceptible, surtout à l&rsquo;entraînement. Je pense que cette exposition m&rsquo;a aidé à mettre en perspective les points que je dois améliorer pour jouer à ce niveau. »</p>
<p><em><strong>En 2017, tu es sacré médaillé d’or et champion du monde U18 avec l’équipe nationale des États-Unis, c’est quelque chose d’unique pour un jeune joueur à cet âge-là, peux-tu nous raconter cette belle épopée et quels souvenirs gardes-tu dans ta mémoire ?</strong></em></p>
<p><strong><span >Dylan St. Cyr :</span></strong> « Ce fut sans aucun doute l&rsquo;un des moments les plus excitants de ma carrière de hockeyeur. Même si j&rsquo;étais jeune, le chemin parcouru par notre équipe pour remporter ce championnat est ce qui l&rsquo;a rendu si gratifiant. La première année, nous n&rsquo;avons remporté aucun de nos trois tournois internationaux et avons été considérés comme la pire équipe de l&rsquo;USNTDP (United States National Development Program) à avoir suivi le programme. La transition vers notre deuxième année a été passionnante, car notre objectif était de remporter la médaille d&rsquo;or lors de notre dernier tournoi de l&rsquo;année. Passer un mois en Slovaquie et gagner ce tournoi à ce niveau, a été l&rsquo;une des expériences les plus enrichissantes de ma carrière de hockeyeur à ce jour. »</p>
<figure id="attachment_16464" aria-describedby="caption-attachment-16464"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/Capture-decran-2023-06-29-a-10.49.50-300x173.png" alt="" width="419" height="241" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/Capture-decran-2023-06-29-a-10.49.50-300x173.png 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Capture-decran-2023-06-29-a-10.49.50-1024x590.png 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Capture-decran-2023-06-29-a-10.49.50-768x442.png 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Capture-decran-2023-06-29-a-10.49.50-1536x884.png 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Capture-decran-2023-06-29-a-10.49.50-2048x1179.png 2048w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Capture-decran-2023-06-29-a-10.49.50-128x74.png 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Capture-decran-2023-06-29-a-10.49.50-32x18.png 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Capture-decran-2023-06-29-a-10.49.50-98x56.png 98w" sizes="auto, (max-width: 419px) 100vw, 419px" /><figcaption id="caption-attachment-16464" ><em><span >Quinn Hughes (à gauche) et Dylan St. Cyr (au centre) lors du sacre de Team USA en 2017.</span></em></figcaption></figure>
<p><em><strong>Tu avais également été le meilleur gardien de cette compétition, avec comme backup un certain Cayden Primeau (actuel gardien chez les Canadiens de Montréal), tu évoluais aux côtés de noms connus de la NHL comme Quinn Hughes ou Brady Tkatchuk, est-ce que le fait de voir ces joueurs-là performer en NHL, te laisse un goût amer de ne pas avoir été repêché ?</strong></em></p>
<p><span ><strong>Dylan St. Cyr :</strong></span> « Je pense qu&rsquo;à l&rsquo;époque, c&rsquo;était un peu frustrant, mais avec le temps, j&rsquo;ai continué à réaliser à quel point la taille est un facteur déterminant pour atteindre le niveau supérieur, en particulier à mon poste. Le chemin que j&rsquo;ai emprunté m&rsquo;a apporté beaucoup de bien, et je pense que les autres facteurs liés à ma taille et au fait de ne pas avoir été repêché sont des choses que je ne peux pas contrôler et qui m&rsquo;ont bien servi de motivation et qui continueront de me servir de motivation pour la suite. »</p>
<figure id="attachment_16424" aria-describedby="caption-attachment-16424"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/zqh.HKYvsU18.11.16.18._0268.jpg-300x200.webp" alt="" width="344" height="229" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/zqh.HKYvsU18.11.16.18._0268.jpg-300x200.webp 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/zqh.HKYvsU18.11.16.18._0268.jpg-128x86.webp 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/zqh.HKYvsU18.11.16.18._0268.jpg-32x21.webp 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/zqh.HKYvsU18.11.16.18._0268.jpg-360x240.webp 360w, https://pro.hormadi.fr/wp-content/uploads/2023/06/zqh.HKYvsU18.11.16.18._0268.jpg-98x65.webp 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/zqh.HKYvsU18.11.16.18._0268.jpg.webp 720w" sizes="auto, (max-width: 344px) 100vw, 344px" /><figcaption id="caption-attachment-16424" ><em><span >Dylan St. Cyr arborant le chandail de son équipe nationale américaine.</span></em></figcaption></figure>
<p><em><strong>Tu porteras donc les couleurs de l’Hormadi la saison prochaine, pourquoi ce choix de venir en France et à Anglet ?</strong></em></p>
<p><strong><span >Dylan St. Cyr :</span> </strong>« Eh bien, après cette dernière saison, j&rsquo;ai senti, pour les mêmes raisons que celles que j&rsquo;ai évoquées dans la dernière question, que mon parcours professionnel serait mieux adapté en Europe. La France, et Anglet en particulier, semble être un endroit extrêmement attrayant pour vivre et m&rsquo;immerger dans une nouvelle culture. C&rsquo;est une excellente occasion de commencer ma carrière professionnelle à l&rsquo;étranger. »</p>
<p><em><strong>Un gardien de petite taille comme toi fait toujours parler, surtout avec une histoire particulière comme la tienne, quel style de gardien es-tu dans tes filets ?</strong></em></p>
<p><span ><strong>Dylan St. Cyr :</strong></span> « Je pense qu&rsquo;il y a des domaines sur lesquels je me concentre pour compenser mon manque de taille. Mon patinage et ma capacité à manier le palet sont des aspects cruciaux sur lesquels je m&rsquo;appuie pour faire la différence sur la glace, en plus de ma compétitivité. »</p>
<p><em><strong>Le fait d’avoir une mère qui s’appelle Manon Rhéaume, mondialement connu dans le hockey sur glace pour avoir été la première femme à évoluer dans la NHL, te rajoute une forme de pression supplémentaire ?</strong></em></p>
<p><span ><strong>Dylan St. Cyr :</strong></span> « Non, je ne pense pas que cela ajoute une quelconque pression. C&rsquo;est vraiment passionnant de voir l&rsquo;impact qu&rsquo;elle a eu, et qu&rsquo;elle continue d&rsquo;avoir, sur le hockey. Cela dit, nous sommes deux personnes différentes avec des parcours différents, et j&rsquo;ai l&rsquo;intention d&rsquo;avoir mon propre impact sur le jeu à ma façon. »</p>
<figure id="attachment_16419" aria-describedby="caption-attachment-16419"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/37012374-41b5-4f26-b192-693ef93dafcd-Young_Dylan_St._Cyr_with_mom_Manon_Rheaume_1.jpg-300x182.webp" alt="" width="433" height="262" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/37012374-41b5-4f26-b192-693ef93dafcd-Young_Dylan_St._Cyr_with_mom_Manon_Rheaume_1.jpg-300x182.webp 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/37012374-41b5-4f26-b192-693ef93dafcd-Young_Dylan_St._Cyr_with_mom_Manon_Rheaume_1.jpg-1024x623.webp 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/06/37012374-41b5-4f26-b192-693ef93dafcd-Young_Dylan_St._Cyr_with_mom_Manon_Rheaume_1.jpg-768x467.webp 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/37012374-41b5-4f26-b192-693ef93dafcd-Young_Dylan_St._Cyr_with_mom_Manon_Rheaume_1.jpg-128x78.webp 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/37012374-41b5-4f26-b192-693ef93dafcd-Young_Dylan_St._Cyr_with_mom_Manon_Rheaume_1.jpg-32x19.webp 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/37012374-41b5-4f26-b192-693ef93dafcd-Young_Dylan_St._Cyr_with_mom_Manon_Rheaume_1.jpg-98x60.webp 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/37012374-41b5-4f26-b192-693ef93dafcd-Young_Dylan_St._Cyr_with_mom_Manon_Rheaume_1.jpg.webp 1284w" sizes="auto, (max-width: 433px) 100vw, 433px" /><figcaption id="caption-attachment-16419" ><span ><em>Dylan St. Cyr aux côtés de Manon Rhéaume (sa mère), première femme a avoir évolué en NHL, vice-championne olympique, double championne du monde avec le Canada.</em></span></figcaption></figure>
<p><em><strong>Est-ce un exemple pour toi sur la glace et en dehors, t’encourage-t-elle dans ce nouveau challenge et cette nouvelle vie que tu vas connaître ?</strong></em></p>
<p><span ><strong>Dylan St. Cyr :</strong> </span>« Mes deux parents m&rsquo;ont soutenu à leur manière dans ma carrière de hockeyeur, compte tenu de leur propre expérience dans ce domaine. J&rsquo;ai la chance qu&rsquo;ils ne soient pas autoritaires, ce qui me permet de prendre des décisions par moi-même, tout en les consultant en cas de questions. »</p>
<p><em><strong>Va-t-elle venir te rendre visite durant la saison, bien qu’elle soit très occupée dans son nouveau job chez les Kings de Los Angeles?</strong></em></p>
<p><span ><strong>Dylan St. Cyr :</strong></span> « Oui bien sûr, elle prévoit de faire un voyage cette saison afin de venir me rendre visite. »</p>
<p><em><strong>Te conseille-t-elle à tant qu’ancienne gardienne de but, même si le hockey a bien changé depuis son époque ?</strong></em></p>
<p><span ><strong>Dylan St. Cyr :</strong></span> « Honnêtement, elle ne s&rsquo;est pas beaucoup occupée de moi, surtout ces dernières années, car je me sens à l&rsquo;aise dans ma carrière de hockeyeur. Mais, comme je l&rsquo;ai dit, elle est toujours disponible pour me consulter en cas de besoin. »</p>
<figure id="attachment_16421" aria-describedby="caption-attachment-16421"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/b1f18624-c394-4c6d-8844-3f3b3075099d-Dylan_St._Cyr_and_mom_Manon_Rheaume.jpg-300x270.webp" alt="" width="331" height="298" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/b1f18624-c394-4c6d-8844-3f3b3075099d-Dylan_St._Cyr_and_mom_Manon_Rheaume.jpg-300x270.webp 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/b1f18624-c394-4c6d-8844-3f3b3075099d-Dylan_St._Cyr_and_mom_Manon_Rheaume.jpg-1024x922.webp 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/06/b1f18624-c394-4c6d-8844-3f3b3075099d-Dylan_St._Cyr_and_mom_Manon_Rheaume.jpg-768x691.webp 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/b1f18624-c394-4c6d-8844-3f3b3075099d-Dylan_St._Cyr_and_mom_Manon_Rheaume.jpg-128x115.webp 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/b1f18624-c394-4c6d-8844-3f3b3075099d-Dylan_St._Cyr_and_mom_Manon_Rheaume.jpg-32x29.webp 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/b1f18624-c394-4c6d-8844-3f3b3075099d-Dylan_St._Cyr_and_mom_Manon_Rheaume.jpg-445x400.webp 445w, https://pro.hormadi.fr/wp-content/uploads/2023/06/b1f18624-c394-4c6d-8844-3f3b3075099d-Dylan_St._Cyr_and_mom_Manon_Rheaume.jpg-98x88.webp 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/b1f18624-c394-4c6d-8844-3f3b3075099d-Dylan_St._Cyr_and_mom_Manon_Rheaume.jpg.webp 1284w" sizes="auto, (max-width: 331px) 100vw, 331px" /><figcaption id="caption-attachment-16421" ><em><span >La médaille d&rsquo;or autour du cou de Dylan St. Cyr.</span></em></figcaption></figure>
<p><em><strong>Quels sont tes objectifs avec l’Hormadi la saison prochaine ?</strong></em></p>
<p><strong><span >Dylan St. Cyr :</span> </strong>« Je dirais que le fait d&rsquo;être une équipe qui a une bonne culture et qui aime être sur la patinoire est probablement la chose la plus importante à mes yeux. Je dirais que cela jette les bases de tous les objectifs mesurables que nous voulons atteindre cette saison. »</p>
<p><em><strong>Connais-tu quelques joueurs qui, eux aussi, ont signé à Anglet la saison prochaine, on peut penser notamment à des joueurs en provenance de NCAA comme toi ?</strong></em></p>
<p><span ><strong>Dylan St. Cyr :</strong> </span>« Je ne connais personnellement personne dans l&rsquo;équipe, mais je dirais qu&rsquo;il y a quelques gars avec des amis communs. J&rsquo;ai été en contact avec certains d&rsquo;entre eux. J&rsquo;ai regardé un petit peu l&rsquo;effectif, il est de qualité, j&rsquo;ai hâte de rencontrer les gars en personne. »</p>
<p><em><strong>Ton français s’est-il amélioré depuis ta signature ?</strong></em></p>
<p><strong><span >Dylan St. Cyr :</span></strong> « Haha (rires), je vais chercher à travailler mon français pendant la saison. Même si c&rsquo;est différent, j&rsquo;ai des antécédents canadiens-français qui, je l&rsquo;espère, me serviront de base pour apprendre la langue en France et m&rsquo;y adapter. »</p>
<figure id="attachment_16423" aria-describedby="caption-attachment-16423"  ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/St._Cyr_v3MkR-300x169.jpg" alt="" width="405" height="228" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/St._Cyr_v3MkR-300x169.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/St._Cyr_v3MkR-1024x576.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/06/St._Cyr_v3MkR-768x432.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/St._Cyr_v3MkR-1536x864.jpg 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/06/St._Cyr_v3MkR-128x72.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/St._Cyr_v3MkR-32x18.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/St._Cyr_v3MkR-98x55.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/St._Cyr_v3MkR.jpg 2000w" sizes="auto, (max-width: 405px) 100vw, 405px" /><figcaption id="caption-attachment-16423" ><em><span >Notre tout nouveau portier américain Dylan St. Cyr.</span></em></figcaption></figure>
<p><strong>Pour conclure, aurais-tu un petit mot pour les fans qui ont hâte de te découvrir ?</strong></p>
<p><span ><strong>Dylan St. Cyr :</strong></span> « Je dirais simplement que je suis ravi de m&rsquo;installer à Anglet, je suis impatient, la saison morte est assez longue, ça me tarde de porter mes nouvelles couleurs et j&rsquo;espère que nous pourrons offrir un produit excitant sur la glace aux fans ! »</p>
<p><span >Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</span></p>
', 'Vie du Club', '/images/news/dylan-st-cyr-etre-une-equipe-qui-a-une-bonne-culture-et-qui-aime-etre-sur-la-pat.jpg', true, '1688049919000', '1774831611273', '1774833441759');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arnaud-faure-ou-lrsquohomme-de-lrsquoombre-devenu-indispensable', 'Arnaud Faure ou l&rsquo;homme de l&rsquo;ombre devenu indispensable', 'Arnaud Faure : « D&rsquo;avoir pu écouter Pierrick sur son projet, sur ce qu&rsquo;il veut mettre en place à moyen et long terme, ainsi que son enthousiasme par rapport à l&rsquo;équipe, montre que nous avons la même vision des choses. Il m&rsquo;a fait prendre conscience que c&rsquo;était à Anglet ', '<h3>Arnaud Faure : « D&rsquo;avoir pu écouter Pierrick sur son projet, sur ce qu&rsquo;il veut mettre en place à moyen et long terme, ainsi que son enthousiasme par rapport à l&rsquo;équipe, montre que nous avons la même vision des choses. Il m&rsquo;a fait prendre conscience que c&rsquo;était à Anglet que je devais signer »</h3>
<p>Finaliste des deux récentes éditons de la Coupe de France sous les couleurs de Gap, le défenseur français, Arnaud Faure, a décidé de troquer les montagnes afin de rejoindre l&rsquo;océan et l&rsquo;Hormadi à partir du mois d&rsquo;août prochain. Entretien exclusif avec notre numéro 6, qui nous en dit un peu plus sur lui à l&rsquo;approche de la nouvelle saison.</p>
<p><strong><em><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/53877602_2308821416004574_6255650781798596608_n-300x200.jpg" alt="" width="443" height="295" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/53877602_2308821416004574_6255650781798596608_n-300x200.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/53877602_2308821416004574_6255650781798596608_n-1024x683.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/06/53877602_2308821416004574_6255650781798596608_n-768x512.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/53877602_2308821416004574_6255650781798596608_n-1536x1024.jpg 1536w, https://pro.hormadi.fr/wp-content/uploads/2023/06/53877602_2308821416004574_6255650781798596608_n-128x85.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/53877602_2308821416004574_6255650781798596608_n-32x21.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/53877602_2308821416004574_6255650781798596608_n-360x240.jpg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/06/53877602_2308821416004574_6255650781798596608_n-98x65.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/53877602_2308821416004574_6255650781798596608_n.jpg 2048w" sizes="auto, (max-width: 443px) 100vw, 443px" /></em></strong></p>
<p><strong><em>Après des passages en Isère à Grenoble, dans les Vosges à Épinal puis dans la Maine-et-Loire à Angers, et enfin lors des quatre dernières saisons dans les Hautes-Alpes sous les couleurs de Gap, cela te fait déjà, à 27 ans seulement, un beau pedigree. Quel est ton secret pour réussir à t’imposer de la sorte au sein des grosses écuries du championnat ?</em></strong></p>
<p><span ><strong>Arnaud Faure :</strong></span> « <span >Il n&rsquo;y a pas vraiment de secret, il suffit de travailler, d&rsquo;être appliqué et surtout d&rsquo;être assidu dans l&rsquo;équipe, avoir une bonne relation avec tous les gars c&rsquo;est important. C&rsquo;est toujours ce que l&rsquo;on m&rsquo;a inculqué, et c&rsquo;est d&rsquo;ailleurs ce qu&rsquo;on souhaite mettre en place cette saison avec Pierrick (Rézard), Mathieu (Cyr) et toute l&rsquo;équipe. Après c&rsquo;est sûr, ça fait pas mal de bons clubs, j&rsquo;ai eu la chance de jouer deux ans à Grenoble, mon club formateur, je suis ensuite parti découvrir d&rsquo;autres horizons. Mais ce sont surtout les quatre dernières saisons à Gap qui ont été les plus constructives pour moi, j&rsquo;ai énormément progressé, j&rsquo;ai eu plus de responsabilités, ça m&rsquo;a permis d&rsquo;évoluer et de devenir le défenseur que je suis maintenant ».</span></p>
<p><em><strong>Tu sors justement de deux belles saisons sous le maillot des Rapaces de Gap, avec au tableau, deux finales de Coupe de France consécutives, malheureusement perdues, quels enseignements tires-tu de ces deux magnifiques parcours en tant que joueur et humainement ?</strong></em></p>
<p><strong><span >Arnaud Faure :</span></strong> « Oui on a eu la chance de jouer ces deux dernières finales, cette année en 2023, et celle d&rsquo;avant en 2022, avec malheureusement un dénouement assez cruel à chaque fois, surtout face à Grenoble cette année, ça était plus difficile à digérer. Mais ce sont des expériences incroyables, avec des parcours extraordinaires, des tours préliminaires à la finale. Et puis le Graal de fouler la glace de Bercy, devant une Accor Arena pleine en finale, c&rsquo;est peut-être quelque chose que l&rsquo;on vit qu&rsquo;une seule fois dans sa carrière. Forcément, c&rsquo;est mieux de la gagner, mais on ne peut pas tout contrôler. Humainement, ce sont des moments qui soudent encore plus un groupe, ça restera gravé à jamais dans ma mémoire ».</p>
<p><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/une-300x160.png" alt="" width="507" height="270" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/une-300x160.png 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/une-1024x546.png 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/06/une-768x409.png 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/une-128x68.png 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/une-32x17.png 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/une-98x52.png 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/une.png 1272w" sizes="auto, (max-width: 507px) 100vw, 507px" /><em>Vas-tu justement apporter ce savoir-faire à l’équipe la saison prochaine, que tu as pu acquérir à travers ses différentes expériences ?</em></strong></p>
<p><span ><strong>Arnaud Faure :</strong></span> « Oui c&rsquo;est le but, c&rsquo;est un luxe d&rsquo;avoir une certaine expérience, on devient de moins en moins jeune. D&rsquo;autant plus qu&rsquo;au vu du recrutement, avec des joueurs universitaires qui vont connaître leur première expérience en Europe, les plus anciens et moi, nous serons là pour faire le lien et partager notre savoir-faire avec eux. Cela fait partie du processus mis en place avec Pierrick ».</p>
<p><em><strong>Tu as décidé de rejoindre les rangs de l’Hormadi pour le prochain exercice, pourquoi ce choix et comment s’est concrétisée ta signature au club ?</strong></em></p>
<p><strong><span >Arnaud Faure :</span> </strong>« J&rsquo;en avais déjà discuté, je souhaitais après Gap, m&rsquo;orienter vers un club avec une philosophie similaire. J&rsquo;étais en discussion avec plusieurs clubs, mais j&rsquo;ai eu Pierrick très rapidement, et puis le fait de l&rsquo;avoir eu en assistant coach à Gap à l&rsquo;époque, ça a accéléré ma décision. D&rsquo;avoir pu l&rsquo;écouter sur son projet, sur ce qu&rsquo;il veut mettre en place à moyen et long terme, et également son enthousiasme par rapport à l&rsquo;équipe ainsi que mon ajout au groupe, nos échanges étaient très intéressants et constructifs. Il m&rsquo;a fait prendre conscience que c&rsquo;était à Anglet que je devais signer, afin d&rsquo;apporter mon jeu, mon expérience, ma bonne humeur au quotidien. On veut mettre ça en place avec Pierrick, se baser sur un groupe soudé, une cohésion d&rsquo;équipe au coeur du projet, nous avons la même vision des choses. J&rsquo;ai eu ensuite Xavier (Daramy), on a de suite trouver un terrain d&rsquo;entente, c&rsquo;est un beau défi qui m&rsquo;attend et j&rsquo;en suis très satisfait. »</p>
<p><em><strong>Quel est ton programme quotidien actuellement, ta préparation physique bat son plein ?</strong></em></p>
<p><strong><span >Arnaud Faure :</span> </strong>« Actuellement oui. Tous les jours, Flo (Neyens) m&rsquo;envoie un programme physique par mail, bien détaillé et très bien fait, qui justement explique parfaitement les exercices. Donc ouais, on est en plein dedans là, c&rsquo;est super, il y a une approche différente de ce que j&rsquo;ai pu connaître comme préparation physique auparavant. Il y a moins de barres, beaucoup plus d&rsquo;explosivité et d&rsquo;élastique, je découvre donc un nouveau fonctionnement, c&rsquo;est super intéressant ».</p>
<p><em><span ><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/IMG_4478-300x200.jpeg" alt="" width="442" height="294" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/IMG_4478-300x200.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/IMG_4478-1024x683.jpeg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/06/IMG_4478-768x512.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/IMG_4478-128x85.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/IMG_4478-32x21.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/IMG_4478-360x240.jpeg 360w, https://pro.hormadi.fr/wp-content/uploads/2023/06/IMG_4478-98x65.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/IMG_4478.jpeg 1170w" sizes="auto, (max-width: 442px) 100vw, 442px" /></strong></span></em></p>
<p><em><span ><strong>Toi qui es né et formé à Grenoble, connais-tu certains gars de l’équipe actuelle ?</strong></span></em></p>
<p><strong><span >Arnaud Faure :</span></strong> « Oui je connais pas mal de gars à Anglet. Tout d&rsquo;abord, je connais très bien Mathieu (Pons) depuis extrêmement longtemps, on a fait toutes nos gammes chez les jeunes de U très petit (rires) jusqu&rsquo;en professionnel, avant qu&rsquo;il ne parte à Anglet. Je connais aussi Arross (Nicolas Arrossamena) avec qui j&rsquo;ai joué à Épinal. Je connais bien Mo (Maurin Bouvet) et Kaza (Fabien Kazarine), on a joué tous les trois en Équipe de France, on s&rsquo;entend très bien. Évidemment, je connais très bien Victor (Ranger), car nous sommes dans la même école située sur Grenoble, et puis nous avons évolué ensemble à Gap en 2020 ».</p>
<p><em><strong>On te place dans la catégorie des défenseurs purs et propres sur la glace, comment décrirais-tu ton style de jeu pour ceux qui ne te connaissent pas ?</strong></em></p>
<p><strong><span >Arnaud Faure :</span></strong> « Je suis plutôt un défenseur défensif, bon en désavantage numérique notamment, c&rsquo;est mon rôle et c&rsquo;est ce que j&rsquo;aime faire aussi. Je ne fais pas trop de vague, on ne me voit pas trop durant les matchs, c&rsquo;est plutôt de la rigueur défensive et de la simplicité bien exécuter. Certes, ça va moins crever l&rsquo;écran qu&rsquo;un défenseur offensif qui mettra plus de points, mais c&rsquo;est tout aussi important d&rsquo;assumer ce rôle défensif et de faire partie de cet équilibre derrière. Mon but est de continuer de développer mes forces, et de travailler sur les points qui ne sont pas innés pour moi afin de passer des paliers avec Anglet et devenir encore plus complet. »</p>
<p><em><strong>Les affrontements face à Gap ont souvent été accrochés à Anglet, si on met de côté la première journée la saison dernière, est-ce difficile de venir jouer à la Barre ?</strong></em></p>
<p><strong><span >Arnaud Faure :</span></strong> « Oui ça a toujours été difficile de jouer à Anglet, peu importent les équipes d&rsquo;ailleurs, ce sont des matchs toujours complexes à aborder mentalement et physiquement. On sait que ça va être un gros combat, que ça frappe fort, puis le fait que ce soit une petite glace fait que ça diminue le temps et l&rsquo;espace, on a toujours quelqu&rsquo;un sur le dos. Ça me fait d&rsquo;ailleurs penser un peu à l&rsquo;ancienne patinoire d&rsquo;Angers, celle du Haras, c&rsquo;était toujours compliqué et redouté d&rsquo;y jouer. Voilà, ce sera notre mission avec les gars, de ne jamais rendre la tâche facile aux équipes adverses à la Barre devant nos supporteurs. Je pense d&rsquo;ailleurs, que ce sera encore plus difficile de venir jouer à la Barre la saison prochaine, car on sera présent physiquement, on ne lâchera pas le morceau jusqu&rsquo;au bout ».</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/le-defenseur-arnaud-faure-etait-l-un-des-joueurs-cadres-des-rapaces-de-gap-archives-photo-le-dl-vincent-ollivier-1682104877-300x223.jpg" alt="" width="455" height="338" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/le-defenseur-arnaud-faure-etait-l-un-des-joueurs-cadres-des-rapaces-de-gap-archives-photo-le-dl-vincent-ollivier-1682104877-300x223.jpg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/le-defenseur-arnaud-faure-etait-l-un-des-joueurs-cadres-des-rapaces-de-gap-archives-photo-le-dl-vincent-ollivier-1682104877-1024x762.jpg 1024w, https://pro.hormadi.fr/wp-content/uploads/2023/06/le-defenseur-arnaud-faure-etait-l-un-des-joueurs-cadres-des-rapaces-de-gap-archives-photo-le-dl-vincent-ollivier-1682104877-768x571.jpg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/le-defenseur-arnaud-faure-etait-l-un-des-joueurs-cadres-des-rapaces-de-gap-archives-photo-le-dl-vincent-ollivier-1682104877-128x95.jpg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/le-defenseur-arnaud-faure-etait-l-un-des-joueurs-cadres-des-rapaces-de-gap-archives-photo-le-dl-vincent-ollivier-1682104877-32x24.jpg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/le-defenseur-arnaud-faure-etait-l-un-des-joueurs-cadres-des-rapaces-de-gap-archives-photo-le-dl-vincent-ollivier-1682104877-98x73.jpg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/le-defenseur-arnaud-faure-etait-l-un-des-joueurs-cadres-des-rapaces-de-gap-archives-photo-le-dl-vincent-ollivier-1682104877-160x120.jpg 160w, https://pro.hormadi.fr/wp-content/uploads/2023/06/le-defenseur-arnaud-faure-etait-l-un-des-joueurs-cadres-des-rapaces-de-gap-archives-photo-le-dl-vincent-ollivier-1682104877.jpg 1293w" sizes="auto, (max-width: 455px) 100vw, 455px" />Tu as donc déjà pu découvrir le coin, quels sont tes souvenirs de tes rapides passages au Pays Basque ?</strong></em></p>
<p><strong><span >Arnaud Faure :</span></strong> « Je n&rsquo;ai pas tant de souvenirs que ça hormis la patinoire et ses alentours, mais ce sera l&rsquo;occasion de découvrir cette magnifique région et de constater la qualité de vie, qui est incroyable, j&rsquo;en suis convaincu. J&rsquo;ai que des échos positifs, sur l&rsquo;hospitalité, la convivialité, cette chaleur humaine et l&rsquo;ambiance. Peut-être un peu moins sur le temps qui change du tout au tout (rires), mais c&rsquo;est logique nous sommes en bord d&rsquo;océan. »</p>
<p><em><strong>On te surnomme apparemment « la barre de fer », peux-tu nous expliquer pourquoi ?</strong></em></p>
<p><span ><strong>Arnaud Faure :</strong> </span>« Celle-là, il faudra demander à Victor (Ranger), il s&rsquo;est mis ça dans la tête tout seul (rires). »</p>
<p><em><strong>On va parler d’objectifs pour la saison prochaine, quels sont les tiens d’un point de vue individuel, tes axes d’amélioration ainsi que tes ambitions collectives ?</strong></em></p>
<p><strong><span >Arnaud Faure :</span></strong> « Je vais commencer par parler d&rsquo;objectifs collectifs, on ne va pas se le cacher, c&rsquo;est de disputer les play-offs forcément, rentrer dans le top 8. Alors, est-ce que le top 8 est atteignable ? Oui bien entendu. Est-ce qu&rsquo;on ne pourrait pas aller gratter au-dessus ? On peut toujours, je trouve que le recrutement est de qualité, même très bon. Mais ne nous enflammons pas, construisons d&rsquo;abord un noyau solide, qui nous servira sur le long terme et autour duquel il faudra bâtir. Et puis je vais rajouter, pourquoi pas un beau parcours de Coupe de France, qui sait, ce serait formidable. Après individuellement parlant, faire une saison solide défensivement, continuer de me développer dans d&rsquo;autres secteurs du jeu. Mettre des points, ce n&rsquo;est pas mon rôle, juste se présenter à chaque match avec la manière, le reste c&rsquo;est du bonus. »</p>
<p><em><strong><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/379-FAUREarnaud-GAP-20211105.jpg-300x200.webp" alt="" width="336" height="224" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/379-FAUREarnaud-GAP-20211105.jpg-300x200.webp 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/379-FAUREarnaud-GAP-20211105.jpg-128x86.webp 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/379-FAUREarnaud-GAP-20211105.jpg-32x21.webp 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/379-FAUREarnaud-GAP-20211105.jpg-360x240.webp 360w, https://pro.hormadi.fr/wp-content/uploads/2023/06/379-FAUREarnaud-GAP-20211105.jpg-98x65.webp 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/379-FAUREarnaud-GAP-20211105.jpg.webp 702w" sizes="auto, (max-width: 336px) 100vw, 336px" />Pour finir, as-tu quelques mots pour nos supporteurs alors que la saison approche à grands pas ?</strong></em></p>
<p><strong><span >Arnaud Faure :</span></strong> « Je suis très heureux de rejoindre les rangs de l&rsquo;Hormadi, j&rsquo;ai vraiment hâte que la saison démarre et de pouvoir vous rencontrer et discuter avec vous. Que l&rsquo;on fasse trembler le chaudron de la Barre tout au long de l&rsquo;année afin d&rsquo;attaquer au mieux les moments importants. »</p>
<p><span >Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</span></p>
<p>&nbsp;</p>
', 'Interview', '/images/news/arnaud-faure-ou-lrsquohomme-de-lrsquoombre-devenu-indispensable.jpeg', true, '1687790738000', '1774831612153', '1774833441761');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'maurin-bouvet-lrsquoambiance-est-electrique-avec-une-pointe-de-chauvinisme-si-mes-souvenirs-sont-bons-rires', 'Maurin BOUVET : « L&rsquo;ambiance est électrique, avec une pointe de chauvinisme si mes souvenirs sont bons (rires) »', 'Maurin Bouvet : « L&rsquo;ambiance est électrique, avec une pointe de chauvinisme si mes souvenirs sont bons (rires) » Du haut de ses 44 sélections en Équipe de France, le centre international tricolore, Maurin Bouvet, a fait le choix de quitter l&rsquo;une des armadas de la Ligue Magnus, les Ducs d', '<h3>Maurin Bouvet : « L&rsquo;ambiance est électrique, avec une pointe de chauvinisme si mes souvenirs sont bons (rires) »</h3>
<p>Du haut de ses 44 sélections en Équipe de France, le centre international tricolore, Maurin Bouvet, a fait le choix de quitter l&rsquo;une des armadas de la Ligue Magnus, les Ducs d&rsquo;Angers, afin de rejoindre le projet angloy la saison prochaine. Ce dernier, se dit prêt à « tout faire pour être à la hauteur des attentes ». Entretien exclusif avec le futur numéro 51 basque.</p>
<p><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.32.38-261x300.jpeg" alt="" width="338" height="389" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.32.38-261x300.jpeg 261w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.32.38-889x1024.jpeg 889w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.32.38-768x884.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.32.38-111x128.jpeg 111w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.32.38-28x32.jpeg 28w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.32.38-85x98.jpeg 85w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.32.38.jpeg 1091w" sizes="auto, (max-width: 338px) 100vw, 338px" /></p>
<blockquote><p><em><strong>Tu sors d’une saison pleine chez les Ducs d’Angers, avec pas loin de 70 matchs au compteur toutes compétitions confondues, dont une finale de Continental Cup, comment sors-tu de cet exercice 2022-2023 relativement long ?</strong></em></p></blockquote>
<p><span ><strong>Maurin Bouvet :</strong></span> « La saison passée fut très intense de par le calendrier sportif chargé et les évènements extra-sportifs. La Continental Cup (seconde coupe d&rsquo;Europe) nous a ajouté 9 matchs supplémentaires et a densifié notre programme, 3 tournois de 3 matchs en l&rsquo;espace de 3 jours. L&rsquo;expérience était vraiment géniale et j&rsquo;en garderai de bons souvenirs. Pour revenir à ta question, chaque saison a son lot d&rsquo;émotions positives et négatives. À la fin de saison, je prends toujours 3 semaines de break afin de recharger les batteries physiquement et mentalement, avant de repartir me préparer. »</p>
<p><em><strong>Qu’est-ce qui t’a convaincu de rejoindre l’Hormadi ?</strong></em></p>
<p><span ><strong>Maurin Bouvet :</strong> </span>« Avant de signer, j&rsquo;ai pu échanger avec différents membres du staff ainsi que certains joueurs sur le fonctionnement de l&rsquo;équipe et du club en général. Le courant est de suite très bien passé, et puis le challenge est excitant. Mes responsabilités devraient être plus importantes que l&rsquo;année passée, je vais donc tout faire pour être à la hauteur de ces attentes. »</p>
<p><em><strong>Tu parles de responsabilités justement, c&rsquo;est aussi cela qui t&rsquo;a poussé à rejoindre Anglet, avec cette assurance d&rsquo;avoir un rôle plus important au centre de l’offensive angloye par rapport à ce que tu connaissais à Angers la saison dernière ?</strong></em></p>
<p><span ><strong>Maurin Bouvet :</strong></span> « Oui complètement ! J&rsquo;avais cette forte envie de jouer les moments importants comme j&rsquo;ai pu déjà le faire par le passé. D&rsquo;être sur la glace quand il faut aller chercher un but ou au contraire, défendre une avance dans les dernières secondes d&rsquo;une partie, c&rsquo;est ce que j&rsquo;aime. »</p>
<p><em><strong>Tu connais très bien Fabien Kazarine alias « Kaza », que peux-tu nous dire sur votre relation ?</strong></em></p>
<p>&nbsp;</p>
<p><span ><strong>Maurin Bouvet :</strong></span> « Ahhh Kaza ! Avec Kaza, ça fait plus de 15 ans que l&rsquo;on se connaît. On s&rsquo;est construit ensemble, que ce soit à l&rsquo;école ou sur la glace, nous n&rsquo;étions jamais très loin. Nous avons une amitié forte, il sera d&rsquo;ailleurs mon témoin de mariage cet été, je n&rsquo;ai pas été capable de trouver mieux que ça (rires).</p>
<blockquote><p><span ><em><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/Mo-et-Kaza-1-300x248.jpeg" alt="" width="312" height="258" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/Mo-et-Kaza-1-300x248.jpeg 300w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Mo-et-Kaza-1-768x634.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Mo-et-Kaza-1-128x106.jpeg 128w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Mo-et-Kaza-1-32x26.jpeg 32w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Mo-et-Kaza-1-98x81.jpeg 98w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Mo-et-Kaza-1-555x460.jpeg 555w, https://pro.hormadi.fr/wp-content/uploads/2023/06/Mo-et-Kaza-1.jpeg 945w" sizes="auto, (max-width: 312px) 100vw, 312px" /></em></span></p>
<p><span ><em>« Il sera d&rsquo;ailleurs mon témoin de mariage cet été, je n&rsquo;ai pas été capable de trouver mieux que ça (rires) »</em></span></p></blockquote>
<p>Je suis très content que l&rsquo;on puisse rejouer dans la même équipe, sous les mêmes couleurs et pouvoir performer ensemble. Je pourrais en parler pendant des heures, mais j&rsquo;ai des choses à faire aujourd&rsquo;hui (rires). »</p>
<p>&nbsp;</p>
<p><em><strong>Comment définirais-tu le style de joueur que tu es, plutôt un centre two-way ?</strong></em></p>
<p><strong><span >Maurin Bouvet : </span></strong><span ><span >« Oui, two-way, ça définit assez bien mon profil. Je suis un joueur assez complet dans les deux sens de la glace, capable d&rsquo;évoluer au centre comme à l&rsquo;aile. Je suis altruiste et donc j&rsquo;aime échanger le palet souvent et trouver des décalages. Bien sûr, lorsque l&rsquo;opportunité se présente à moi, je ne me ferais pas prier pour marquer des buts ! »</span></span></p>
<p><em><strong>Tu as déjà foulé la glace de la Barre sous d’autres couleurs, quelles ont été tes impressions sur cette patinoire, son ambiance et ses alentours ?</strong></em></p>
<p><strong><span ><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.29.14.jpeg" alt="" width="285" height="357" />Maurin Bouvet :</span></strong> « <span >La taille de la glace ! C&rsquo;est la première chose que je dirais, quand on est l&rsquo;équipe visiteuse et que l&rsquo;on vient jouer ici à la Barre, les repères ne sont pas du tout les mêmes, ce qui rend l&rsquo;adaptation très difficile. L&rsquo;ambiance est électrique, avec une pointe de chauvinisme si mes souvenirs sont bons (rires).</span></p>
<blockquote><p><span ><em>« L&rsquo;ambiance est électrique, avec une pointe de chauvinisme si mes souvenirs sont bons »</em></span></p></blockquote>
<p>Et puis, comment ne pas parler de la plage quand on fait référence à la Barre. Quand je suis venu jouer ici, que ce soit avec Angers, Rouen, ou même Gap, j&rsquo;avais pour habitude de marcher prendre l&rsquo;air en regardant l&rsquo;océan&#8230; je sais, je suis poétique (rires). »</p>
<blockquote><p><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.36.50-241x300.jpeg" alt="" width="314" height="391" srcset="https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.36.50-241x300.jpeg 241w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.36.50-823x1024.jpeg 823w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.36.50-768x955.jpeg 768w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.36.50-103x128.jpeg 103w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.36.50-26x32.jpeg 26w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.36.50-85x105.jpeg 85w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.36.50-79x98.jpeg 79w, https://pro.hormadi.fr/wp-content/uploads/2023/06/WhatsApp-Image-2023-05-09-at-15.36.50.jpeg 1106w" sizes="auto, (max-width: 314px) 100vw, 314px" /></p></blockquote>
<p><em><strong>L’effectif est presque au complet, quel avis portes-tu sur ce dernier à l’heure d’aujourd’hui ?</strong></em></p>
<p><strong><span >Maurin Bouvet :</span></strong> « <span >Il y a eu pas mal de changements cette intersaison dans l&rsquo;équipe. Il y a deux ou trois têtes qui me sont familières. Je n&rsquo;ai aucun doute que l&rsquo;ambiance sera bonne dans le vestiaire et sur le glaçon. En ce qui concerne mon avis, il compte peu. C&rsquo;est surtout ce que nous produirons sur la glace et de quelle manière nous allons nous comporter en tant que collectif qui comptera ! »</span></p>
<p><em><strong>Quels sont tes objectifs personnels et collectifs pour la saison à venir ?</strong></em></p>
<p><span ><strong>Maurin Bouvet :</strong></span> « <span >Mes objectifs personnels sont de performer évidemment. D&rsquo;aider l&rsquo;équipe à gagner le plus de matchs possible. Les objectifs collectifs s&rsquo;alignent avec les miens : viser une qualification en play-offs. Il faut aussi se faire plaisir, c&rsquo;est avant tout ça le hockey sur glace, et puis bien sûr, faire plaisir et rendre fiers nos supporteurs. Et cela passe par des bons résultats. »</span></p>
<p><em><strong>Enfin, as-tu un petit mot pour les supporteurs angloys qui s&#8217;empressent de te découvrir et de te rencontrer ?</strong></em></p>
<p><span ><strong>Maurin Bouvet :</strong></span> « <span >J&rsquo;ai vraiment hâte de commencer la saison et d&rsquo;aller à votre rencontre ! Profitez tous bien de votre été, faites attention à vous et on se donne rendez-vous à la Barre dans quelques semaines. »</span></p>
<blockquote><p><span >Recueilli par Matthieu Lalanne et Anaïs Domengie&#8230;</span></p></blockquote>
<p>&nbsp;</p>
', 'Interview', '/images/news/maurin-bouvet-lrsquoambiance-est-electrique-avec-une-pointe-de-chauvinisme-si-me.jpg', true, '1687273225000', '1774831613132', '1774833441762');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-cole-thiessen', 'Arrivée de Cole THIESSEN', '[vc_row][vc_column width= »1/2&Prime;][vc_column_text]Un défenseur canadien peut en cacher un autre, aujourd’hui nous vous annonçons l’arrivée du défenseur offensif, Cole THIESSEN, qui vient compléter un peu plus l’arrière-garde angloye la saison prochaine. Un beau cadeau d’anniversaire puisque ce d', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_column_text]Un défenseur canadien peut en cacher un autre, aujourd’hui nous vous annonçons l’arrivée du défenseur offensif, <strong>Cole THIESSEN</strong>, qui vient compléter un peu plus l’arrière-garde angloye la saison prochaine. Un beau cadeau d’anniversaire puisque ce dernier, fêtera ses 25 ans ce dimanche.<span >🥳</span></p>
<p>En provenance du championnat universitaire canadien d’USports lui aussi, de l’Université de Brock plus précisément au sein de laquelle il évoluait depuis 4 saisons. Cole était le défenseur le plus productif de sa formation des Badgers de Brock au cours des deux dernières années, avec notamment 22 points en 31 matchs saison régulière et play-offs confondus lors du dernier exercice, Cole possède un petit gabarit (1.73m / 75kg). Ayant une grosse qualité de patinage et de vitesse, notre nouveau défenseur droitier, originaire de l’Ontario également, aime soutenir l’offensive et se montre à son aise grâce à son petit gabarit sur les situations d’avantage numérique.</p>
<p>C’est donc toute une recrue qui s’en vient au club, nous sommes très heureux de pouvoir l’accueillir en terre basque pour sa première expérience en Europe. Et bien évidemment, nous avons très hâte de le voir fouler notre glace de la Barre au mois de septembre.</p>
<p>WELCOME HOME COLE[/vc_column_text][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16229&Prime; img_size= »large » alignment= »center »][vc_btn title= »Elite Prospect » style= »3d » color= »primary » align= »center » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F268694%2Fcole-thiessen|target:_blank »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyNjg2OTQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjMxMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBBJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-cole-thiessen.jpeg', true, '1686996023000', '1774831615322', '1774833441762');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-sam-dunn', 'Arrivée de Sam DUNN', '[vc_row][vc_column width= »1/2&Prime;][vc_column_text]C’est au tour d’un robuste défenseur canadien de poser ses patins et ses crosses à la Barre, Sam DUNN, rejoint les rangs de l’Anglet Hormadi Pays Basque à la rentrée prochaine. Originaire de l’Ontario, ce grand gaillard au physique imposant sur l', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_column_text]C’est au tour d’un robuste défenseur canadien de poser ses patins et ses crosses à la Barre, <strong>Sam DUNN</strong>, rejoint les rangs de l’Anglet Hormadi Pays Basque à la rentrée prochaine.</p>
<p>Originaire de l’Ontario, ce grand gaillard au physique imposant sur la glace (1.88m / 98kg), arrive à la Barre extrêmement déterminé. Sam débarque de l’ECHL, des Lions des Trois-Rivières du Québec, l’un des deux clubs affiliés de Montréal, où il y a terminé la saison avec neuf matchs au compteur.</p>
<p>Effectuant son junior au sein de la prestigieuse LHJMQ sous les couleurs des Remparts du Québec, Sam avait eu la chance d’être invité au camp de développement des Blue Jackets de Columbus en 2018, une belle expérience pour lui à l’époque. Par la suite, il poursuivait son chemin en USports, à l’Université de Saint-Mary&rsquo;s, aux côtés de notre nouvel attaquant Keith Getson. Les deux hommes se connaissent parfaitement puisqu’ils ont évolué ensemble au cours des quatre dernières années. Alors que Keith était le capitaine, Sam lui, était son assistant capitaine à Saint- Mary&rsquo;s.</p>
<p>Défenseur bon dans les deux sens de la glace, nous sommes ravis de pouvoir l’accueillir au club. Nous lui souhaitons toutes et tous, la bienvenue ainsi qu’un bel été. Sam vous a d’ailleurs laissé quelques mots, dans un français parfait, on peut le dire !<span >😁</span></p>
<p>WELCOME HOME SAM[/vc_column_text][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16226&Prime; img_size= »large » alignment= »center »][vc_btn title= »Elite Prospect » style= »3d » color= »primary » align= »center » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F249307%2Fsam-dunn|target:_blank »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyNDkzMDclMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQwMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-sam-dunn.jpeg', true, '1686841241000', '1774831617660', '1774833441762');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-michael-young', 'Arrivée de Michael YOUNG', '[vc_row][vc_column width= »1/2&Prime;][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine. Il est lui aussi Américain, le robuste défenseur droitier et capitaine de l’Université de Yale en NCAA, Michael YOUNG, rejoint les rangs de Pierrick ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine.</p>
<p>Il est lui aussi Américain, le robuste défenseur droitier et capitaine de l’Université de Yale en NCAA, <strong>Michael YOUNG</strong>, rejoint les rangs de Pierrick Rézard et Mathieu Cyr.</p>
<p>Âgé de 24 ans, Michael alias « Mike », évolue depuis 4 ans au sein de la meilleure ligue universitaire américaine, la NCAA, à l’instar de nos récentes recrues, Colin Doyle, Hugo Reinhardt, Dylan St. Cyr ou encore Craig Puffer, eux aussi passés par là. Solide capitaine des Bulldogs de Yale cette saison, Michael est un défenseur au physique imposant (1.85m / 95kg), qui couvre parfaitement sa ligne bleue. Ses qualités premières sont évidemment de défendre ardemment ses filets, en apportant un certain équilibre à sa défensive. Michael aime jouer dur en étant très compétitif, tout en étant capable de tirer de la pointe.</p>
<p>Avec un état d’esprit d’équipe irréprochable et un dévouement sans compter, nous sommes extrêmement heureux de pouvoir l’accueillir au club. Nous lui souhaitons toutes et tous, la bienvenue à l’Hormadi ainsi qu’un très bel été.</p>
<p>WELCOME HOME MICHAEL[/vc_column_text][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16218&Prime; img_size= »large » alignment= »center »][vc_btn title= »Elite Prospect » style= »3d » color= »primary » align= »center » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F270506%2Fmichael-young|target:_blank »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyNzA1MDYlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjMxMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-michael-young.jpeg', true, '1686322859000', '1774831624533', '1774833441763');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-austin-glover', 'Départ de Austin GLOVER', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy au mois de septembre, AUSTIN GLOVER, n’est pas conservé par l’Anglet Hormadi Pays Basque. Arrivé au mois d’octobre en urgence afin de pallier plusieurs blessures notamment, le centre can', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy au mois de septembre, <strong>AUSTIN GLOVER</strong>, n’est pas conservé par l’Anglet Hormadi Pays Basque.</p>
<p>Arrivé au mois d’octobre en urgence afin de pallier plusieurs blessures notamment, le centre canadien aura effectué 42 parties pour un total de 28 points toutes compétitions confondues sous nos couleurs cette saison.</p>
<p>Nous le remercions pour son investissement et nous lui souhaitons bonne chance pour la suite de sa carrière.[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F120630%2Faustin-glover|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16184&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxMjA2MzAlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM4NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-austin-glover.jpeg', true, '1686150024000', '1774831628589', '1774833441763');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-craig-puffer', 'Arrivée de Craig PUFFER', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]C’est à coup sûr une redoutable arme offensive qui débarque à la Barre, l’ailier gauche américain, Craig PUFFER, rejoint l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine. Le natif de Greenwich aux États-Unis, ar', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]C’est à coup sûr une redoutable arme offensive qui débarque à la Barre, l’ailier gauche américain,<strong> Craig PUFFER</strong>, rejoint l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine.</p>
<p>Le natif de Greenwich aux États-Unis, arrive en provenance du championnat britannique d’EIHL, et plus précisément des Panthers de Nottingham où il y a disputé 32 matchs cette saison. Avant cette expérience de l’autre côté de la Manche, Craig avait affolé les compteurs au Danemark, dans le championnat élite de la Metal Ligaen, avec 104 points en 115 matchs de saison régulière et playoffs confondus sous les couleurs d’Esbjerg. Un an plus tôt, en 2020, il avait également fait le bonheur du club de Manglerud en Norvège, inscrivant 30 points en 29 matchs.</p>
<p>Passé furtivement par l’ECHL avant de s’expatrier en Europe, Craig est un ailier au petit gabarit, très vif et excellent finisseur, possédant un redoutable tir du poignet. Très à l’aise aussi sur les situations d’avantage numérique, notre nouvel attaquant brisera sans aucun doute la glace à plusieurs reprises sous notre chandail lors du prochain exercice.</p>
<p>L’ensemble du club est extrêmement satisfait de pouvoir compter sur ses services dès le mois de septembre. Nous lui souhaitons toutes et tous, la bienvenue à l’Hormadi ainsi qu’un très bel été</p>
<p>WELCOME HOME CRAIG[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F256641%2Fcraig-puffer|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16178&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyNTY2NDElMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM0MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-craig-puffer.jpeg', true, '1685977230000', '1774831629558', '1774833441763');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-hugo-reinhardt', 'Arrivée de Hugo REINHARDT', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine. Passé notamment par l’excellente formation suédoise de Frölunda HC lors de son junior, le centre suédois de 27 ans, Hugo REINHARDT, q', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine.</p>
<p>Passé notamment par l’excellente formation suédoise de Frölunda HC lors de son junior, le centre suédois de 27 ans, <strong>Hugo REINHARDT</strong>, quitte le froid nordique afin de rejoindre la Barre à la rentrée prochaine.</p>
<p>Après avoir percé dans les catégories de jeunes de U16 à U20 au sein du plus grand club Suédois, le Frölunda HC, Hugo s’était expatrié sur le continent américain à l’âge de 20 ans, afin d’évoluer dans le championnat universitaire NCAA, sous les couleurs de l’American International College. Il y passera quatre saisons en tant qu’assistant capitaine puis capitaine lors de la dernière saison, avec au compteur 76 points en 131 matchs et un trophée de la division Atlantique NCAA en 2019. Avant de rentrer au pays en 2020 en HockeyAllsvenskan, le second échelon suédois. Une réussite, puisqu’avec le club de Timrå IK, Hugo sera couronné en remportant le championnat en 2021 et par la même occasion, promu en SHL, l’élite du hockey suédois.</p>
<p>Cette saison, il aura porté à 43 reprises, les couleurs des Stars de Dundee en EIHL, le championnat britannique, en tant qu’assistant capitaine également. Hugo est un centre physique, plein d’énergie qui ne calcule pas les efforts. Bon passeur et bon dans les deux sens de la glace notamment, l’originaire de Kungsbacka adore faire le sale boulot autour du filet adverse afin d’être présent aux déviations ou aux rebonds.</p>
<p>L’ensemble du club est ravi de pouvoir compter sur lui pour le prochain exercice, en attendant, nous lui souhaitons la bienvenue et un bel été.</p>
<p>ONGI ETORRI HUGO</p>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F146824%2Fhugo-reinhardt|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16152&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxNDY4MjQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM4NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-hugo-reinhardt.jpeg', true, '1685613601000', '1774831632074', '1774833441764');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-maxime-loubier', 'Départ de Maxime LOUBIER', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, le jeune gardien Maxime LOUBIER, prend son envol afin de s’orienter vers un nouveau challenge en D2. Après avoir réalisé quasiment toute sa formation à l’Anglet Horm', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, le jeune gardien <strong>Maxime LOUBIER</strong>, prend son envol afin de s’orienter vers un nouveau challenge en D2.</p>
<p>Après avoir réalisé quasiment toute sa formation à l’Anglet Hormadi Pays Basque, Maxime a eu l’honneur de faire le saut dans le grand bain cette saison en Synerglace Ligue Magnus avec deux apparitions face à Grenoble pour son baptême du feu, puis lors du derby aquitain à Bordeaux.</p>
<p>Le club tient à saluer ses performances lorsque le staff avait fait appel à lui. Nous le remercions et nous lui souhaitons bonne chance au sein de sa future équipe, en espérant le voir représenter haut et fort la formation angloye.</p>
<p>MILESKER MAXIME[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F559845%2Fmaxime-loubier|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16159&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q1NTk4NDUlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjMxMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-maxime-loubier.jpeg', true, '1685527253000', '1774831634471', '1774833441764');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-vincent-deslauriers', 'Arrivée de Vincent DESLAURIERS', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine. Pur Québécois de souche, l’ailier droit de 26 ans et capitaine de l’Université de Moncton en USports, Vincent DESLAURIERS, quitte la ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine.</p>
<p>Pur Québécois de souche, l’ailier droit de 26 ans et capitaine de l’Université de Moncton en USports, <strong>Vincent DESLAURIERS</strong>, quitte la belle province et le Canada, afin de rejoindre la Barre en septembre.</p>
<p>Ayant effectué tout son junior lui aussi au sein de la reconnue LHJMQ sous les couleurs du Phoenix de Sherbrooke puis du Drakkar de Baie-Comeau, Vincent a ensuite réalisé l’entièreté de son cursus universitaire comme tout bon joueur canadien, en USports. Durant cinq saisons, notre nouvel attaquant, aura porté les couleurs de l’Université des Aigles Bleus de Moncton, avec la lettre « C » sur son chandail, puisqu’il en était le solide capitaine. Un leader aussi bien en dehors, que sur la glace, car avec 122 points en 150 rencontres d’USports au cours de ces cinq années, Vincent était l’un des atouts majeurs de sa formation de Moncton.</p>
<p>Vincent a également eu l’occasion cette saison, en janvier dernier, d’être parmi la sélection « USports All-Stars ». Cette dernière, réunissait les meilleurs joueurs canadiens de la ligue afin d’affronter par deux fois lors de matchs amicaux, Connor Bedard et sa Team Canada U20 en marge de leur camp de préparation aux championnats du monde junior.</p>
<p>Ailier droit de petite taille et trapu, le Québécois débarque à la Barre pour apporter toutes ses qualités de patinage et de franc-tireur. Nous sommes donc extrêmement ravis de l’accueillir au club, et nous avons hâte de le voir s’exprimer sous notre tunique basque.</p>
<p>ONGI ETORRI VINCENT[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F151120%2Fvincent-deslauriers|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16137&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxNTExMjAlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM0MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-vincent-deslauriers.jpeg', true, '1685372423000', '1774831635134', '1774833441764');
