INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-robin-lamboley', 'Départ de Robin LAMBOLEY', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, l’attaquant Robin Lamboley, n’est pas conservé par le club. Après son premier passage au club entre 2018 et 2020, Lambols était revenu sur la côte basque l’été derni', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, l’attaquant Robin Lamboley, n’est pas conservé par le club.</p>
<p>Après son premier passage au club entre 2018 et 2020, Lambols était revenu sur la côte basque l’été dernier. Pas épargné non plus par quelques pépins physiques, notre numéro 13 aura tout de même disputé 41 matchs toutes compétitions confondues pour un total de 7 assistances cette saison sous les couleurs angloyes.</p>
<p>Nous le remercions pour son sérieux tout au long de l’année, et nous lui souhaitons évidemment bonne chance dans ses projets futurs.</p>
<p>MILESKER ROBIN[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F163201%2Frobin-lamboley|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16112&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxNjMyMDElMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjU2NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-robin-lamboley.jpeg', true, '1685181608000', '1774831636536', '1774833441768');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-colin-doyle', 'Arrivée de Colin DOYLE', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine. Le centre canadien de 25 ans, Colin DOYLE, traverse l’Atlantique pour sa première expérience en Europe, chez nous, à l’Hormadi. Colin', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine.</p>
<p>Le centre canadien de 25 ans, <strong>Colin DOYLE</strong>, traverse l’Atlantique pour sa première expérience en Europe, chez nous, à l’Hormadi.</p>
<p>Colin débarque tout droit d’ECHL, le troisième échelon nord-américain, où il a terminé la saison. Avec 2 buts et 1 assistance en 7 matchs sous l’uniforme des Savannah Ghost Pirates.<br />
Avant cela, l’originaire de Campbellford, évoluait depuis cinq ans dans le club universitaire d’Alaska-Fairbanks en NCAA, le meilleur championnat universitaire américain.</p>
<p>Gros patineur et travailleur, Colin est principalement réputé pour son jeu défensif et ses qualités de tueur de pénalités notamment, mais son flair aux engagements, est aussi l’une de ses forces. C’est donc un choix très visé par Pierrick Rézard et son staff, afin d’apporter de la profondeur à l’offensive basque tout en accompagnant nos jeunes angloys sur des trios plus défensifs.</p>
<p>Nous sommes très heureux de pouvoir l’accueillir à la Barre, et nous lui souhaitons toutes et tous, la bienvenue au club pour sa première expérience en dehors du continent nord-américain.</p>
<p>WELCOME HOME COLIN[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F268372%2Fcolin-doyle|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16111&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyNjgzNzIlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjMxMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-colin-doyle.jpeg', true, '1685026814000', '1774831636784', '1774833441768');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-anton-vasilyev', 'Départ de Anton VASILYEV', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]C’est un nouveau départ aujourd’hui, il ne fera plus partie de l’effectif angloy la saison prochaine, notre top scorer, ANTON VASILYEV, quitte l’Anglet Hormadi Pays Basque après deux saisons à la Barre. Arrivé en décembre 2021, An', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]C’est un nouveau départ aujourd’hui, il ne fera plus partie de l’effectif angloy la saison prochaine, notre top scorer, ANTON VASILYEV, quitte l’Anglet Hormadi Pays Basque après deux saisons à la Barre.</p>
<p>Arrivé en décembre 2021, Anton avait tout de suite marqué les esprits de par son talent offensif. Auteur de 39 points en 41 matchs la saison dernière, il aura gravé de son emprunte les partisans de la Barre durant son passage.</p>
<p>Nous le remercions pour ces deux saisons, et nous lui souhaitons bonne chance pour la suite de sa carrière.</p>
<p>MILESKER ANTON[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F334202%2Fanton-vasilyev|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16113&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzMzQyMDIlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQzMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-anton-vasilyev.jpeg', true, '1684940421000', '1774831637073', '1774833441768');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-alexander-nikulin', 'Départ de Alexander NIKULIN', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, notre vétéran russe de 37 ans, ALEXANDER NIKULIN, n’évoluera plus sous nos couleurs en septembre. Une saison compliquée pour Niki, ayant subi une lourde blessure au ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, notre vétéran russe de 37 ans, <strong>ALEXANDER NIKULIN</strong>, n’évoluera plus sous nos couleurs en septembre.</p>
<p>Une saison compliquée pour Niki, ayant subi une lourde blessure au début du mois d’octobre, l’ex-NHLers n’a pas pu prendre part à la compétition durant quatre mois. Ce dernier avait inscrit 6 points en 7 matchs avant sa blessure, avant de revenir sur la glace à la fin du mois de janvier pour le sprint final. Finalement, il terminera cet épisode 2022-2023 avec un total de 9 points en 15 matchs au compteur.</p>
<p>Nous le remercions infiniment pour son état d’esprit irréprochable ainsi que toute l’expérience qu’il a apporté au groupe et nous lui souhaitons bon courage dans projets futurs.</p>
<p>MILESKER ALEXANDER[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F12427%2Falexander-nikulin|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16107&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxMjQyNyUyMiUyMHdpZHRoJTNEJTIyMTAwJTI1JTIyJTIwaGVpZ2h0JTNEJTIyNjcwJTIyJTIwc2Nyb2xsaW5nJTNEJTIybm8lMjIlMjBmcmFtZWJvcmRlciUzRCUyMjAlMjIlM0UlM0MlMkZpZnJhbWUlM0UlMEE=[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-alexander-nikulin.jpeg', true, '1684767653000', '1774831637395', '1774833441769');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-bastien-zago', 'Départ de Bastien ZAGO', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, Bastien ZAGO, arrivé il y a un an à la Barre, n’est pas conservé par le club. Malgré quelques pépins physiques lors de cet exercice, Bastien aura disputé 41 matchs t', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, <strong>Bastien ZAGO</strong>, arrivé il y a un an à la Barre, n’est pas conservé par le club.</p>
<p>Malgré quelques pépins physiques lors de cet exercice, Bastien aura disputé 41 matchs toutes compétitions confondues cette saison, avec un total de 9 points sous nos couleurs. Auteur notamment d’une performance notable durant la poule de maintien, nul doute qu’il saura rebondir dans l’hexagone au sein d’une nouvelle formation.</p>
<p>Nous le remercions pour son sérieux et son application tout au long de la saison, et nous lui souhaitons également bonne chance dans ses projets futurs.</p>
<p>MILESKER BASTIEN[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F358976%2Fbastien-zago|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16095&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]aHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGcGxheWVyJTJGMzU4OTc2JTJGYmFzdGllbi16YWdvJTJGZW1iZWQtc3RhdHM=[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-bastien-zago.jpeg', true, '1684490448000', '1774831637828', '1774833441769');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-keith-getson', 'Arrivée de Keith GETSON', '[vc_row][vc_column][vc_video link= »https://youtu.be/KCTxrWK6FlI » align= »center »][/vc_column][/vc_row][vc_row][vc_column width= »1/2&Prime;][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine. C’est vers le centre canadien et capitaine d', '<div ><p>[vc_row][vc_column][vc_video link= »https://youtu.be/KCTxrWK6FlI » align= »center »][/vc_column][/vc_row][vc_row][vc_column width= »1/2&Prime;][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine.</p>
<p>C’est vers le centre canadien et capitaine de l’Université de Saint-Mary&rsquo;s en USports, que le staff sportif s’est penché, <strong>Keith GETSON</strong>, portera les couleurs angloyes.</p>
<p>Âgé de 25 ans, cet attaquant trapu d’1.80m pour 88kg, a fait ses classes juniors dans son pays, au sein de la LHJMQ, la reconnue Ligue de Hockey Junior Majeure du Québec. Durant cinq saisons, il faisait le bonheur des Islanders de Charlottetown avant d’être échangé à Halifax pour terminer son cursus junior.</p>
<p>À la suite de cela, Keith avait eu le privilège d’être invité au camp estival des rookies de la franchise des Rangers de New York en 2019. Une riche expérience pour le jeune canadien à l’époque, avant de poursuivre son chemin en USports, parmi l’une des meilleures universités du pays, à Saint-Mary&rsquo;s. Il y passera trois saisons, pour un total de 77 points en 100 matchs, saison régulière et playoffs confondu. En étant l’un des éléments très importants de son équipe, buteur dans l’âme, il a notamment porté les Huskies, avec 6 points en 7 matchs, vers les quarts de finale du championnat canadien cette saison, défait par une certaine équipe de l’UQTR.</p>
<p>Keith est également un joueur de caractère, qui ne rechigne pas les efforts sur la glace, accompagné d’un leadership qui a fait de lui un capitaine à Saint-Mary&rsquo;s.</p>
<p>Nous sommes donc pleinement satisfaits de le voir rejoindre l’effectif de Pierrick Rézard et Mathieu Cyr dès le mois d’août prochain. En attendant, nous lui souhaitons toutes et tous, la bienvenue à l’Hormadi !</p>
<p>WELCOME HOME KEITH[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F194811%2Fkeith-getson|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_empty_space][vc_single_image image= »16088&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxOTQ4MTElMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM3MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-keith-getson.jpeg', true, '1684404031000', '1774831638322', '1774833441769');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-charles-schmitt', 'Départ de Charles SCHMITT', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, Charles SCHMITT, a préféré donner une nouvelle orientation à sa jeune carrière en évoluant sous un autre chandail au mois de septembre. Arrivé sur la côte basque il ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, <strong>Charles SCHMITT</strong>, a préféré donner une nouvelle orientation à sa jeune carrière en évoluant sous un autre chandail au mois de septembre.</p>
<p>Arrivé sur la côte basque il y a tout juste un an en provenance de <em>Briançon</em>, le défenseur international français de 22 ans, aura disputé 53 matchs pour un total de 27 points sous les couleurs de l’Anglet Hormadi Pays Basque cette saison. Ses performances, lui avaient même permis d’être appelé par Philippe Bozon lors du second rassemblant de l’Équipe de France en décembre dernier. Un diamant, qu’aurait aimé continuer de polir le staff angloy, mais Charles a fait le choix de s’engager chez un prétendant au titre.</p>
<p>Nous respectons sa décision et nous le remercions pour son passage à la Barre tout en lui souhaitant bon courage dans sa nouvelle aventure.</p>
<p>MILESKER CHARLES[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F454898%2Fcharles-schmitt|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16081&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q0NTQ4OTglMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjU2NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-charles-schmitt.jpeg', true, '1684335631000', '1774831639077', '1774833441769');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-maurin-bouvet', 'Arrivée de Maurin BOUVET', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine. Cocorico !🇫🇷🐓 Ce n’est ni plus ni moins, qu’un international Français qui arrive à la Barre, en provenance tout droit des Ducs d’A', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine.</p>
<p>Cocorico !<span >🇫🇷</span><span >🐓</span><br />
Ce n’est ni plus ni moins, qu’un international Français qui arrive à la Barre, en provenance tout droit des Ducs d’Angers,<strong> Maurin BOUVET</strong>, rejoint les rangs basques.</p>
<p>Formé à Amiens, le centre de 27 ans s’était expatrié de l’autre côté de l’Atlantique, aux États-Unis lorsqu’il était en junior à 19 ans. Après deux saisons, Maurin faisait son retour dans l’hexagone sous les couleurs de Gap en 2015, avec qui, il décrochait un titre de champion de France en 2017. Il était également récompensé du trophée Jean-Pierre Graff en 2016, décerné au meilleur jeune joueur de Ligue Magnus.<br />
Depuis, Maurin a continué son parcours à Rouen, puis à Angers lors des trois dernières saisons, dans un rôle important où il aura inscrit 92 points toutes compétitions confondues. Il ajoutera également à son palmarès, une Coupe de France (2022) et une médaille d’argent en Continental Cup en janvier dernier (2023) avec les Ducs.</p>
<p>Du haut de ses 44 sélections en Équipe de France, notamment deux championnats du monde (2017 et 2018) et 376 matchs en Synerglace Ligue Magnus, l’international tricolore a décidé de donner un nouvel élan à sa carrière en s’engageant à l’Hormadi. Il sera assurément, l’une des pierres angulaires de notre offensive à la rentrée prochaine.</p>
<p>Nous sommes donc extrêmement satisfaits d’avoir pu acquérir ses services et très fiers de pouvoir l’accueillir au club. Nous lui souhaitons toutes et tous, la bienvenue et nous avons hâte le voir porter fièrement nos couleurs !</p>
<p>ONGI ETORRI MAURIN[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F113119%2Fmaurin-bouvet|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16027&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxMTMxMTklMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjc5MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-maurin-bouvet.jpeg', true, '1684162853000', '1774831640765', '1774833441770');
