<p>[/vc_column_text][stm_block_quote bq_text= »#1 : Notre prochaine recrue est un international français qui évolue au poste d’attaquant. »][stm_block_quote bq_text= »#2 : Anglet sera le 5 ème club de Magnus de notre nouvelle recrue »][/vc_column][/vc_row]</p>
</div>', 'Jeu concours', '/images/news/decouvre-la-nouvelle-recrue-indice-2-16042.jpg', true, '1684141236000', '1774831643815', '1774833441771');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'decouvre-la-nouvelle-recrue-indice-1-16030', 'Découvre la nouvelle recrue – Indice # 1', '[vc_row][vc_column][vc_single_image image= »16031&Prime; img_size= »full » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_column_text] Tente de gagner une crosse dédicacée de notre nouvelle recrue en trouvant son nom grâce aux 4 indices qui seront publiés sur le site à : 1 er indic', '<div ><p>[vc_row][vc_column][vc_single_image image= »16031&Prime; img_size= »full » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]</p>
