INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'promongation-de-theo-fremond', 'Promongation de Théo FREMOND', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Un jeune défenseur peut en cacher un autre. Nous vous annonçons aujourd’hui la prolongation de contrat d’un pur produit de la formation angloye, THÉO FRÉMOND, poursuit à l’Anglet Hormadi Pays Basque la saison prochaine. Une suite ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Un jeune défenseur peut en cacher un autre. Nous vous annonçons aujourd’hui la prolongation de contrat d’un pur produit de la formation angloye, <strong>THÉO FRÉMOND</strong>, poursuit à l’Anglet Hormadi Pays Basque la saison prochaine.</p>
<p>Une suite logique pour Théo, après une saison 2022-2023 très riche, puisqu’il a disputé 33 rencontres de Synerglace Ligue Magnus sous les ordres de Pierrick Rezard, mais également 20 parties avec l’équipe U20 Élite, dont il était l’un des leaders.<br />
Notre jeune défenseur gaucher, fera définitivement le grand saut la saison prochaine avec l’équipe Magnus afin de passer un cap. Puisque du haut de ses 21 ans bientôt, il ne sera plus apte à évoluer avec l’équipe U20 Élite.</p>
<p>Nous sommes donc très heureux de pouvoir compter sur lui à la rentrée prochaine, et ainsi l’entourer dans le but de le voir se développer convenablement.</p>
<p>LASTER ARTE THÉO[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F362604%2Ftheo-fremond|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16021&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzNjI2MDQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM3MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/promongation-de-theo-fremond.jpeg', true, '1684058442000', '1774831646812', '1774833441774');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-baptiste-manciot-16015', 'Prolongation de Baptiste MANCIOT', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Notre jeune défenseur angloy, BAPTISTE MANCIOT, prolonge l’aventure à l’Anglet Hormadi Pays Basque la saison prochaine. Notre numéro 24, qui s’était montré très à son aise au sein de la défensive basque en fin de saison dernière, ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Notre jeune défenseur angloy, <strong>BAPTISTE MANCIOT</strong>, prolonge l’aventure à l’Anglet Hormadi Pays Basque la saison prochaine.</p>
<p>Notre numéro 24, qui s’était montré très à son aise au sein de la défensive basque en fin de saison dernière, continuera d’arborer la double casquette entre l’équipe Synerglace Ligue Magnus et l’équipe U20 Élite, au sein de laquelle, il détient un rôle majeur.</p>
<p>Avec 22 matchs au compteur dans l’élite lors du précédent exercice, nous sommes extrêmement ravis de voir Baptiste continuer son développement sous nos couleurs. Mais aussi de pouvoir l’accompagner sur le long terme afin qu’il atteigne son plein potentiel.</p>
<p>LASTER ARTE BAT[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F362574%2Fbaptiste-manciot|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16018&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzNjI1NzQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM0MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-baptiste-manciot-16015.jpeg', true, '1683972009000', '1774831647640', '1774833441775');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-dylan-st-cyr', 'Arrivée de Dylan ST-CYR', '[vc_row][vc_column][vc_video link= »https://youtu.be/ADUa4mL1bW0&Prime; align= »center »][/vc_column][/vc_row][vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Chose promise, chose due !🎥 Nous vous laissons découvrir en images, notre tout nouveau portier américain, qui statuera ', '<div ><p>[vc_row][vc_column][vc_video link= »https://youtu.be/ADUa4mL1bW0&Prime; align= »center »][/vc_column][/vc_row][vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Chose promise, chose due !🎥</p>
<p>Nous vous laissons découvrir en images, notre tout nouveau portier américain, qui statuera devant les filets de l’Anglet Hormadi Pays Basque la saison prochaine, en la présence de l’ancien médaillé d’or et champion du monde U18 américain, DYLAN ST. CYR.🥇🇺🇸</p>
<p>Celui qui fêtera ses 24 ans dans une dizaine de jours, quitte les États-Unis afin de traverser l’Atlantique pour sa première expérience en Europe, chez nous, à la Barre. Né dans le Nevada à Las Vegas, Dylan fait partie d’une grande famille de hockeyeurs. Puisque sa mère, est ni plus ni moins que Manon Rhéaume, la première femme à avoir évolué dans la NHL sous les couleurs de Tampa Bay, médaillé d’argent aux Jeux Olympiques de 1998, double championne du monde avec le Canada, et actuellement parmi l’organisation des Kings de Los Angeles en NHL.</p>
<p>En bref, Dylan suit donc les traces de sa mère, puisque ce dernier était le gardien numéro un de la Team USA, lors du sacre de son équipe nationale U18 américaine aux championnats du monde de 2017. Il avait d’ailleurs comme backup, un certain Cayden Primeau, actuel gardien au sein de la franchise des Canadiens de Montréal. Couronné d’or aux côtés de certains gros noms comme Quinn Hughes, Brady Tkatchuk ou encore Josh Norris, Dylan avait également raflé cette année-là, le prix du meilleur portier de la compétition avec un pourcentage de 92.1% d’arrêts.</p>
<p>Ses performances, lui permettaient de poursuivre sa jeune carrière en NCAA, le meilleur championnat universitaire américain. D’abord à Notre Dame, puis à Quinnipiac et enfin la saison dernière, dans la prestigieuse université de Michigan State. Alignant une moyenne de 92.5% d’arrêts et deux titres nationaux (B1G) lors de ces cinq années passées en NCAA, Dylan s’est vu offrir une chance en fin de saison dernière en étant appelé trois fois en AHL. Au sein du club école des Red Wings de Détroit (NHL), les Griffins Grand Rapids. Il y aura disputé une moitié de match, avec un blanchissage à la clé.</p>
<p>Petit par sa taille, mais grand par son talent, nous sommes donc très satisfaits et enchanté de pouvoir l’accueillir à l’Hormadi. Nous lui souhaitons un bel été et nous avons extrêmement hâte de le voir à l’œuvre à la Barre sous nos couleurs.</p>
<p>WELCOME HOME DYLAN[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F233496%2Fdylan-st.-cyr|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »16012&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyMzM0OTYlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQwMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-dylan-st-cyr.jpeg', true, '1683820826000', '1774831648566', '1774833441775');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-matt-robson', 'Départ de Matt ROBSON', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Arrivé en octobre dernier afin de pallier le poste de gardien numéro un, MATTHEW ROBSON, ne fera plus partie de l’effectif de l’Anglet Hormadi Pays Basque la saison prochaine. Le club avait mis en œuvre les efforts nécessaires pou', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Arrivé en octobre dernier afin de pallier le poste de gardien numéro un, <strong>MATTHEW ROBSON</strong>, ne fera plus partie de l’effectif de l’Anglet Hormadi Pays Basque la saison prochaine.</p>
<p>Le club avait mis en œuvre les efforts nécessaires pour conserver Mat lorsque ce dernier avait indiqué son souhait de rester à Anglet une saison supplémentaire. Mais malgré cette volonté commune entre joueur et club de continuer l’aventure, le portier canadien n’a plus donné de nouvelles à plusieurs de nos relances au cours des dernières semaines.</p>
<p>Mat, aura disputé 34 matchs de saison régulière sous nos couleurs, avec notamment des performances notables face aux cadors du championnat. Ainsi que 3 matchs de Coupe de France et 4 parties en playdowns.</p>
<p>Nous le remercions pour son passage au Pays basque, et nous lui souhaitons bonne chance dans ses projets futurs.</p>
<p>MILESKER MAT[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F204278%2Fmat-robson|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15999&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyMDQyNzglMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM1NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-matt-robson.jpeg', true, '1683730830000', '1774831651922', '1774833441775');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-des-freres-larroque', 'Départ des frères LARROQUE', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Ils ne feront plus partie de l’effectif angloy la saison prochaine, la fratrie LARROQUE, ARTHUR notre défenseur international U20, ainsi que son frère aîné et attaquant THÉO, s’envolent tous deux vers de nouveaux horizons en D1. F', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Ils ne feront plus partie de l’effectif angloy la saison prochaine, la fratrie <strong>LARROQUE</strong>, <strong>ARTHUR</strong> notre défenseur international U20, ainsi que son frère aîné et attaquant <strong>THÉO</strong>, s’envolent tous deux vers de nouveaux horizons en D1.</p>
<p>Formés au club dès leur plus jeune âge, <strong>Arthur et Théo</strong> ont découvert ensemble la Synerglace Ligue Magnus en 2021 sous les couleurs de leur club formateur, l’Anglet Hormadi Pays Basque. Permettant notamment à Arthur d’arborer fièrement les couleurs angloyes lors de son titre de champion du monde D1B en 2022, et plus récemment cette saison, lors de sa médaille de bronze D1A avec l’Équipe de France U20. Théo de son côté, a parfaitement su remplir son rôle cette année lorsque les blessures coulaient à flots. Dans son style caractéristique, il n’a jamais rien lâché en faisant preuve de caractère, terminant même avec un splendide dernier but lors de l’ultime match face à Nice. C’est donc avec une petite pointe au cœur mais surtout, avec beaucoup de fierté que nous les voyons prendre leur envol.</p>
<p>Nul doute que ces deux-là feront honneur à la formation angloye au sein de leur future équipe la saison prochaine. Nous les remercions et nous leur souhaitons bonne chance dans cette nouvelle aventure. À très vite les boys !</p>
<p>MILESKER MESSIEURS ![/vc_column_text][vc_btn title= »Elite Prospect Théo » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F457764%2Ftheo-larroque|target:_blank »][vc_empty_space][vc_btn title= »Elite Prospect Arthur » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F362572%2Farthur-larroque|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15991&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]Arthur et Théo, ont bien sûr tenu à vous adresser un dernier petit message[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width= »1/2&Prime;][vc_single_image image= »15994&Prime; img_size= »large » alignment= »center »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15995&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-des-freres-larroque.jpeg', true, '1683558059000', '1774831652932', '1774833441776');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-victor-ranger-15985', 'Prolongation de Victor RANGER', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] C’était son 24e anniversaire ce vendredi, et quoi de mieux que l’annonce de sa resignature pour fêter cela. Vous l’avez tous bien compris, notre attaquant, VICTOR RANGER, continuera de porter le chandail de l’Hormadi la saison pr', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<p ><span >C’était son 24e anniversaire ce vendredi, et quoi de mieux que l’annonce de sa resignature pour fêter cela. Vous l’avez tous bien compris, notre attaquant, VICTOR RANGER, continuera de porter le chandail de l’Hormadi la saison prochaine.</span></p>
<p ><span >Cette année, Vic a su passer un cap en se révélant sous les ordres de Pierrick Rézard et a fait partie des grandes satisfactions de l’offensive angloye. Avec 19 points au compteur en Synerglace Ligue Magnus et 3 points en autant de rencontres en Coupe de France, il a réalisé son meilleur total et donc, sa meilleure production depuis son retour au club en 2020. Dans un rôle différent et sans doute plus important qu’auparavant, amenant à plus de responsabilités sur le front de l’attaque basque, Victor ne s’est pas défilé et a su prendre avec sérieux cette nouvelle étiquette.</span></p>
<p ><span >C’est donc en toute logique que le staff sportif compte pleinement sur notre numéro 18, afin de continuer de lui faire franchir les paliers et devenir à terme, un élément important de l’effectif.</span></p>
<p ><span >Nous lui souhaitons un bel été, et nous sommes toutes et tous, extrêmement ravi de pouvoir le retrouver dès la rentrée prochaine à la Barre. </span></p>
<p ><span >LASTER ARTE VIC</span></p>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F297247%2Fvictor-ranger|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15986&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyOTcyNDclMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjUyMCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-victor-ranger-15985.jpeg', true, '1683367253000', '1774831653720', '1774833441776');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-mathieu-pons', 'Prolongation de Mathieu PONS', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Une nouvelle qui va en ravir plus d’un, nous sommes heureux d’annoncer aujourd’hui, la prolongation de contrat de notre infatigable défenseur, MATHIEU PONS. Vaillant et exemplaire, Poncho entamera sa dixième saison sous les couleu', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Une nouvelle qui va en ravir plus d’un, nous sommes heureux d’annoncer aujourd’hui, la prolongation de contrat de notre infatigable défenseur, MATHIEU PONS.</p>
<p>&nbsp;</p>
<p>Vaillant et exemplaire, Poncho entamera sa dixième saison sous les couleurs de l’Anglet Hormadi Pays Basque la saison prochaine. Notre fidèle guerrier continuera d’être un pilier du vestiaire, tout en multipliant les sacrifices sur la glace, fidèle à lui-même, comme à son habitude dans son rôle de l’ombre si important pour le collectif. De par toute sa générosité, sur et en dehors du glaçon, Mathieu a su s’imposer au fil des années comme un digne représentant des valeurs du club.</p>
<p>&nbsp;</p>
<p>C’est donc avec beaucoup de joie que nous le retrouvons dès le mois d’août à la Barre pour ce nouvel exercice, prêt à défendre corps et âme nos couleurs qui lui sont si chères.</p>
<p>&nbsp;</p>
<p>LASTER ARTE PONCHO[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F114198%2Fmathieu-pons|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15981&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxMTQxOTglMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjY0MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-mathieu-pons.jpeg', true, '1683298802000', '1774831655990', '1774833441776');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-nicolas-arrossamena', 'Prolongation de Nicolas ARROSSAMENA', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Au club depuis notre remontée dans l’élite, notre Saint-Pierrais et numéro dix, NICOLAS ARROSSAMENA, sera toujours parmi les rangs de l’Anglet Hormadi Pays Basque la saison prochaine. Assistant capitaine depuis deux saisons, il co', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Au club depuis notre remontée dans l’élite, notre Saint-Pierrais et numéro dix, <b>NICOLAS ARROSSAMENA</b>, sera toujours parmi les rangs de l’Anglet Hormadi Pays Basque la saison prochaine.</p>
<p>Assistant capitaine depuis deux saisons, il continuera d’être l’un des cadres du vestiaire. Auteur de 20 points lors de la saison régulière cette année, il aura également pour but, d’encadrer nos jeunes pousses angloys du haut de ces 33 ans lors du prochain exercice.</p>
<p>Nous lui souhaitons toutes et tous, un bel été, et nous sommes heureux de pouvoir compter sur lui dès le mois d’août prochain, sur la glace de la Barre.[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F24851%2Fnicolas-arrossamena|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15977&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyNDg1MSUyMiUyMHdpZHRoJTNEJTIyMTAwJTI1JTIyJTIwaGVpZ2h0JTNEJTIyOTQwJTIyJTIwc2Nyb2xsaW5nJTNEJTIybm8lMjIlMjBmcmFtZWJvcmRlciUzRCUyMjAlMjIlM0UlM0MlMkZpZnJhbWU=[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-nicolas-arrossamena.jpeg', true, '1683126008000', '1774831658121', '1774833441776');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-hugo-baron', 'Prolongation Hugo BARON', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nous démarrons ce mois de Mai avec la resignature d’un élément tout particulier de notre effectif. Pur produit du club, notre attaquant et ambianceur du vestiaire, HUGO BARON, continuera l’aventure avec l’Anglet Hormadi Pays Basqu', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nous démarrons ce mois de Mai avec la resignature d’un élément tout particulier de notre effectif.</p>
<p>&nbsp;</p>
<p>Pur produit du club, notre attaquant et ambianceur du vestiaire, <strong>HUGO BARON</strong>, continuera l’aventure avec l’Anglet Hormadi Pays Basque la saison prochaine.</p>
<p>&nbsp;</p>
<p>Pour sa première saison complète en Synerglace Ligue Magnus, notre jeune numéro 14 s’est révélé sous les ordres de Pierrick Rézard. Une progression notable, se distinguant avec trois buts et trois assistances au compteur. Mais surtout, devenu spécialiste de l’infériorité numérique, faisant de lui le joueur le plus utilisé de la ligue dans ce domaine lors du précédent exercice. Son humour débordant et sa joie de vivre également, ne manqueront pas d’animer les travées de la Barre tout au long de la nouvelle saison.</p>
<p>&nbsp;</p>
<p>C’est donc en toute logique que le staff sportif souhaitait conserver Hugo afin qu’il poursuive son développement sous nos couleurs. Nous sommes ravis de pouvoir le retrouver dès la rentrée prochaine, en attendant, nous lui souhaitons toutes et tous, un bel été.</p>
<p>&nbsp;</p>
<p>Hugo vous a d’ailleurs laissé quelques mots (avec le sourire)<a href="https://fb.watch/kfBI7plH-v/" target="_blank" rel="noopener">😁👉</a></p>
<p>&nbsp;</p>
<p>LASTER ARTE HUGO[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F457759%2Fhugo-baron|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15972&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q0NTc3NTklMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjM4NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-hugo-baron.jpeg', true, '1682953206000', '1774831663742', '1774833441777');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-matyas-zelingr', 'Départ de Matyas ZELINGR', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, le défenseur tchèque, MATYAS ZELINGR, n’est pas conservé par le club. Le robuste défenseur de 24 ans faisait escale pour la première fois en dehors de son pays natal', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Il ne fera plus partie de l’effectif angloy la saison prochaine, le défenseur tchèque, <strong>MATYAS ZELINGR</strong>, n’est pas conservé par le club.</p>
<p>Le robuste défenseur de 24 ans faisait escale pour la première fois en dehors de son pays natal cette saison. Arrivé du HC Slavia Prague l’été dernier, l’ex-international junior tchèque, aura disputé 45 rencontres pour un total de 7 points sous les couleurs de l’Hormadi.</p>
<p>Nous le remercions, et nous lui souhaitons bonne chance pour la suite de sa carrière.</p>
<p>MILESKER MATYAS ![/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F236423%2Fmatyas-zelingr|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15968&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyMzY0MjMlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjU4MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-de-matyas-zelingr.jpeg', true, '1682762458000', '1774831666705', '1774833441777');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-samuel-rousseau', 'Arrivée de Samuel ROUSSEAU', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine. Il s’agit de l’attaquant français, SAMUEL ROUSSEAU, qui nous provient tout droit des Scorpions de Mulhouse. Jeune attaquant de 22 ans', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine.</p>
<p>Il s’agit de l’attaquant français, <strong>SAMUEL ROUSSEAU</strong>, qui nous provient tout droit des Scorpions de Mulhouse. Jeune attaquant de 22 ans, Samuel a connu quatre dernières saisons pleines avec le club alsacien en Synerglace Ligue Magnus. Avant ça, il avait déjà goûté à l’élite du hockey français sous les couleurs de son club formateur, l’Étoile Noire de Strasbourg, entre 2017 et 2019. Dotant d’un bon potentiel, il compte de nombreuses sélections en Équipe de France U20 et U18.</p>
<p>Capable d’évoluer au centre de l’offensive comme à l’aile gauche, Samuel fait preuve également de polyvalence dans les deux sens de la glace. En vue sous les ordres de Kévin Hecquefeuille la saison dernière au sein de la formation mulhousienne avec 12 points au compteur et une belle performance en play-offs, le jeune français a décidé de traverser l’hexagone afin de poursuivre sa carrière au Pays basque sous les couleurs de l’Hormadi.</p>
<p>Nous lui souhaitons donc toutes et tous, la bienvenue, et nous sommes ravis de pouvoir l’accueillir à la Barre très prochainement.</p>
<p>ONGI ETORRI SAM[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F363574%2Fsamuel-rousseau|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15965&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzNjM1NzQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjU4MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-samuel-rousseau.jpeg', true, '1682694015000', '1774831667779', '1774833441777');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'vente-aux-encheres-saison-20222023', 'Vente aux enchéres saison 2022/2023', 'Comme chaque fin de saison, nous vous proposons d’acquérir par le biais des enchères les maillots portés des joueurs. Il n’y a pas d’autres moyens de se les procurer, ce sont des exemplaires uniques, portés, dont le gagnant sera le seul possesseur ! Les maillots sont des modèles joueurs et non des m', '
<p>Comme chaque fin de saison, nous vous proposons d’acquérir par le biais des enchères les maillots portés des joueurs. Il n’y a pas d’autres moyens de se les procurer, ce sont des exemplaires uniques, portés, dont le gagnant sera le seul possesseur !</p>
<p>Les maillots sont des modèles joueurs et non des modèles type “réplica”, ils sont donc de grande taille (XL ou XXL).Petite spécificité, il y une attache en bas du dos à l’intérieur des maillots preuve que ses maillots ont vécu (cette attache est exigée pour que les maillots tiennent en place).</p>
<p>Les maillots vous seront proposés à la vente du vendredi 28 avril 2023 16h00 jusqu’au mardi 9 mai 2023 à 16h00 sur Facebook.</p>
<p><em><span ><strong>Règlement :</strong></span></em></p>
<p>Le prix de départ est fixé à 45€.</p>
<p>Le palier minimum pour une enchère est de 5.00€.</p>
<p>Pour enchérir il vous faudra commenter la photo du maillot en question avec le montant de votre enchère. Les montants comprenant des centimes ne sont pas autorisés (pas d’enchères à 60,01€).</p>
<p>Les enchères se termineront le mardi 9 mai 2022 à 16h00. L’heure de référence est celle de Facebook.</p>
<p>Néanmoins, afin d’éviter un engorgement de dernière minute, si une enchère valide est proposée dans les quinze dernières minutes de l’enchère, l’heure de clôture sera repoussée de dix minutes, aussi souvent que nécessaire.</p>
<p><strong>Une fois l’enchère clôturée, les maillots ne pourront être ni repris, ni échangés, ni remboursés.</strong></p>
<p><em><strong>Enchères à distance :</strong></em></p>
<p>Vous pouvez enchérir et remporter un maillot même sans habiter à proximité d’Anglet. Il suffira de rajouter à votre enchère le montant des frais d’envoi en fonction du mode choisi (colis simple, suivi, en recommandé, etc…). Environ 10€ pour un envoi en France.</p>
<p>Les règlements se feront en espèce, par virement ou par chèque.</p>
<p>Pour toutes autres questions veuillez nous contacter à l’adresse contact@hormadi.fr</p>
', 'Vie du Club', '/images/news/vente-aux-encheres-saison-20222023.jpg', true, '1682676931000', '1774831669012', '1774833441778');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-drsquoalexei-polodyan', 'Départ d&rsquo;Alexei POLODYAN', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] C’est avec le cœur gros que nous vous dévoilons ce mercredi son départ. Il ne fera plus partie de l’effectif angloy la saison prochaine, ALEXEI POLODYAN, quitte l’Hormadi pour de nouveaux horizons. Arrivé en novembre 2021 sur la ', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<p >C’est avec le cœur gros que nous vous dévoilons ce mercredi son départ. Il ne fera plus partie de l’effectif angloy la saison prochaine, <strong>ALEXEI POLODYAN</strong>, quitte l’Hormadi pour de nouveaux horizons.</p>
<p >Arrivé en novembre 2021 sur la côte basque, notre virevoltant Russe aux mains et à la chevelure dorée, avait tout de suite démontré tout son talent aux yeux de tous. Devenu rapidement un élément incontournable de l’équipe, « Polo » aura inscrit 55 points en 62 rencontres de Synerglace Ligue Magnus sous notre maillot.<br />
De par toutes ses qualités, il aura gravé de son empreinte les partisans de la Barre durant son passage à Anglet.</p>
<p >L’ex-international junior russe n’a fait qu’éclore aux yeux de l’hexagone. De ce fait, le club souhaitait vivement le conserver, mais malgré les efforts mis en œuvre pour prolonger notre numéro 27, ce dernier a pris la décision de s’engager au sein d’un autre club.</p>
<p >Nous le remercions pour ces deux belles saisons et nous lui souhaitons bonne chance dans sa nouvelle formation.</p>
<p >MILESKER POLO !</p>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F313724%2Falexei-polodyan|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15953&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QzMTM3MjQlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjQxNSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-drsquoalexei-polodyan.jpg', true, '1682521219000', '1774831669893', '1774833441778');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-de-thomas-decock', 'Prolongation de Thomas DECOCK', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] Hey matelots, votre capitaine est de retour à la Barre. À bientôt 37 ans, notre numéro 11 et capitaine, THOMAS DECOCK, enquille pour une 17e saison dans l’élite. Plus besoin de le présenter, vous le connaissez tous. Résident de l', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<div >
<div dir="auto">Hey matelots, votre capitaine est de retour à la Barre.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">À bientôt 37 ans, notre numéro 11 et capitaine, <strong>THOMAS DECOCK</strong>, enquille pour une 17e saison dans l’élite.</div>
<div dir="auto">Plus besoin de le présenter, vous le connaissez tous. Résident de la Barre depuis son plus jeune âge, formé à Anglet et leader incontournable du vestiaire, Thomas continue avec son club de cœur afin d’aider à faire grandir ce groupe.<br />
Auteur de 25 points en 44 parties la saison dernière, Tom, à démontrer qu’il en avait encore sous le patin.</div>
</div>
<div >
<div dir="auto">Il continuera donc de défendre corps et âme le blason de l’Hormadi qui lui est si cher la saison prochaine.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">LASTER ARTE TOM</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F24755%2Fthomas-decock|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15950&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QyNDc1NSUyMiUyMHdpZHRoJTNEJTIyMTAwJTI1JTIyJTIwaGVpZ2h0JTNEJTIyODIwJTIyJTIwc2Nyb2xsaW5nJTNEJTIybm8lMjIlMjBmcmFtZWJvcmRlciUzRCUyMjAlMjIlM0UlM0MlMkZpZnJhbWUlM0UlMEE=[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-de-thomas-decock.jpg', true, '1682348434000', '1774831670960', '1774833441778');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-arnaud-faure', 'Arrivée Arnaud FAURE', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine. En provenance de Gap, finaliste des deux dernières éditions de la Coupe de France, le défenseur français, ARNAUD FAURE, quitte les H', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<div >
<div dir="auto">Nouvelle arrivée au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">En provenance de Gap, finaliste des deux dernières éditions de la Coupe de France, le défenseur français, <strong>ARNAUD FAURE</strong>, quitte les Hautes-Alpes afin de poser ses valises sur la côte basque.</div>
</div>
<div >
<div dir="auto">Âgé de 27 ans, Arnaud est dans la force de l’âge. Il débarque à la Barre pour apporter toute sa sérénité défensive et de la profondeur à l’arrière-garde angloye. Avec ses 1.83m pour 90kg, il possède une belle intelligence de jeu, souvent focus sur la relance et solide à la ligne bleue, Arnaud est un travailleur de l’ombre permettant d’avoir cet équilibre défensif si important.</div>
</div>
<div >
<div dir="auto">Formé à la bonne école de Grenoble, il a également porté les couleurs d’Angers et Épinal en Synerglace Ligue Magnus. Lors des quatre dernières saisons, notre nouveau défenseur gaucher, évoluait chez les Rapaces de Gap. Notre coach, Pierrick Rézard, le connaît parfaitement, puisque ce dernier était assistant coach sur le banc de Gap en 2018 lorsque Arnaud évoluait sous le chandail haut-alpin.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Il rejoint donc les rangs basques pour la saison prochaine. Nous lui souhaitons toutes et tous, la bienvenue et nous sommes extrêmement ravis de pouvoir l’accueillir au club.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">ONGI ETORRI ARNAUD</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F163801%2Farnaud-faure|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15945&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxNjM4MDElMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjYyNSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNFJTBB[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-arnaud-faure.jpg', true, '1682175603000', '1774831671479', '1774833441778');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'arrivee-de-guillaume-duquenne', 'Arrivée de Guillaume DUQUENNE', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] Pour bien finir la semaine, nous vous dévoilons la toute première arrivée et ce nouveau visage au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine. Le staff angloy s’est penché sur un pensionnaire de D1', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<div >
<div dir="auto">Pour bien finir la semaine, nous vous dévoilons la toute première arrivée et ce nouveau visage au sein de l’effectif de l’Anglet Hormadi Pays Basque pour la saison prochaine.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Le staff angloy s’est penché sur un pensionnaire de D1, afin de trouver son gardien français. En la présence de <strong>GUILLAUME DUQUENNE</strong>, qui nous arrive tout droit de Neuilly-sur-Marne.</div>
</div>
<div >
<div dir="auto">À 29 ans, Guillaume dépose ses jambières et sa mitaine à la Barre afin de faire partie de la paire de gardiens qui aura à cœur de protéger au mieux les filets basques. Un portier bien connu de la D1, pour y avoir évolué lors des six dernières saisons en tant que numéro un, dans chacun des clubs dans lequel il est passé, avec une moyenne de 90.3% d’arrêts.<br />
Entre Briançon puis Dunkerque sous les ordres de notre coach Pierrick Rézard, et enfin à Neuilly-sur-Marne la saison dernière où il a disputé les play-offs, Guillaume fait donc son retour en Synerglace Ligue Magnus. Quelques années après avoir goûté à l’élite du hockey français sous les couleurs d’Amiens et Gap lorsqu’il était plus jeune.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Nous sommes ravis de pouvoir l’accueillir au club pour cette nouvelle aventure, et nous lui souhaitons toutes et tous, la bienvenue à l’Hormadi.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">ONGI ETORRI GUILLAUME</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F71701%2Fguillaume-duquenne|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15942&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0Q3MTcwMSUyMiUyMHdpZHRoJTNEJTIyMTAwJTI1JTIyJTIwaGVpZ2h0JTNEJTIyNjg1JTIyJTIwc2Nyb2xsaW5nJTNEJTIybm8lMjIlMjBmcmFtZWJvcmRlciUzRCUyMjAlMjIlM0UlM0MlMkZpZnJhbWUlM0UlMEE=[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Arrivées', '/images/news/arrivee-de-guillaume-duquenne.jpg', true, '1682096407000', '1774831672920', '1774833441779');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-julien-gaubert', 'Départ Julien GAUBERT', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text] Il ne fera plus partie de l’effectif angloy la saison prochaine, le gardien français, JULIEN GAUBERT, n’est pas conservé par le club. Arrivé de Brest en D1 l’été dernier, où il avait été couronné du titre de champion de France de', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]</p>
<div >
<div dir="auto">
<p>Il ne fera plus partie de l’effectif angloy la saison prochaine, le gardien français, <strong>JULIEN GAUBERT</strong>, n’est pas conservé par le club.</p>
</div>
</div>
<div >
<div dir="auto">Arrivé de Brest en D1 l’été dernier, où il avait été couronné du titre de champion de France de D1, Julien aura pris part à 12 rencontres sous nos couleurs cette saison. Nous le remercions pour son investissement et son sérieux, tout en lui souhaitant bonne chance dans ses projets futurs.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">MILESKER JULIEN !</div>
</div>
<p>[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F163393%2Fjulien-gaubert|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15939&Prime; img_size= »large »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxNjMzOTMlMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjU4MCUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Départs', '/images/news/depart-julien-gaubert.jpg', true, '1681916457000', '1774831673444', '1774833441779');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-fabien-kazarine', 'Prolongation Fabien KAZARINE', '[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Arrivé l’été dernier au Pays basque en provenance de Chamonix, notre ailier gauche de 27 ans, FABIEN KAZARINE, fera partie de l’effectif angloy lors du futur exercice. Alias Kaza, il a tout simplement été le joueur français le plu', '<div ><p>[vc_row][vc_column width= »1/2&Prime;][vc_empty_space][vc_column_text]Arrivé l’été dernier au Pays basque en provenance de Chamonix, notre ailier gauche de 27 ans, <strong>FABIEN KAZARINE</strong>, fera partie de l’effectif angloy lors du futur exercice.</p>
<p>Alias Kaza, il a tout simplement été le joueur français le plus productif de l’effectif la saison dernière avec au compteur <strong>30 points en 44 parties</strong>.<br />
Apportant tout son talent offensif et son intelligence de jeu, l’originaire de Compiègne, est très rapidement devenu l’un des atouts majeurs du système de Pierrick Rézard et Mathieu Cyr.<br />
Aucun doute qu’il continuera d’être l’un des fers de lance de notre offensive dès la rentrée prochaine.<br />
C’est donc avec une joie toute particulière que nous pourrons compter sur notre numéro 19 une saison supplémentaire.[/vc_column_text][vc_btn title= »Elite Prospect » style= »3d » color= »primary » link= »url:https%3A%2F%2Fwww.eliteprospects.com%2Fplayer%2F151491%2Ffabien-kazarine|target:_blank »][/vc_column][vc_column width= »1/2&Prime;][vc_single_image image= »15932&Prime; img_size= »large » alignment= »center »][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]JTNDaWZyYW1lJTIwc3JjJTNEJTIyaHR0cHMlM0ElMkYlMkZ3d3cuZWxpdGVwcm9zcGVjdHMuY29tJTJGaWZyYW1lX3BsYXllcl9zdGF0cy5waHAlM0ZwbGF5ZXIlM0QxNTE0OTElMjIlMjB3aWR0aCUzRCUyMjEwMCUyNSUyMiUyMGhlaWdodCUzRCUyMjc3NSUyMiUyMHNjcm9sbGluZyUzRCUyMm5vJTIyJTIwZnJhbWVib3JkZXIlM0QlMjIwJTIyJTNFJTNDJTJGaWZyYW1lJTNF[/vc_raw_html][/vc_column][/vc_row]</p>
</div>', 'Prolongations', '/images/news/prolongation-fabien-kazarine.jpg', true, '1681916437000', '1774831674617', '1774833441779');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'communique-de-presse-la-barre-de-rire', 'Communiqué de presse la Barre de Rire', '[vc_row][vc_column][vc_single_image image= »15928&Prime; alignment= »center »][vc_separator color= »black » border_width= »2&Prime; el_width= »60&Prime; css_animation= »bounceIn »][vc_column_text] COMMUNIQUÉ DE PRESSE [/vc_column_text][vc_separator color= »black » border_width= »2&Prime; el_width= »', '<div ><p>[vc_row][vc_column][vc_single_image image= »15928&Prime; alignment= »center »][vc_separator color= »black » border_width= »2&Prime; el_width= »60&Prime; css_animation= »bounceIn »][vc_column_text]</p>
<h1 >COMMUNIQUÉ DE PRESSE</h1>
<p>[/vc_column_text][vc_separator color= »black » border_width= »2&Prime; el_width= »60&Prime; css_animation= »bounceIn »][vc_column_text]</p>
<h2 >C&rsquo;est l&rsquo;humour à la plage</h2>
<p>[/vc_column_text][vc_column_text]L&rsquo;Anglet Hormadi Pays Basque, organise en collaboration avec la ville d&rsquo;Anglet un festival d&rsquo;humour :</p>
<p>La Barre de rire. Pour l&rsquo;occasion, la patinoire de la Barre à Anglet, déglacée, accueillera des grands noms de l&rsquo;humour. La première édition du festival La Barre de rire aura lieu le <strong>samedi 27 et le dimanche 28 mai 2023</strong>.</p>
<p>Positionner Le Pays Basque sur la scène nationale du rire, tel est notre défi !</p>
<p><strong>Cédric Cazenabe</strong>, président de l&rsquo;Anglet Hormadi Pays Basque, <strong>Xavier Daramy</strong>, directeur de la patinoire d&rsquo;Anglet et <strong>Djamel Hamidi</strong>, directeur artistique ont souhaité positionner le Pays Basque sur la scène nationale du rire. Ensemble, ils ont décidé de créer le festival « La Barre de rire »</p>
<p>Programmation : Week end de la pentecôte 27/28 mai 2023 :</p>
<p><strong>Samedi 27</strong> : Baptiste Lecaplain spectacle « Voir les gens »<br />
<strong>Dimanche 28</strong> : « Booder is Back »<br />
Notre équipe participe également à la mise en scène des jeunes talents de la région avec la création de « L&rsquo;Hormadi Comedy Club »</p>
<p>Anglet, avec sa situation privilégiée au sein du Pays basque, dispose de toutes les infrastructures nécessaires à la réussite et au développement de ce festival.[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width= »1/5&Prime;][/vc_column][vc_column width= »1/5&Prime;][vc_single_image image= »15887&Prime; img_size= »medium » alignment= »center »][/vc_column][vc_column width= »1/5&Prime;][vc_single_image image= »15919&Prime; img_size= »medium » alignment= »center » onclick= »custom_link » img_link_target= »_blank » link= »https://labarrederire.fr/ »][/vc_column][vc_column width= »1/5&Prime;][vc_single_image image= »15886&Prime; img_size= »medium » alignment= »center »][/vc_column][vc_column width= »1/5&Prime;][/vc_column][/vc_row]</p>
</div>', 'Vie du Club', '/images/news/communique-de-presse-la-barre-de-rire.jpg', true, '1679929206000', '1774831675753', '1774833441780');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'fin-de-carriere-de-lionel-tarantino', 'Fin de carrière de Lionel TARANTINO', 'Après 5 ans passés dans notre club, nous annonçons la fin de carrière de Lionel TARANTINO. Son engagement et sa passion pour le hockey ont été exemplaires, et il a su laisser sa marque sur et en dehors de la glace. Tout au long de cette période, il a été un des piliers de l’équipe,…', '<div >
<div dir="auto">Après <strong>5 ans</strong> passés dans notre club, nous annonçons la fin de carrière de <strong>Lionel TARANTINO</strong>.<br />
Son engagement et sa passion pour le hockey ont été exemplaires, et il a su laisser sa marque sur et en dehors de la glace.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Tout au long de cette période, il a été un des piliers de l’équipe, apportant une inspiration constante à ses coéquipiers par sa persévérance et son implication.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Nous remercions Lionel pour ses contributions remarquables au succès de notre équipe, et nous lui souhaitons le meilleur pour ses projets futurs&#8230;</div>
</div>
', 'Départs', '/images/news/fin-de-carriere-de-lionel-tarantino.jpg', true, '1679900454000', '1774831676592', '1774833441780');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'depart-de-michal-gutwald', 'Départ de Michal GUTWALD', 'Après deux ans passés au club, notre joueur tchèque, Michal GUTWALD ne poursuivra pas la saison prochaine à nos côtés. Nous tenons à le remercier d&rsquo;avoir porté nos couleurs pendant 100 matchs. Avant son départ il a tenu à vous adresser ce message : J&rsquo;aimerais profiter de cette occasion p', '<p >Après <strong>deux ans</strong> passés au club, notre joueur tchèque, <strong>Michal GUTWALD</strong> ne poursuivra pas la saison prochaine à nos côtés.<span ><br />
</span>Nous tenons à le remercier d&rsquo;avoir porté nos couleurs pendant <strong>100 matchs</strong>.</p>
<p >Avant son départ il a tenu à vous adresser ce message :</p>
<blockquote>
<p >J&rsquo;aimerais profiter de cette occasion pour remercier la famille de l&rsquo;Hormadi. Malheureusement, il est temps pour ma famille et moi de rentrer à la maison et c&rsquo;était donc mon dernier match devant les supporters de l&rsquo;Hormadi. J&rsquo;apprécie tout le soutien apporté au cours de ces deux saisons, nous nous sommes sentis bien accueillis et nous nous en souviendrons toujours. Merci également au club, à l&rsquo;équipe et aux amis d&rsquo;Anglet.</p>
</blockquote>
<p ><strong>Merci Michal pour ton implication et bonne continuation pour tes projets futurs</strong></p>
', 'Départs', '/images/news/depart-de-michal-gutwald.jpg', true, '1679731258000', '1774831677370', '1774833441780');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-florent-neyens', 'Prolongation Florent NEYENS', 'Après l’annonce de la prolongation de nos deux entraîneurs, Pierrick Rézard et Mathieu Cyr, pour la saison 2023/2024, c’est au tour de notre préparateur physique de suivre leurs traces. Florent NEYENS (31 ans), prolonge également une saison supplémentaire au sein du staff sportif. D’abord joueur/pré', '<div >
<div dir="auto">Après l’annonce de la prolongation de nos deux entraîneurs, Pierrick Rézard et Mathieu Cyr, pour la saison 2023/2024, c’est au tour de notre<strong> préparateur physique</strong> de suivre leurs traces.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto"><strong>Florent NEYENS</strong> (31 ans), prolonge également une saison supplémentaire au sein du staff sportif.</div>
<div dir="auto"></div>
<div dir="auto">D’abord joueur/préparateur avant de raccrocher les patins l’été dernier, il est depuis un an, consacré à temps plein à son rôle de préparateur physique du club.</div>
</div>
<div >
<div dir="auto">Florent Neyens vient donc compléter ce trio derrière le banc basque, qui sera à la tête de la future équipe de l’Anglet Hormadi Pays Basque la saison prochaine en Synerglace Ligue Magnus.</div>
</div>
', 'Prolongations', '/images/news/prolongation-florent-neyens.jpg', true, '1678362074000', '1774831680795', '1774833441781');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-mathieu-cyr', 'Prolongation Mathieu CYR', 'Pierrick Rézard n’est pas le seul à prolonger l’aventure pour la saison 2023/2024. Puisque son assistant coach, Mathieu CYR (37 ans), rempile une année supplémentaire lui aussi. Il entamera lors du prochain exercice, sa quatrième saison sur le banc angloy en qualité d’assistant. Très cérébral, il es', '<div >
<div dir="auto">Pierrick Rézard n’est pas le seul à prolonger l’aventure pour la saison 2023/2024.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Puisque son assistant coach, <strong>Mathieu CYR</strong> (37 ans), rempile une année supplémentaire lui aussi.<br />
Il entamera lors du prochain exercice, sa <span >quatrième saison</span> sur le banc angloy en qualité d’assistant.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Très cérébral, il est la force tranquille du staff sportif. Ancien joueur également de l’Anglet Hormadi Pays Basque de 2010 à 2013 puis de 2016 à 2018, où il avait été notamment couronné du titre de champion de France de D1 lors de la belle épopée en 2018, qui avait permis au club de retrouver l’élite du hockey français.</div>
</div>
', 'Prolongations', '/images/news/prolongation-mathieu-cyr.jpg', true, '1678361917000', '1774831681285', '1774833441781');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'prolongation-pierrick-rezard', 'Prolongation Pierrick REZARD', 'Arrivé à l’Anglet Hormadi Pays Basque il y a presque un an maintenant en provenance de Dunkerque (D1), Pierrick RÉZARD, notre HEAD COAH, prolonge l’aventure une saison supplémentaire. Pour sa première année sur un banc de Ligue Magnus, notre jeune technicien de 33 ans, à récolter la meilleure moyenn', '<div >
<div dir="auto">Arrivé à l’<strong>Anglet Hormadi Pays Basque</strong> il y a presque un an maintenant en provenance de Dunkerque (D1), <strong>Pierrick RÉZARD</strong>, notre HEAD COAH, prolonge l’aventure une saison supplémentaire.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">Pour sa première année sur un banc de Ligue Magnus, notre jeune technicien de 33 ans, à récolter la meilleure moyenne de point par match (1.11) ainsi que le plus grand nombre de points (49). C’est aujourd’hui, le meilleur résultat du club, depuis sa remontée il y a cinq ans.</div>
<div dir="auto"></div>
</div>
<div >
<div dir="auto">C’est donc en toute logique que les dirigeants misent sur la stabilité, en prolongeant leur confiance envers Pierrick RÉZARD, afin de continuer de développer ce process qui est entamé depuis l’été dernier.</div>
</div>
', 'Prolongations', '/images/news/prolongation-pierrick-rezard.jpg', true, '1678350658000', '1774831681819', '1774833441781');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'interview-alexander-nikulin', 'Interview ALEXANDER NIKULIN', '[vc_row gap= »20&Prime;][vc_column width= »1/2&Prime; css= ».vc_custom_1673096529207{background-color: #00654f !important;} »][vc_single_image image= »15843&Prime; img_size= » » alignment= »center »][vc_column_text css= ».vc_custom_1673096900536{margin: 30px !important;} »] POUR CEUX QUI NE TE CONNA', '<div ><p>[vc_row gap= »20&Prime;][vc_column width= »1/2&Prime; css= ».vc_custom_1673096529207{background-color: #00654f !important;} »][vc_single_image image= »15843&Prime; img_size= » » alignment= »center »][vc_column_text css= ».vc_custom_1673096900536{margin: 30px !important;} »]</p>
<p ><span ><strong>POUR CEUX QUI NE TE CONNAISSENT PAS, PEUX-TU TE PRÉSENTER?</strong></span></p>
<p ><span >Je m&rsquo;appelle Alexander Nikulin, numéro 36 et attaquant au sein du club de hockey Hormadi Anglet et je suis originaire de Russie.</span></p>
<p ><span ><strong>QUAND PENSES-TU ETRE DE RETOUR SUR LA GLACE POUR LES MATCHS?</strong></span></p>
<p ><span >Je souhaite reprendre les matchs d&rsquo;ici quelques semaines, actuellement aucune date n&rsquo;est définie mais ça ne saurait tarder.</span></p>
<p ><span ><strong>PEUX-TU NOUS DONNER TES PASSIONS EN DEHORS DU HOCKEY?</strong></span></p>
<p ><span >Le hockey est ma seule passion, mais à côté de ça j&rsquo;aime beaucoup lire.</span></p>
<p>[/vc_column_text][/vc_column][vc_column width= »1/2&Prime;][vc_column_text css= ».vc_custom_1673096929787{margin: 40px !important;} »]</p>
<p ><span ><strong>COMMENT TE SENS TU DEPUIS CES DERNIERES SEMAINES?</strong></span></p>
<p ><span >Je me sens mieux de jour en jour, les séances de rééducation ont été intenses et l&rsquo;ai hâte de reprendre les matchs et la compétition après ces trois mois d&rsquo;arrêt.</span></p>
<p ><span ><strong>AS-TU ÉTÉ EN MESURE DE REPRENDRE L&rsquo;ENTRAÎNEMENT DEPUIS TA BLESSURE ?</strong></span></p>
<p ><span >Effectivement j&rsquo;ai repris progressivement l&rsquo;entrainement avec toute l&rsquo;équipe depuis quelques semaines, mes sensations reviennent et lespère pouvoir reprendre le rythme le plus vite possible.</span></p>
<p ><span ><strong>AVANT DE REJOINDRE LE CLUB D&rsquo;HORMADI, OU JOUAIS TU ?</strong></span></p>
<p ><span >J&rsquo;ai joué en Russie en KHL (ligue continentale de hockey). La saison dernière j&rsquo;ai joué dans le club Tuto à Turku en Finlande.</span></p>
<p ><span ><strong>QUAND PENSES-TU ETRE DE RETOUR SUR LA GLACE POUR LES MATCHS?</strong></span></p>
<p ><span >Je souhaite reprendre les matchs d&rsquo;ici quelques semaines, actuellement aucune date n&rsquo;est définie mais ça ne saurait tarder.</span></p>
<p>[/vc_column_text][/vc_column][/vc_row]</p>
</div>', 'Interview', '/images/news/interview-alexander-nikulin.png', true, '1672999752000', '1774831686002', '1774833441781');
INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'loge-immersion', 'Loge Immersion', '[vc_row][vc_column][vc_column_text] Envie de vivre une expérience unique? Profitez des remises actuelles pour vous offrir une loge pour 8 personnes. Plus d&rsquo;infos auprès du service commercial ici [/vc_column_text][vc_single_image image= »15746&Prime; img_size= »700&#215;700&Prime; alignment= »c', '<div ><p>[vc_row][vc_column][vc_column_text]</p>
