INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'lancer-de-peluches', 'Lancer de peluches', '[vc_section][vc_row][vc_column][vc_column_text] À l&rsquo;occasion du match de noël un lancer de peluches aura lieu sur la glace lors du 1er but de l&rsquo;Hormadi ! En soutient à HAUR ERI on compte sur vous pour venir accompagné de vos plus belles peluches neuves. Ces peluches seront distribuées au', '<div ><p>[vc_section][vc_row][vc_column][vc_column_text]</p>
