INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'communique-de-presse', 'Communiqué de Presse', '[vc_row][vc_column][vc_column_text]Découvrez le communiqué de presse paru le 7 novembre 2022 suite à l&rsquo;assemblée générale du club.[/vc_column_text][vc_single_image image= »15648&Prime; img_size= »full » alignment= »center »][/vc_column][/vc_row]', '<div ><p>[vc_row][vc_column][vc_column_text]Découvrez le communiqué de presse paru le 7 novembre 2022 suite à l&rsquo;assemblée générale du club.[/vc_column_text][vc_single_image image= »15648&Prime; img_size= »full » alignment= »center »][/vc_column][/vc_row]</p>
