INSERT INTO "Article" ("id", "slug", "title", "excerpt", "content", "category", "imageUrl", "published", "publishedAt", "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'source-drsquoemotions-avec-les-enfants-de-plan-cousut', 'Source d&rsquo;émotions avec les enfants de Plan Cousut', '[vc_row][vc_column][vc_column_text]Vendredi 15 février, au retour de leur déplacement de Lyon, les joueurs de l’Hormadi ont pris sur leur temps de repos pour passer un moment de partage avec les enfants de l’IME Plan Cousut. L’institut médico-éducatif est un établissement qui accueille des enfants, ', '<div ><p>[vc_row][vc_column][vc_column_text]Vendredi 15 février, au retour de leur déplacement de Lyon, les joueurs de l’Hormadi ont pris sur leur temps de repos pour passer un moment de partage avec les enfants de l’<strong>IME Plan Cousut</strong>.<br />
L’institut médico-éducatif est un établissement qui accueille des enfants, adolescents et jeunes adultes en situation de handicap.<br />
Il a pour but de leur proposer et mettre en œuvre une éducation, un enseignement, une formation et des soins adaptés qui leur permettent de se préparer à occuper la meilleure place dans notre société en lien avec leurs capacités et leurs besoins.</p>
<p>Cette matinée avait pour but de proposer aux enfants une nouvelle activité afin qu’ils puissent découvrir le hockey sur glace tout en leur permettant  de développer leur motricité, leur capacité de socialisation et leur confiance en soi.</p>
<blockquote><p>Dès leur arrivée les enfants ont eu droit à une visite des lieux puis un échauffement en musique à l’initiative des joueurs. Ce qui a permis de « briser la glace » et de voir des sourires se dessiner sur les visages.<br />
Pour la suite du programme les sensations étaient au rendez-vous ; joie, bonne humeur et émotions pour clôturer cette initiation qui rimait avec réussite !<br />
Le Basa est même descendu de sa montagne pour participer à cette rencontre, l’occasion pour lui aussi de s’initier au patinage.<br />
<i>Florent Neyens</i> attaquant, nous confie : « Ça fait plaisir de partager un moment privilégié avec ces enfants, nous avons vraiment apprécié, c’est incroyable l’énergie qu’ils ont ! »</p></blockquote>
<p><img loading="lazy" decoding="async"  src="https://www.hormadi.fr/wp-content/uploads/2019/02/Summer-ready-tht-is-300x240.png" alt="" width="542" height="434" srcset="https://pro.hormadi.fr/wp-content/uploads/2019/02/Summer-ready-tht-is-300x240.png 300w, https://pro.hormadi.fr/wp-content/uploads/2019/02/Summer-ready-tht-is-768x614.png 768w, https://pro.hormadi.fr/wp-content/uploads/2019/02/Summer-ready-tht-is-128x102.png 128w, https://pro.hormadi.fr/wp-content/uploads/2019/02/Summer-ready-tht-is-32x26.png 32w, https://pro.hormadi.fr/wp-content/uploads/2019/02/Summer-ready-tht-is-143x116.png 143w, https://pro.hormadi.fr/wp-content/uploads/2019/02/Summer-ready-tht-is-98x78.png 98w, https://pro.hormadi.fr/wp-content/uploads/2019/02/Summer-ready-tht-is-600x480.png 600w, https://pro.hormadi.fr/wp-content/uploads/2019/02/Summer-ready-tht-is.png 945w" sizes="auto, (max-width: 542px) 100vw, 542px" />[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][/vc_column][/vc_row]</p>
</div>', 'Vie du Club', '/images/news/source-drsquoemotions-avec-les-enfants-de-plan-cousut.png', true, '1550588977000', '1774831915721', '1774833441834');
